quests[2965] = { id = 2965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omen von Uldum", description = "Ah, {name}, es ist vortrefflich, dass Ihr erneut zu mir gekommen seid. Eure Funde auf der Uldaman-Grabungsstätte haben uns Gelehrten sicherlich einigen Gesprächsstoff geliefert. Ich unterhielt mich also gerade mit einer der Druiden, Nara Wildmane, als mir dämmerte, dass ihre früheren Erfahrungen als Abenteurer von großer Wichtigkeit für unseren nächsten Schritt sein könnten.\n\nIch möchte, dass Ihr mit ihr über ihre Reisen ins Tal der Behüter in der Tanariswüste sprecht. Sie erwartet Euch auf der Anhöhe der Ältesten.", sourceObjective = "Sprecht mit Nara Wildmane auf der Anhöhe der Ältesten in Thunder Bluff.", completion = "Es gibt tief in der Tanariswüste einen Ort, der Tal der Behüter genannt wird. Diese Scheiben, die Ihr geborgen habt... Die Übersetzung ihrer Glyphen erwähnt einen Ort, der Uldum genannt wird. Die meisten denken, dieser Ort sei ein Mythos.\n\nIch weiß, dass dem nicht so ist; Uldum existiert. Ich war dort. Nun... jedenfalls davor.\n\nDas Problem ist Folgendes, {name}: Wir glauben, es gibt eine Verbindung zwischen den Scheiben und Uldum, und wir wollen, dass Ihr dort hingeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[2966] = { id = 2966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mal sehen, was passiert...", description = "Sage Truthseeker und ich würden Euch bitten, die Miniaturscheiben, die Ihr gefunden habt, zu den versiegelten Toren von Uldum zu bringen. Wir... wir sind uns nicht ganz sicher, was dann passieren wird.\n\nDas klingt ein wenig riskant, sicher, das geben wir auch zu. Es könnte allerdings auch gar nichts passieren. Vielleicht müsst Ihr die Scheiben mit etwas benutzen. Vielleicht öffnen sich die Türen, wenn Ihr die Scheiben bei Euch habt. Versucht alles Mögliche und seid bereit für alles, was passieren könnte.\n\nFindet alles heraus, was Ihr könnt, und kehrt dann zu mir zurück. Wir werden dann viel zu bereden haben.", sourceObjective = "Bringt die Miniaturplatinscheiben zu den Toren von Uldum in Tanaris und sucht nach Hinweisen auf die Verbindung zwischen beidem.", progress = "Dieser vertraut aussehende Sockel ragt aus dem heißen Sand heraus. Vielleicht gibt es einen Grund für sein Hiersein...", completion = "Als Ihr den Sockel berührt, summen und glühen die Miniaturplatten von Uldaman in Eurem Rucksack. Eine vertrautes Kribbeln überzieht Eure Hände, als das Bild eines weiteren Steinbeobachters vor den Toren von Uldum zum Leben erwacht.\n\n\"Willkommen. Ich bin der Behüter des Eingangs. Die Scheiben, die für den Zugang verwendet wurden, enthalten nicht die korrekten Zutrittsscheiben, die Platten von Uldum. Bitte fügt diese Platten der Scheibenstruktur hinzu und wiederholt Eure Zugangssequenz. Danke.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[2967] = { id = 2967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Thunder Bluff", description = "Ihr greift erneut auf den Sockel zu und die Platinscheiben erscheinen plötzlich wieder in Eurem Rucksack.\n\nNachdem Ihr das Wissen des Steinbehüters verinnerlicht habt und die Scheiben wieder in Eurem Besitz sind, ist es jetzt an der Zeit, nach Thunder Bluff zurückzukehren und Nara Wildmane von Eurer Entdeckung in Kenntnis zu setzen.", sourceObjective = "Sprecht mit Nara Wildmane in Thunder Bluff.", progress = "Wilkommen zurück, {name}. Habt Ihr die Scheiben zu Eurem Vorteil nutzen können oder war alles vergebens?", completion = "Euch fehlten einige Scheiben? Interessant, es sieht so aus, als wären die Scheiben von Norgannon nur Teile eines vollständigen Satzes - wie Schlüssel auf einem Schlüsselring, wenn Ihr so wollt.\n\nWenn wir die Platten von Uldum finden könnten, hätten wir tatsächlich Zugang zum Uldum-Komplex selbst. Ich weiß nicht, ob ich mich ob dieser Aussichten freuen oder fürchten soll.\n\nWir müssen vielleicht alles riskieren, um sicherzustellen, dass die Geheimnisse der Erde, die uns alle zerstören könnten, genau das bleiben - nämlich Geheimnisse.", sourceObjectiveStatus = "unverified-source-field" }
quests[2968] = { id = 2968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zukünftige Aufgabe", description = "Nun, {name}... Wir scheinen unglücklicherweise in einer Sackgasse zu stecken. Wir wissen, was wir brauchen - die Platten von Uldum -, aber wir haben keinen Schimmer, wo diese sein könnten. Wir werden Nachforschungen darüber anstellen und dann einen soliden Einsatzplan entwickeln. Ich habe ein paar Ideen, wo man mit der Suche anfangen könnte; Ich hege große Hoffnungen, dass wir Euch bald bitten werden, Euch wieder unseren Bemühungen um die Entdeckung der Wahrheit anzuschließen.\n\nSage Truthseeker muss hiervon in Kenntnis gesetzt werden, {name}; zweifellos wird er Euch ebenfalls persönlich dafür danken wollen, dass Ihr noch einmal dem Ruf gefolgt seid.", sourceObjective = "Sprecht mit Sage Truthseeker in Thunder Bluff.", completion = "Wir sind uns demnach alle einig - die beste Vorgehensweise ist es, diese Angelegenheit erst einmal ruhen zu lassen, bis wir die Gebiete, in denen diese Platten versteckt liegen könnten, etwas eingrenzen können. Ihr habt uns so weit gebracht, {name}, und ich hoffe, dass Ihr derjenige sein werdet, der zurück ins Feld geht und den Geheimnissen von Uldum auf den Grund geht!\n\nErlaubt mir, Euch zwischenzeitlich dieses Honorar auszuhändigen. Dies sollte alle Ausgaben decken, die bei unserer Unterstützung angefallen sind, inklusive eines kleinen Bonus. Schaut bald wieder bei uns herein... Uldum ruft uns alle, junger Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[2969] = { id = 2969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für alle Kreaturen", description = "Der dreckige Grimmtotemklan fängt Feendrachen ein, {name}. Jer’kai und ich haben keine Ahnung, was sie mit ihnen vorhaben, aber es ist bestimmt nichts Gutes.\n\nWir sind nicht stark genug, um uns durch das Lager zu kämpfen und die gefangenen Drachen zu befreien, aber mit Eurer Hilfe...\n\nWenn Ihr willens seid und ein paar starke Freunde habt, dann befreit mit diesem Schlüssel die Kreaturen aus ihrem Käfig und stellt sicher, dass sie mit ihrem Leben davonkommen. Ich werde die ganze Zeit an Eurer Seite sein. Jer'kai wird hier bleiben.", sourceObjective = "Befreit mit dem Bambuskäfigschlüssel die Grimmlingflitzer aus dem Pferch im Grimmtotemlager. Kindal Moonweaver sowie mindestens 6 Grimmlingflitzer müssen überleben.\n\nIhr habt 6 Minuten, bis Kindal beschließt, dass es Zeit zum Rückzug und Eure Aufgabe gescheitert ist.", completion = "Dank sei Elune, {name}! Ihr seid ein großer Segen für uns und für die Flitzer, die Ihr gerettet habt. Jer’kai und ich hätten allein den Drachen nicht helfen können - Eure Einmischung in die Angelegenheiten der Grimmtotem wird nicht vergessen werden.\n\nSprecht jetzt mit Jer’kai... Ich muss unseren Vergeltungsschlag vorbereiten. Dass die Feendrachen frei sind, bedeutet nicht, dass es so bleibt. Jer’kai und ich werden jetzt in die Offensive gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2970] = { id = 2970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit üben", description = "Wie sie Euch ja schon mitgeteilt hat, tragen Kindal und ich den Kampf jetzt zu den Grimmtotem. Gemeinsam sollten wir in der Lage sein, einige der Tauren ohne große Gefahr für uns selbst auszuschalten, aber wir würden etwas Hilfe sehr begrüßen, wenn Ihr dazu bereit wärt.\n\nIhr habt das Lager unterhalb von uns ja schon gesehen, aber es gibt mehr davon im Osten. Verwendet Eure eigenen Taktiken, um den Tauren so viel Schaden wie möglich zuzufügen. Wir können uns alle wieder hier treffen, nachdem sie Kindals Pfeile und Eure Waffen geschmeckt haben!", sourceObjective = "Tötet 12 Naturalisten der Grimmtotem, 10 Räuber der Grimmtotem sowie 6 Schamanen der Grimmtotem und kehrt dann zu Jer’kai Moonweaver nach Feralas zurück.", progress = "Kindal benötigt Vorbereitungszeit, aber unsere Verluste gehen bereits in die Dutzende. Der Grimmtotemklan ist sich unserer Anwesenheit in der Gegend wohl bewusst und seine Mitglieder suchen uns wie giftige Vipern.\n\nSie werden alles in ihrer Macht Stehende tun, um uns die Köpfe abzureißen. Seid auf der Hut ... Sie werden jetzt, nachdem Ihr Euch eingemischt habt, auch hinter Euch her sein.", completion = "Kindal hatte Recht, was Euch betrifft, {name}... Ihr habt das richtige Händchen dafür. Ihr seid ein erfahrenerer Abenteurer als wir beide zusammen und dafür danken wir Euch.\n\nDer Grimmtotemklan ist viel feindseliger als die meisten Tauren... Ich frage mich, ob die Tauren die Taten von ihresgleichen missbilligen. Es würde mich nicht überraschen. Wie Euch wahrscheinlich klar sein dürfte, haben viele Völker Azeroths Verbindungen zu weniger freundlichen Zeitgenossen.\n\nDoch darüber reden wir ein andermal.", sourceObjectiveStatus = "unverified-source-field" }
quests[2972] = { id = 2972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit üben", description = "Hier draußen in der Wildnis haben Kindal und ich nur geringe Mittel, um Euch für Eure Hilfe zu entlohnen, aber wir wollen nicht, dass Ihr Euch nicht wertgeschätzt fühlt. Nehmt meinen Siegelring.  Solltet Ihr Euch jemals in Teldrassil wiederfinden, geht zum Tempel des Mondes im Herzen von Darnassus. Dort werdet Ihr meine Hohepriesterin vorfinden, Tyrande Whisperwind. Der Ring wird sie wissen lassen, dass es uns gut geht, und Eure Geschichte untermauern.\n\nWir beide danken Euch, {name}.", sourceObjective = "Bringt Jer’kais Siegelring zu Hohepriesterin Tyrande Whisperwind nach Darnassus.", progress = "Hallo, Kindchen. Es freut uns, mächtige Abenteurer hier im Tempel zu haben. Wenn Ihr die Zeit findet, würdet Ihr mit den jüngeren Abenteurern die eine oder andere Geschichte teilen? Ich weiß, dass einige von ihnen von Eurer Weisheit profitieren könnten.\n\nIch bin untröstlich, wie unhöflich von mir. Ihr kamt in den Tempel, um unsere Hilfe zu ersuchen, und ich stelle Ansprüche an Euch. Bitte, verzeiht mir. Sagt mir, was die Diener des Lichts für Euch tun können.", completion = "Das ist eine erstaunliche Geschichte, {name}. Es freut uns, dass Ihr nicht nur den Drachen, sondern auch einer unserer Priesterinnen geholfen habt. Jer’kai hatte Recht, Euch zu mir zu schicken. Ich werde dafür sorgen, dass sie ihren Ring wiederbekommt - ich entsende ohnehin demnächst einige Späher in Richtung Feralas. Das wird eine weitere Sache sein, die sie auf ihrer Mission überprüfen können.\n\nDanke noch einmal, macht es Euch bitte bequem, solange Ihr hier seit.", sourceObjectiveStatus = "unverified-source-field" }
quests[2973] = { id = 2973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmer für einen neuen Umhang", description = "Grüße, {class}. Ich bin mit meinen Gefährten auf einer Mission für unsere Meister aus Orgrimmar hinunter nach Feralas gereist.\n\nMeine Lebensgefährtin Korrin liebt neue Kleider und daher habe ich vor, ihr einen neuen Umhang zu fertigen, der mit den hauchzarten Flügeln von Feendrachen geschmückt ist. Seid Ihr vielleicht in der Lage, mir zu helfen? Grimmlingflitzer mit prachtvollen Flügeln, wie ich sie will, gibt es westlich vom Camp Mojache.", sourceObjective = "Bringt 10 regenbogenfarbene Grimmlingflitzerflügel zu Krueg Skullsplitter nach Camp Mojache.", progress = "Die Grimmlingflitzer können gefährliche Tierwesen sein, wenn man sie provoziert. Seid vorsichtig im Umgang mit ihnen, {class}. Und passt noch viel mehr auf etwaige Nachtelfen in der Gegend auf. Diese lästigen Narren überfallen einen gern in den Wäldern.\n\nWenn Ihr genug Flügel habt, lasst es mich wissen, ich werde Euch sicher gut entlohnen!", completion = "Wunderbar, {class}! Die sind perfekt. Das sind genug, um einen Umhang für Korrin zu fertigen und vielleicht noch anderes! Danke.\n\nIch hoffe, die Reise war nicht zu gefährlich... Das Gebiet von Feralas ist nicht gerade als harmlos bekannt, aber Ihr habt Euch offensichtlich recht gut geschlagen.\n\nNochmals danke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[2974] = { id = 2974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausige Entdeckung", description = "Was!? Ihr seid in dieser Gegend auf Tauren getroffen? Ihr macht Witze! Wie sahen sie aus?\n\nDer Grimmtotemklan! Ihr habt einige von denen gefunden? Belgrom, einer unserer Meister, interessiert sich für diese Sippe... Er hat sogar ein Kopfgeld auf sie ausgesetzt.\n\nIhr müsst wieder zurückgehen, {class}. Geht zurück und bringt mir ihre Hörner... haufenweise, wenn Ihr könnt. Mit den Grimmtotem ist nicht zu spaßen und man sollte sie nicht unterschätzen. Geht zurück und erschlagt sie; lasst die Flüsse in Feralas rot werden von ihrem dunklen Blut.", sourceObjective = "Bringt 20 Grimmtotemhörner zu Krueg Skullsplitter nach Camp Mojache.", progress = "Nehmt meine Worte ernst, {class}, der Grimmtotemklan ist böse. Wenn Ihr seinen Aufenthaltsort herausgefunden habt, dann ist es an Euch, zurückzukehren und den ersten Schlag gegen ihren Klan zu führen... bevor er in unser eigenes Land kommt und unsere Dörfer auslöscht oder unser Land plündert.", completion = "Das sind gute Hörner, {class}. Gut gemacht. Ich nehme sie Euch ab und werde Belgrom garantiert davon berichten, sobald wir nach Orgrimmar zurückkehren. Ihr habt mir jetzt schon zweimal geholfen und dafür habt Ihr meine Anerkennung. Vielleicht kann ich Euch in Zukunft einmal helfen! Viel Glück noch für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[2975] = { id = 2975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oger von Feralas", description = "Der Einfluss des Ogerstamms der Gordunni sind in diesem Gebiet kaum zu übersehen. Schaut Euch mal um, {name}. Seine bloße Anwesenheit zeichnet das Land. Wir müssen die Gordunni zurückdrängen, bevor sie sich weiter nach Feralas hinein ausbreiten können.\n\nFolgt dem Fluss nach Norden und Ihr werdet ihren Außenposten finden. Verringert ihre Zahl, {name}. Wir müssen ihnen klar machen, dass ihre Art hier nicht willkommen ist.", sourceObjective = "Rok Orhan im Camp Mojache will, dass Ihr 10 Oger der Gordunni, 10 Magier der Gordunni und 5 Schläger der Gordunni tötet.", completion = "Ausgezeichnet, {name}. Zur rechten Zeit wird das Land heilen. Wir dürfen nicht aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[2976] = { id = 2976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausige Entdeckung", description = "Was?!\n\nHm, ich hab wohl wirklich ein Kopfgeld erwähnt, nicht wahr? Gut, das wird mich lehren, meinen Mund nicht zu weit aufzureißen, oder?\n\nIhr habt die Arbeit gemacht, also ist es wohl nur fair, wenn Ihr den größten Lohn einheimst. Nehmt die Hörner, ich lasse sie für Euch in eine Kiste packen. Findet Belgrom Rockmaul im Tal der Ehre. Er wird wissen wollen, was Ihr gesehen habt, und Euch für Eure harte Arbeit belohnen.\n\nMacht es gut, {class}, und danke noch einmal für alles, was Ihr getan habt.", sourceObjective = "Bringt die Kiste mit Grimmtotemhörnern zu Belgrom Rockmaul nach Orgrimmar.", progress = "Fasst Euch kurz, {class}, ich habe heute noch einiges zu erledigen.", completion = "Die Grimmtotem!? Das ist interessant. Ihr sagt, Ihr seid ihnen auf der Jagd in Feralas begegnet? Wirklich?\n\nMeine Partner werden Eure Neuigkeiten hören wollen, {class}. Erzählt mir mehr und ich werde derweil Eure Münzen abzählen.\n\nUnd bevor Ihr geht, wisset, dass ich Euch für die Informationen danke, die Ihr an diesem Tag an mich weitergegeben habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[2977] = { id = 2977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Ironforge", description = "Ihr greift erneut auf den Sockel zu und die Platinscheiben erscheinen plötzlich wieder in Eurem Rucksack.\n\nNachdem Ihr das Wissen des Steinbehüters verinnerlicht habt und die Scheiben wieder in Eurem Besitz sind, ist es jetzt an der Zeit, nach Ironforge zurückzukehren und die Forscherliga von Eurer Entdeckung in Kenntnis zu setzen.", sourceObjective = "Sprecht mit Historiker Karnik in Ironforge.", progress = "Willkommen zurück, {name}. Habt Ihr die Scheiben zu Eurem Vorteil nutzen können oder war alles letzten Endes nur Zeitverschwendung?", completion = "Euch fehlten einige Scheiben? Interessant, es sieht so aus, als wären die Scheiben von Norgannon nur Teile eines vollständigen Satzes - wie Schlüssel auf einem Schlüsselring, wenn Ihr so wollt.\n\nWenn wir die Platten von Uldum finden könnten, hätten wir tatsächlich Zugang zum Uldum-Komplex selbst! Stellt Euch nur vor, den Ort zu erforschen, an dem die Schöpfer gearbeitet haben, und das, ohne eine riesige Schaufel mitzunehmen.\n\nNicht, dass an einer Schaufel etwas falsch wäre ... oder am Graben ...", sourceObjectiveStatus = "unverified-source-field" }
quests[2978] = { id = 2978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gordunnischriftrolle", description = "Ihr hebt die verschmutzte Schriftrolle auf und bemerkt, dass sie eine Art Versammlung oder Zermonie darstellt. Rok Orhan wird sich für diese Schriftrolle, und was sie für die Gordunni bedeutet, interessieren.", sourceObjective = "Bringt die Gordunnischriftrolle zu Rok Orhan ins Camp Mojache.", progress = "Was ist das?", completion = "Diese Schriftrolle... Ihr habt sie im Außenposten der Gordunni gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[2979] = { id = 2979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Zeremonie", description = "Dies scheinen Pläne für eine Art dunkle Zeremonie zu sein, {name}. Soweit ich das erkennen kann, wird dieses Ritual von den Magierlords der Gordunni ausgeführt.\n\nFindet einen dieser Magierlords und sammelt eine Kugel von ihm.\n\nDie Kugel eines Magiers enthält große Macht und wird uns dabei helfen, mehr über diese Zeremonie und die Magie, die die Gordunni beherrschen, herauszufinden.", sourceObjective = "Rok Orhan im Camp Mojache will, dass Ihr eine Gordunnikugel findet.", progress = "Wir müssen mehr darüber herausfinden, warum die Gordunni hier sind, {name}.", completion = "Diese Kugel wird uns mehr Informationen über die Gordunni geben... die wir dann verwenden werden, um ihren Untergang zu planen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[2980] = { id = 2980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oger von Feralas", description = "Jetzt, da Ihr bewiesen habt, dass Ihr ein wahrer Kämpfer seid, vertraue ich darauf, dass Ihr den Mut besitzt, mit der vorliegenden Aufgabe weiterzumachen.\n\nReist in die obere Wildnis südwestlich von hier. Dort gibt es einige verlassene und zerstörte Gebäude auf dem Land, das einst den Nachtelfen gehörte. Sucht nach diesen Ruinen, und wenn Ihr verwelkte Bäume und entweihtes Gelände seht, dann werdet Ihr die Gordunni finden. Drängt sie zurück.\n\nDiese Oger sind viel stärker als diejenigen, denen Ihr bisher entgegengetreten seid, {name}. Seht Euch vor.", sourceObjective = "Rok Orhan im Camp Mojache will, dass Ihr 10 Schamanen der Gordunni, 10 Hexenmeister der Gordunni und 5 Raufer der Gordunni tötet.", completion = "Ihr habt Euch als ein vertrauenswürdiger und verlässlicher Verbündeter erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[2981] = { id = 2981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bedrohung in Feralas", description = "Feralas ist der ideale Ort für jemanden mit Eurer Erfahrung, {class}, der sich selbst beweisen will. Ein Stamm von Ogern, die sich Gordunni nennen, ist die vorherrschende Militärmacht dort, und ihre Zahl wächst. Sie müssen aufgehalten werden, bevor sie unsere Anwesenheit in Feralas bedrohen.\n\nEine mir bekannte Kriegerin mit Namen Rok Orhan lebt im Camp Mojache in Feralas; geht zu ihr. Sie wird Euch mehr über die Situation erzählen, wenn Ihr dort ankommt.", sourceObjective = "Belgrom Rockmaul will, dass Ihr mit Rok Orhan im Camp Mojache sprecht.", completion = "Belgrom hat Euch also hergeschickt. Ihr kommt gerade rechtzeitig, {race}.\n\nLasst mich die Situation erklären und dann könnt Ihr entscheiden, ob Ihr Euch der Herausforderung gewachsen fühlt... Doch wenn Belgrom Euch geschickt hat, dann besteht sicher kein Zweifel an Eurem Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[2982] = { id = 2982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die obere Wildnis", description = "Obwohl es gefährlich ist, haben Troyas und ich die Ruinen erforscht, die in den Wäldern von Feralas zu finden sind.\n\nIn jüngster Zeit ist Troyas jedoch oft allein in die obere Wildnis gegangen und ich mache mir Sorgen um ihn. Die Oger der Gordunni haben dieses Gebiet besetzt und sie reagieren nicht sehr freundlich auf jemanden, der ihr Territorium betritt.\n\nIch hoffte, dass Ihr vielleicht zu den Ruinen im Südosten reisen und einige der Oger beseitigen würdet. Macht es ein wenig sicherer für meinen Troyas und ich werde Euch sehr dankbar sein.", sourceObjective = "Angelas Moonbreeze will, dass Ihr 8 Hexenmeister der Gordunni, 8 Schamanen der Gordunni und 8 Schläger der Gordunni tötet.", completion = "Ich bin sehr dankbar, dass Ihr das für mich tun konntet.\n\nAber bitte kein Wort darüber zu Troyas...", sourceObjectiveStatus = "unverified-source-field" }
quests[2983] = { id = 2983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Es ist eine Weile her, seit Ihr zuletzt geprüft wurdet, {name}. Ihr wart in Euren Studien bisher sehr geduldig, doch es ist an der Zeit, dass Ihr etwas über größere Mächte erlernt... Es ist an der Zeit, dass Ihr wahre Macht erfahrt. Das Element des Feuers ist Euer, wenn Ihr bereit seid, dafür zu bezahlen.\n\nSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich von Crossroads, aber gebt Acht... wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.", sourceObjective = "Sucht Kranal Fiss im Brachland.", completion = "Hmmm, hat Swart Euch geschickt, ja?\n\nNun denn, Swart kann man immer vertrauen. Das bedeutet, dass Ihr bereit seid, Euer nächstes Sapta zu nehmen, das Feuersapta.\n\nIch sehe es schon in Euren Augen, das Lodern, das Verlangen. Ihr habt von der Macht gekostet und seid jetzt bereit für mehr. Geduld, {name}. Vergesst nicht, was Euch die Erde lehrte. Macht und Zerstörung werden sicherlich kommen, dennoch müsst Ihr wissen, wann Ihr Euch zurückhalten solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[2984] = { id = 2984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, {name}. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über Zerstörung zu lernen... und über Chaos. Ihr könnt das Element des Feuers verstehen lernen, wenn Ihr bereit seid, dafür zu bezahlen.\n\nSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich von Crossroads, aber gebt Acht, wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.", sourceObjective = "Sucht Kranal Fiss im Brachland.", completion = "Hmmm, hat Narm Euch geschickt, ja?\n\nNun denn, Narm kann man immer vertrauen. Das bedeutet, dass Ihr bereit seid, Euer nächstes Sapta zu nehmen, das Feuersapta.\n\nIch sehe es schon in Euren Augen, das Lodern, das Verlangen. Ihr habt von der Macht gekostet und seid jetzt bereit für mehr. Geduld, {name}. Vergesst nicht, was Euch die Erde lehrte. Macht und Zerstörung werden sicherlich kommen, dennoch müsst Ihr wissen, wann Ihr Euch zurückhalten solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[2985] = { id = 2985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Ihr seht aus, als wäret Ihr bereit für die nächste Prüfung, {name}. Ihr wart bislang geduldig in Euren Studien, doch die Zeit ist gekommen, da Ihr mehr erlernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu erlernen.\n\nSucht nach Islen Waterseer im Brachland. Sie befindet sich an der Ostküste, südlich von Ratchet und dem Südstrom. Ihr findet sie in ihrer Angelhütte. Viel Glück, {name}.", sourceObjective = "Sucht Islen Waterseer im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[2986] = { id = 2986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, {name}. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu lernen.\n\nSucht nach Islen Waterseer im Brachland. Sie befindet sich an der Ostküste, südlich von Ratchet und dem Südstrom. Ihr findet sie in ihrer Fischerhütte. Viel Glück, {name}.", sourceObjective = "Sucht Islen Waterseer im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[2987] = { id = 2987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordunnikobalt", description = "Ich bin gerade erst hier in Feralas angekommen und habe gehört, dass die Oger der Gordunni, die die Wildnis hier bewohnen, einige interessante Mineralien besitzen. Keiner weiß, was die so vorhaben, aber sie passen höllisch gut auf dieses Zeug auf! Sie lassen es nicht einfach herumliegen. Oh nein, sie vergraben es, damit Leute wie ich es nicht in die Finger bekommen.\n\nWenn Ihr wollt, gebe ich Euch meine Schaufel. Geht zum Außenposten der Gordunni nördlich von hier und grabt mir etwas Gordunnikobalt aus. Haltet nach blauem Glühen Ausschau und fangt dann dort an zu graben!", sourceObjective = "Orwin Gizzmick im Camp Mojache will 12 Proben Gordunnikobalt.", progress = "Los jetzt, macht Euch auf den Weg und fangt an zu graben!\n\nIch muss noch andere Orte besuchen und andere Leute treffen - Zeit ist Geld!", completion = "Perfekt! Ich werde das auf meinen weiteren Reisen mitnehmen, {name}. Ich bin sicher, dass ich jemanden finden kann, der eine hübsche Summe für dieses Kobalt zahlen wird.\n\nHier, nehmt dies für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2988] = { id = 2988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käfige der Witherbark", description = "Der Sohn unseres mächtigsten Greifen ist verschwunden! Sturmschwinges Erbe, Scharfschnabel, ging vor ein paar Tagen bei der Jagd mit seinen Eltern verloren und wir glauben, dass die Trolle ihn geschnappt haben.\n\nIhr müsst uns helfen! Durchsucht die Käfige in den beiden Dörfern der Witherbarktrolle, um herauszufinden, ob Scharfschnabel dort ist.", sourceObjective = "Durchsucht die Käfige in den beiden Dörfern der Witherbark und kehrt dann zu Greifenmeister Talonaxe zurück.", progress = "Habt Ihr die Käfige durchsucht, {name}? Wir müssen Scharfschnabel finden!", completion = "Scharfschnabel war nicht in den Dörfern? Hm... Das ist eine schlimme Nachricht. Dieser Greif ist dazu bestimmt, die nächste Greifengeneration anzuführen. Wenn er verloren ist, werden die Stärke und der Geist unserer Flotte deutlich in Mitleidenschaft gezogen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2989] = { id = 2989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Altar von Zul", description = "Scharfschnabel war nicht bei den Witherbarktrollen. Vielleicht haben ihn die Vilebranchtrolle geholt. Geht zum Altar von Zul am Westrand des Territoriums der Vilebranch und sucht nach dem Greifenjungen.", sourceObjective = "Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Talonaxe zurück.", completion = "Scharfschnabel war nicht dort? Das sind schlechte Nachrichten, aber gleichzeitig auch gute...\n\nEs ist gut, dass er nicht am Altar von Zul war, denn die Trolle der Vilebranch sind dafür bekannt, Opferungen durchzuführen.\n\nIch danke Euch für all Eure Hilfe, aber ich fürchte, ich habe noch eine weitaus größere Aufgabe an der Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[2990] = { id = 2990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thadius Grimshade", description = "Bringt diese Feder zum Rutengänger Thadius Grimshade. Er verließ vor Jahren Aerie Peak, um sich dunklerem Wissen zuzuwenden, aber in seinem Herzen ist er immer noch ein Wildhammer!\n\nUnd vielleicht können uns seine Talente dabei helfen, Scharfschnabel zu finden.\n\nDiese Feder stammt aus dem Nest, in dem das Greifenjunge schläft. Wenn Ihr sie Thadius gebt, kann er mit etwas Glück seine Rutengangmagie verwenden, um Scharfschnabel zu finden.\n\nViel Glück, {name}. Ihr werdet Thadius in den verwüsteten Landen finden, im Magierturm der Burg Nethergarde.", sourceObjective = "Bringt Scharfschnabels Feder zu Thadius Grimshade in die verwüsteten Lande.", progress = "{name}, Ihr bringt mir ein Geschenk?", completion = "Oh, ja. Diese Feder gehört einem schönen Greifen. Einem, der für große Taten bestimmt ist... wenn er unbeschadet seine Kindheit übersteht.\n\nIhr wollt ihn finden? Dann hört genau zu, tapferer {class}...", sourceObjectiveStatus = "unverified-source-field" }
quests[2991] = { id = 2991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nekrums Medaillon", description = "Ich werde herausfinden, wo Euer Greif ist, aber erst müsst Ihr etwas für mich tun. Es gibt da einen Troll in Zul'Farrak, Nekrum der Ausweider, der ein Medaillon besitzt, das ich wirklich gern studieren würde. Bringt mir das Medaillon und ich werde meine Kräfte dafür verwenden, Scharfschnabel zu finden.\n\nZul’Farrak ist jenseits des Ozeans, im Westen, in der Wüste von Tanaris.", sourceObjective = "Bringt Thadius Grimshade in den verwüsteten Landen Nekrums Medaillon.", progress = "Habt Ihr Nekrums Medaillon, {name}? In ihm liegen Kräfte, die ich gern enträtseln würde.", completion = "Ah, das Medaillon von Nekrum. Man sagt, es habe dem Troll ein unnatürlich langes Leben beschert - zu einem hohen Preis. Ich hoffe, einen Weg zu finden, die Macht des Medaillons zu nutzen und dabei seine... unangenehmen Nebenwirkungen zu vermeiden.\n\nIhr habt mir einen großen Dienst erwiesen, {name}. Ich werde jetzt meinen Teil der Abmachung einlösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2992] = { id = 2992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rutengang", description = "Lasst mir etwas Platz, während ich ein Rutengangritual durchführe. Ich werde die Verbindung zwischen der Feder, die Ihr mir gebracht habt, und ihrem Besitzer herstellen und dann selbst dieser Verbindung zu Scharfschnabel folgen.\n\nZumindest... wenn alles nach Plan verläuft. Wenn nicht, nun... dann schließt Ihr besser die Augen.", sourceObjective = "Wartet, bis Grimshade das Rutengangritual durchgeführt hat.", completion = "Das Ritual verlief erfolgreich. Ich habe Scharfschnabel gesehen und kann Euch sagen, wie Ihr ihn findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[2993] = { id = 2993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr ins Hinterland", description = "Scharfschnabel wird in einem Käfig hoch oben auf einer Klippe am Gipfel des Jintha’Alor im Hinterland gefangen gehalten. Der Schlüssel zu diesem Käfig ist im Besitz der Hohepriesterin der Vilebranchtrolle, der üblen Priesterin Hexx.\n\nDa. Ich habe meinen Teil erfüllt. Ich wünsche Euch Glück, {name}.", sourceObjective = "Sprecht mit Greifenmeister Talonaxe.", completion = "Ihr habt mit Grimshade gesprochen? Was hat er gesagt?\n\n... Was? Die Vilebranchtrolle haben Scharfschnabel? Das ist unerträglich! Wir müssen eine Truppe zusammenstellen, um ihn zurückzuholen!", sourceObjectiveStatus = "unverified-source-field" }
quests[2994] = { id = 2994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharfschnabels Rettung", description = "Wir müssen Scharfschnabel retten!\n\nKämpft Euch bis zum Gipfel von Jintha’Alor im Herzen des Vilebranchterritoriums vor, holt Euch den Schlüssel zu Scharfschnabels Käfig von der üblen Priesterin Hexx und dann sucht und befreit Scharfschnabel.", sourceObjective = "Kämpft Euch bis zum Gipfel von Jintha’Alor durch, tötet die üble Priesterin Hexx, um an den Schlüssel zu Scharfschnabels Käfig zu kommen, und rettet Scharfschnabel.", completion = "Swiftwind und Keenclaw sind gerade mit ihrem Jungen zurückgekehrt und machen dabei ein Aufhebens wie frisch gebackene Eltern. Sie wiedervereint zu sehen, das treibt selbst diesem alten Zwerg hier ein paar Tränen in die Augen...\n\nWir können Euch gar nicht genug für das danken, was Ihr getan habt, {name}. Die Greife vom Aerie Peak und ihre Reiter werden Euren Namen für lange, lange Zeit singen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2995] = { id = 2995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachrichtenwege", description = "Die Quel'Danil-Hütte ist ein Zentrum der Kommunikation für die Hochelfen des Hinterlands. Ihre Botschafter sind damit beschäftigt, Beziehungen zu anderen Völkern zu knüpfen, mit denen sie ihr Wissen über die Trolle der Witherbark teilen, die das Gebiet im südlichen Hinterland bewohnen. Alle Aufzeichnungen betreffs dieses Nachrichtenaustauschs werden in der Hütte aufbewahrt.\n\nWir können es nicht brauchen, wenn die Hochtalelfen Allianzen mit anderen schließen, {name}.\n\nVernichtet die Hochtaldokumente. Wir müssen ihre Nachrichtenwege niederbrennen... im wahrsten Sinne des Wortes.", sourceObjective = "Oran Snakewrithe in Undercity will, dass Ihr ins Hinterland reist und die Hochtalaufzeichnungen, Hochtalberichte und Hochtalnotizen verbrennt.", completion = "Perfekt, {name}. Während die Hochtalelfen damit beschäftigt sind, ihre verlorenen Informationen wiederzuerlangen, können wir sie noch weiter abschotten...", sourceObjectiveStatus = "unverified-source-field" }
quests[2996] = { id = 2996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Strahad", description = "Ich habe Euch in der Vergangenheit viele Fertigkeiten beigebracht, aber es ist an der Zeit, dass Euch ein anderer lehrt. Er lebt in Ratchet und sein Name ist Strahad. Er ist ein Mensch, aber lasst Euch deswegen nicht dazu hinreißen, ihn für schwach zu halten. Er mag klein sein, aber er ist auch mächtig. Er kann Euch mächtigere Beschwörungen lehren - ich fühle, dass Ihr dazu bereit seid. Geht nun zu ihm. Er ist in Ratchet... Über der Hafenstadt gleich bei seinem Turm.", sourceObjective = "Sprecht mit Strahad Farsan in Ratchet.", completion = "Ein geschäftiger Tag in Ratchet, nicht wahr? Ich liebe es, dem Treiben einer Hafenstadt zuzusehen. So viel Wundersames, so viel Abenteuer... so viel Ignoranz.\n\nSehe ich da Hass in Euren Augen, {name}? Gut, wir werden daraus einen Vorteil ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2997] = { id = 2997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Offenbarung", description = "Hallo, {name}. Ich weiß, Ihr seid damit beschäftigt, den Leuten von Dun Morogh zu helfen, aber wenn Ihr etwas Zeit habt, könntet Ihr Euch auf den Weg nach Ironforge hinauf machen, um mit einer unserer am meisten Respektierten zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von einem erwartet wird.\n\nIhr könnt sie oben in der Halle der Mysterien finden. Falls Ihr noch nie dort wart, das ist im Mystikerviertel. Viel Glück, {name}.", sourceObjective = "Sprecht mit Tiza Battleforge in Ironforge.", completion = "Grüße, {name}. Ich hoffe, das Licht zeigt Euch den wahren Pfad und schützt Euch vor dem Bösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2998] = { id = 2998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Offenbarung", description = "Seid gegrüßt, <Bruder/Schwester>. Duthorian Rall, einer unserer einflussreichsten Paladine, hat kürzlich von Euch gesprochen. Ich habe mitbekommen, wie er darüber sprach, dass es an der Zeit sei, dass Ihr ein wenig getestet würdet... Dabei fielen auch einige Komplimente darüber, wie gut Ihr bisher abgeschnitten habt.\n\nWenn ich Ihr wäre, würde ich nach Stormwind gehen und mit ihm sprechen, sobald Ihr Zeit habt. Ich bin sicher, er ist in der Kathedrale des Lichts - dort verbringt er einen Großteil seiner Zeit.", sourceObjective = "Sprecht mit Duthorian Rall in Stormwind.", completion = "Ist es nicht wunderschön hier in Stormwind?\n\nEure Ankunft hätte nicht besser sein können, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[2999] = { id = 2999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Offenbarung", description = "Hallo, {name}. Ich weiß, Ihr seid damit beschäftigt, den Leuten von Dun Morogh zu helfen, aber wenn Ihr etwas Zeit habt, könntet Ihr nach oben gehen, um mit einer unserer am meisten Respektierten zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von einem erwartet wird.", sourceObjective = "Sprecht mit Tiza Battleforge in Ironforge.", completion = "Grüße, {name}. Ich hoffe, das Licht zeigt Euch den wahren Pfad und schützt Euch vor dem Bösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3000] = { id = 3000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Offenbarung", description = "Hallo, {name}. Ich weiß, Ihr seid damit beschäftigt, den Völkern Azeroths zu helfen, aber wenn Ihr etwas Zeit habt, solltet Ihr nach Ironforge zurückkehren, um mit einem der am meisten respektierten Paladine Eurer Heimat zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Zwergen-Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von uns allen erwartet wird.\n\nIhr findet sie im Obergeschoss der Halle der Mysterien, die sich im Mystikerviertel befindet.", sourceObjective = "Sprecht mit Tiza Battleforge in Ironforge.", completion = "Ich grüße Euch und heiße Euch willkommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[3001] = { id = 3001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Strahad", description = "Ich habe Euch in der Vergangenheit viele Fertigkeiten beigebracht, aber es ist an der Zeit, dass Euch ein anderer lehrt. Er lebt in Ratchet und sein Name ist Strahad. Er ist ein Mensch, aber lasst Euch deswegen nicht dazu hinreißen, ihn für schwach zu halten oder als Euren Feind anzusehen - zumindest vorerst. Er ist mächtig und sollte respektiert werden. Er kann Euch große Beschwörungen lehren, Beschwörungen, für die Ihr, glaube ich, bereit seid. Geht nun zu ihm.\n\nEr ist in Ratchet... Über der Hafenstadt, gleich bei dem Turm dort.", sourceObjective = "Findet Strahad Farsan in Ratchet.", completion = "Ein geschäftiger Tag in Ratchet, nicht wahr? Ich liebe es, dem Treiben einer Hafenstadt zuzusehen. So viel Wundersames, so viel Abenteuer... so viel Ignoranz.\n\nSehe ich da Hass in Euren Augen, {name}? Gut, wir werden daraus einen Vorteil ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3002] = { id = 3002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gordunnikugel", description = "Obwohl ich meinen Feind genau kenne, bin ich ein Krieger, {name}. Ich kann Euch nicht sagen, über welche Fähigkeiten diese Kugel verfügt.\n\nIch kenne einen Magier in Orgrimmar, der uns mehr über die Kugel sagen können wird. Bringt sie zu ihm.", sourceObjective = "Bringt die Gordunnikugel zu Uthel’nay in die Dunkeldornen-Lodge in Orgrimmar.", progress = "Was habt Ihr mir gebracht, {race}?", completion = "Faszinierend, {name}...\n\nDiese Kugel ist sehr mächtig, aber auch sehr gefährlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[3022] = { id = 3022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsichtig behandeln", description = "{name}, ich sehe deutlich, dass Ihr Euch liebend gern meiner noblen Sache zuwenden möchtet. Ja, natürlich könnt Ihr etwas für mich tun!\n\nBringt diese Kiste mit Eiern zu Erelas Ambersky. Das ist ein Druide, der sich um diese Eier kümmert. Er bebrütet sie und bildet dann die jungen Hippogryphe aus. Ihr findet ihn in Teldrassil, in einem kleinen Dorf im Süden namens Rut'theran.", sourceObjective = "Bringt die sorgfältig verpackte Kiste zu Erelas Ambersky in das Dorf Rut'theran.", progress = "Eine weitere Lieferung von Curgle, nicht wahr?", completion = "Danke für Eure Hilfe, {name}. Die Hippogryph-Population würde ohne uns einfach verkümmern. Aber ich denke, Ihr versteht das nur zu gut, schließlich seid Ihr ja selber nach Feralas gereist und habt die Verwüstung der Gordunni dort gesehen.\n\nNun, wie Ihr seht, bin ich sehr beschäftigt; macht Euch lieber gleich auf den Weg.\n\nNochmals danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[3042] = { id = 3042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollaushärter", description = "Die Trolle der Sandfury von Zul'Farrak stellen ein Aushärtungsmittel aus Sandstein her, und ich kann dies verwenden, um die von mir hergestellten Waren auszuhärten, ja, so ist es! Von Kennern wird es hoch gepriesen; wenn Ihr mir also einen guten Vorrat dieses Härters bringt, werde ich Euch reich belohnen.\n\nZul'Farrak liegt nordwestlich von Gadgetzan. Viel Glück.", sourceObjective = "Bringt 20 Phiolen Trollaushärter zu Trenton Lighthammer in Gadgetzan.", progress = "Bringt Ihr mir den Härter, {name}?", completion = "Ah, das ist wirklich guter Härter! Und so viel davon! Ich werde tagelang arbeiten können, bis alles aufgebraucht ist!\n\nDanke, {name}. Bitte, nehmt dies hier als Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[3062] = { id = 3062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Herz", description = "Edana Hasskralle ist die Königin der Nordschwingen, die in den Ruinen im Westen zu Hause sind. Sie ist das vollkommen Böse; ich habe gehört, dass sie ein Herz aus Kristall hat. Sie ist bar jeglicher Emotionen außer dem Hass, den sie für alle anderen fühlt. Ihr müsst Euch Edana stellen und mir ihr dunkles Herz zurückbringen.\n\nIch habe von einem Horn gehört, das die Harpyien tragen - wenn es bei den Hasskrallensteinen, im nördlichen Teil der Ruinen, geblasen wird, wird die Königin beschworen.\n\nStellt Euch ihre Überraschung vor, wenn es nicht die ihren sind, die auf sie warten, sondern ihr Tod.", sourceObjective = "Talo Thornhoof im Camp Mojache will das dunkle Herz von Edana Hasskralle.", progress = "Der Hass, den Edana über das Land verbreitet, muss gestoppt werden.", completion = "Jetzt weiß ich, dass Edana wahrhaft tot ist. Dieses Herz; ich werde es in Erinnerung dessen behalten, was Ihr hier für mich getan habt, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[3063] = { id = 3063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache an den Nordschwingen", description = "Zu meiner Zeit war ich ein erfahrener Jäger. Es gab keine Kreatur, die ich fürchtete. Bis...\n\nIch war draußen im Wald, um nach einem heftigen Kampf meine Klinge zu schärfen, als ich in einen Hinterhalt geriet. Harpyien umzingelten mich, und ich schaffte es kaum, mich in Sicherheit zu bringen.\n\nSelbst heute noch kann ich das Echo ihrer Schreie vernehmen...\n\nDanach war ich nicht mehr derselbe. Aber der Hass kocht in meinem Inneren - ich will Rache, auch noch nach all diesen Jahren.\n\nDie Harpyien der Nordschwingen leben westlich von hier. {name}, rächt mich.", sourceObjective = "Talo Thornhoof möchte, dass Ihr 4 Harpyien der Nordschwingen, 4 Wildfedern der Nordschwingen, 4 Windruferinnen der Nordschwingen und 4 Töter der Nordschwingen erschlagt.", completion = "Danke, {name}. Ihr habt dem Geist eines alten Tauren Ruhe gegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[3065] = { id = 3065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Schrifttafel", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, {name}.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Kriegerlehrer Frang. Er würde gern mit Euch sprechen, wenn Ihr bereit seid. Ihr findet ihn außerhalb des Höhlenbaus, wo er sich in den Schatten verbirgt.", sourceObjective = "Lest die einfache Schrifttafel und sprecht mit Frang im Tal der Prüfungen.", progress = "{race}, noch einer zur Verstärkung unserer Reihen. Mir soll's recht sein.\n\nIhr tut Euch wahrscheinlich schwer damit, eine gute Waffe wie beispielsweise eine Axt zu werfen, aber ein Speer ist genauso gut wie jede andere Waffe.\n\nWillkommen im Tal der Prüfungen.", completion = "Ihr werdet diesen Ort sehr geeignet finden für die weitere Ausbildung auf dem Weg zum {class}. Solltet Ihr Fragen haben, seid so frei und fragt jeden hier. Wenn Ihr bereit seid, kommt zurück und lasst mich Euch ausbilden. Ich habe so viele Situationen und Kämpfe gemeistert, wie jeder andere {class} hier im Tal und kann dieses Wissen an Euch weitergeben ... aber das hat seinen Preis.", sourceObjectiveStatus = "unverified-source-field" }
quests[3082] = { id = 3082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geätzte Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, {name}.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Jägerlehrerin Jen'shan. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Jen'shan im Tal der Prüfungen.", progress = "Jen'shan sehen einen mächtigen {class} vor sich und die Geister geben Zustimmung.\n\nDer Weg des Jägers sein eine der ältesten Lebensweisen. Die Horde sich hat an uns gewendet, als sie ums Überleben kämpfen müssen auf Azeroth, und uns gebeten, ihnen in die Geheimnisse vieler Dinge einzuweihen. Sie bereits stark waren: stark als Schamanen; stark als Krieger. Aber Weg des Jägers nicht ihrer ... damals.", completion = "Wir ihnen bringen diese Dingens bei und sie uns lehren andere. Wir ein Volk werden... na ja, fast. Wir jetzt sein eine lange Zeit Verbündete. Ihr also denken dran, ihnen helfen. Und Jen'shan denken daran, Euch helfen.\n\nJen'shan Euch lehren dann Fertigkeiten von {class} - lehren Euch gut. Ihr nie vergessen, {class} viel respektiert von Stamm. Ihr werden spielen große Rolle in Zukunft... Ihr das nie vergessen.\n\nWenn Ihr wollen, kommen zu Jen'shan. Sie Euch lehren, so viel sie kann, wenn sie meinen, dass Ihr sein bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[3083] = { id = 3083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselte Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, {name}.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie vom Schurkenlehrer Rwag. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest die verschlüsselte Schrifttafel und sprecht mit Rwag im Tal der Prüfungen.", progress = "Willkommen im Tal der Prüfungen, {name}. Ihr wärt nicht hier, wenn Ihr meine Schrifttafel nicht erhalten hättet, daher komme ich gleich auf den Punkt.\n\nIch bin Rwag und zuständig für die Ausbildung der Schurken, Diebe und Taschendiebe hier im Tal. Ich bin derjenige, an den sich die Hand wendet, wenn Ihr nicht bereit seid für das, was auf Euch zukommt. Aber keine Sorge, die Hand kontrolliert nicht alles, was Ihr tut - es wäre jedoch ratsam, mit ihnen zusammenzuarbeiten, sollten sie je Bedarf für Eure Talente haben.", completion = "Bis dahin seid Ihr unter meiner Federführung. Ich werde Euch die Tricks lehren, wie manche dazu sagen. Wenn Ihr meint, dass Ihr vorbereitet seid, kommt zu mir und ich werde Eure Ausbildung fortsetzen. Bis dahin übt Eure Fertigkeiten und verfeinert sie auf's Beste. Man kann nie wissen, wann man selbst die unbedeutendste Fähigkeit benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3084] = { id = 3084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Runen beschriftete Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, {name}.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Shikrik im Tal der Prüfungen.", progress = "Ah, willkommen, {name}. Schön, dass Ihr eingetroffen seid. Meine Tage sind so lang und geschäftig geworden, mit so vielen Schülern, die ich derzeit lehre - aber der Besuch von einem der Euren erfüllt mich mit tiefer Befriedigung - ich erinnere mich an die Tage, als ich von einem Eurer Schamanen unterrichtet wurde.", completion = "Wie Ihr möglicherweise wisst, geben uns die Elemente unsere Macht. Feuer, Erde, Wasser und Luft - das sind unsere Werkzeuge.\n\nUnsere Kraft erhalten wir von den Geistern unserer Vorfahren. Wir sind die Anführer unseres Volkes. Was Thrall für die Horde ist, werden wir für die Dörfer und Städte sein, die wir aufsuchen. Sie werden sich um Rat und Schutz an uns wenden. Ihr müsst häufig trainieren, um besser vorbereitet zu sein. Wenn Ihr fühlt, dass Ihr mächtiger geworden seid, kommt zu mir und ich werde Euch lehren, was ich vermag.", sourceObjectiveStatus = "unverified-source-field" }
quests[3085] = { id = 3085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligte Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, {name}.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie vom Priesterlehrer Ken'jai. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest die geheiligte Schrifttafel und sprecht mit Ken'jai außerhalb des Höhlenbaus im Tal der Prüfungen.", progress = "So Ihr haben hierher geschafft... gut, gut! Geister mir gesagt, Ihr Ken'jai bald aufsuchen. Lasst mich einer der Ersten sein, der Euch im Tal der Prüfungen willkommen heißen. Diese Ort nicht sein Zuhause für lang, aber während es ist, warum nicht machen das Beste daraus.", completion = "Wenn Ihr Euch prüfen, Ihr werden finden, dass Ihr mehr und mehr Kontrolle über die Geister haben - Ihr können sie beschwören für immer größere Dinge... und da kommen der alte Ken'jai ins Spiel. Ihr kommen und reden mit dem alten Ken'jai, wenn Ihr fühlen, dass bereit sein. Wenn Geister zustimmen, dann wir lernen mächtigere Fähigkeiten... aber nur, wenn Geister zustimmen.\n\nGehen jetzt, reden mit anderen im Tal. Reden später wieder mit mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[3086] = { id = 3086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphen-Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, {name}.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Magierlehrerin Mai'ah. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest die mit Glyphen versehene Schrifttafel und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen.", progress = "Ihr Mai'ah schon viel Freude bereiten, {name}. Das sein gut. Ihr zollen Mai'ah Respekt, und Mai'ah vielleicht auch Euch zollen Respekt. Aber jetzt genug davon, Ihr sein hier, um über Magie zu lernen, nicht um Mai'ah reden zu hören.\n\nEs geben nur eins, was Mai'ah Euch nicht lehren kann über Magie, {name} - und das sein, wie zu stoppen Verderbnis.", completion = "Ihr werden sein eines der mächtigsten Lebewesen auf dem Planeten, {name}..., daran bestehen kein Zweifel. Und jeder wird es wissen... und gut wissen!\n\nAber Ihr müssen wachsam sein! Weil sein kein Orc oder Elf oder Zwerg, vor dem Ihr fürchten müsst Euch..., es sein Dinge, die Ihr nicht sehen können. Magie können sein mächtig. Euch Dinge tun lassen, die Ihr nicht tun wollen. Euch denken lassen, Ihr sein mächtiger als Ihr in Wirklichkeit sein. Haben Geduld. Seien schlau.\n\nWenn Ihr denken, dass bereit sein für Unterweisung, kommen zurück zu Mai'ah. Sie Euch lehren, was Ihr wissen müssen, kein Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[3087] = { id = 3087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geätztes Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, {name}.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Jägerlehrerin Jen'shan. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest das geätzte Pergament und sprecht mit Jen'shan im Tal der Prüfungen.", progress = "Ah, da Ihr sein schließlich. Gut. Jen'shan Euch haben erwartet.\n\nViele meinen, das sein ein einfacher Weg, aber Jen'shan Euch sagen, dass nicht stimmen. Die Beherrschung der Bestien von Durotar und darüber hinaus erfordern genauso viel Fertigkeit wie die Beherrschung der arkanen Künste oder das Reden mit unseren Vorfahren.\n\nDas Abfeuern eines Bogens oder eines Gewehres mögen Euch nicht so gefährlich erscheinen wie das Wirken eines Zaubers, es seien jedoch genauso gefährlich für Euren Feind.", completion = "Wenn wir fertig mit reden, Ihr solltet mit anderen Einwohnern des Tals reden. Sie Euch werden bitten, Dinge für sie zu tun... Dinge, mit denen Eure Fertigkeiten geprüft werden und die Euch einige der Gefahren dieses Landes aufzeigen.\n\nWenn Ihr erfahrener und weiser werdet, Ihr werden brauchen Jen'shan, um Euch bessere Techniken und Fertigkeiten zu zeigen. Besucht Jen'shan oft. Ich werde Euch dann mitteilen, was ich Euch lehren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[3088] = { id = 3088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsseltes Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, {name}.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Schurkenlehrer Rwag. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest das verschlüsselte Pergament und sprecht mit Rwag im Tal der Prüfungen.", progress = "Schhht, nicht so laut. Ich traue Nartok dort drüben nicht. Mit jedem, der sich tiefer in einer Höhle verbergen muss als ich, ist nicht zu spaßen.\n\nIch vermute, Ihr hattet keine Probleme, Euch zurecht zu finden?", completion = "Jetzt, wo Ihr wisst, wo ich mich aufhalte, solltet Ihr Folgendes wissen: Die Shattered-Hand haben mich beauftragt, Euch zu suchen. Sie wollen, dass ich Euch unterweise und Euch über alles informiere, was sie brauchen können. Selbst falls Ihr noch nicht daran interessiert seid, ihnen zu helfen - obgleich Ihr ein Narr wärt, dies nicht zu tun -, werde ich tun, was immer ich kann, um Euch zu unterweisen ... natürlich gegen eine geringe Gebühr. Kommt zu mir zurück, wann Ihr meint bereit zu sein - und ich werde sehen, welche Lektionen Ihr lernen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3089] = { id = 3089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Runen beschriftetes Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, {name}.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest das mit Runen beschriebene Pergament und sprecht mit Shikrik im Tal der Prüfungen.", progress = "Ihr seid also angekommen. Ich habe mich schon gefragt, ob Ihr wohl auftauchen würdet. Ich habe das Pergament bereits vor einiger Zeit geschickt und war mir nicht sicher, ob es auch angekommen ist.\n\nAber genug geplaudert... Ihr seid hier, weil Ihr auserwählt seid, auserwählt, das spirituelle Leben Eures Volkes zu leiten.", completion = "Ihr werdet der Kanal sein, über den unsere Vorfahren kommunizieren. Ihr werdet die Macht der Elemente zu Eurer Verfügung haben. Die Zerschlagung Eurer Feinde wird ein Kinderspiel sein; die Heilung Eurer Verbündeten so leicht wie das Atmen sein. Behaltet diese Dinge im Gedächtnis, während Ihr neue Herausforderungen meistert, und kehrt so oft zu mir zurück, wie Ihr wollt. Ich werde hier sein, Euch neue Zauber zu lehren, und Euch auf den richtigen Weg bringen, wenn Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[3090] = { id = 3090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudeltes Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, {name}.\n\nIch versuche normalerweise, jedweden Kontakt mit Hexenmeistern zu vermeiden, aber ich glaube, Ihr solltet es lesen, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von Eurem neuen Lehrer Nartok. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest das besudelte Pergament und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen.", progress = "Endlich seid Ihr gekommen... und so diskret! Gut.\n\nUnsere Welt ist voller Narren, {name}. Selbst der mächtige Thrall hat mehr Fehler als die meisten erkennen können. Er wendet der Macht, durch die dieses Land ganz unser werden kann, den Rücken zu! Wir sind nicht dasselbe Volk, das einst von den Kreaturen aus dem Nether manipuliert und benutzt wurde. Wir sind ein eigenes Volk. Wir sind stolz... und wir sind stark.", completion = "Und nun seid auch Ihr unseren Reihen beigetreten. Versteht mich nicht falsch, {name}. Nur, weil Ihr Zugang zur Macht habt, auf die viele neidisch sind, bedeutet dies nicht, dass Ihr einfach akzeptiert werdet. Thrall lässt einen unserer Art nach Orgrimmar, weil wir noch immer seinesgleichen sind - er kann uns nicht den Rücken zuwenden oder wir würden ebenso pathetisch werden wie die Menschen, die ihn versklavten. Ich sage nur: seid vorsichtig. Ihr mögt mächtig sein, seid Ihr jedoch tollkühn, seid Ihr so gut wie tot.\n\nWenn Ihr eine Unterweisung im Zaubern benötigt, sucht mich wieder auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[3091] = { id = 3091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Notiz", description = "Gerade eben fragte eine Botin nach Euch, {name}. Ich glaube, sie wurde vom Kriegerlehrer Harutt geschickt. Wenn diese Nachricht von Harutt ist, würde ich sie schnellstens lesen.", sourceObjective = "Lest die einfache Nachricht und sprecht mit Harutt Thunderhorn im Camp Narache.", progress = "Ah, {name}, Ihr seid endlich angekommen. In meiner Nachricht habe ich nicht gelogen, {name}. Wir sind von besonderer Art, nicht unähnlich den Druiden oder Schamanen unseres Stammes. Ihr seid ebenso wichtig. Wir sind die, die zur Verteidigung unserer Grenzen gerufen werden, zur Jagd auf den Zentauren und um in den Krieg zu ziehen.", completion = "Jeder von uns spielt in unserem Stamm eine Rolle. Jeder von uns muss auch dieselben Riten durchlaufen. Lasst Euch niemals von Eurem Stolz etwas anderes sagen.\n\nIch verbleibe hier, um neue {class} auszubilden, die Ruhm in Schlachten suchen und den Wegen der ältesten unserer Vorfahren folgen. Wenn Ihr Euch bereit fühlt, kommt wieder zu mir und ich werde tun, was ich kann, um Euch weiter auszubilden. Jetzt geht mit dem Segen des Stammes, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[3092] = { id = 3092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geätzte Notiz", description = "Gerade eben fragte eine Botin nach Euch, {name}. Ich glaube, sie wurde vom Jägerlehrer Lanka geschickt. Wenn diese Nachricht von Lanka ist, würde ich sie schnellstens lesen.", sourceObjective = "Lest die geätzte Nachricht und sprecht mit Lanka Farshot in Red Cloud Mesa.", progress = "Willkommen im Camp Narache, {name}. Ich höre viel Gutes über Euch. Euer Geschlecht ist stark und viele der Ältesten halten Eure Fertigkeiten bereits für gut. Aber das wird sich in den Prüfungen zeigen.\n\nDie Ebenen von Mulgore werden für einige Zeit Euer Zuhause sein - Ihr solltet Euch bemühen, sie so gut wie möglich kennen zu lernen. Eines Tages werdet Ihr in unbekanntes Land aufbrechen, um größere Fertigkeiten zu erwerben. Dann müsst Ihr bereit sein.", completion = "Und es ist meine Aufgabe sicherzustellen, dass Ihr bereit seid, indem ich Euch die Grundlagen unserer Profession lehre - Euer Tier zu zähmen, Euer Gewehr abzufeuern und viele andere Fertigkeiten, die Ihr brauchen werdet.\n\n{class} sind ein starker Teil unserer Tradition und Geschichte, {name}. Ihr tätet gut daran, Euch zu erinnern, wie wichtig Ihr für den Stamm seid. Ihr werdet respektiert und verehrt, wenn Ihr unserem Volk gut dient.", sourceObjectiveStatus = "unverified-source-field" }
quests[3093] = { id = 3093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Runen beschriftete Notiz", description = "Gerade eben fragte eine Botin nach Euch, {name}. Ich glaube, sie wurde von der Schamanenlehrerin Meela geschickt. Wenn diese Nachricht von Meela ist, würde ich sie schnellstens lesen.", sourceObjective = "Lest die mit Runen beschriftete Nachricht und sprecht mit Meela Dawnstrider im Camp Narache.", progress = "So schnell, wie Wasser vom Himmel fällt, seid Ihr hier eingetroffen. Eure Eile freut mich. Sie bedeutet, dass Ihr die Bedeutung unseres Treffens versteht und auch um die Bedeutung Eures Hierseins wisst. Ich bin kein Anführer, aber ich verstehe die Elemente und ich kann mit den Geistern unseres Volkes reden. Ich werde Euch lehren, es mir gleichzutun.", completion = "In den kommenden Tagen werden wir uns häufig sehen. Jedes Mal verlasst Ihr mich ein wenig mächtiger... ein wenig besser vorbereitet. Wie die ewige Flamme wird Euer Geist hell und heiß lodern.\n\nGeht jetzt, {name}. Geht und unterzieht Euch den Prüfungen. Ich werde hier sein, wenn Ihr mich braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[3094] = { id = 3094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefgrüne Notiz", description = "Gerade eben fragte eine Botin nach Euch, {name}. Ich glaube, sie wurde vom Druidenlehrer Gart geschickt. Wenn diese Nachricht von Gart ist, würde ich sie schnellstens lesen.", sourceObjective = "Lest die tiefgrüne Notiz und sprecht mit Gart Mistrunner im Camp Narache.", progress = "Ihr seid gekommen. Das ist gut. In letzter Zeit sind die Geister unserer Vorfahren in ganz Mulgore und Umgebung rastlos, ich kann jedoch nicht sagen, warum. Es wird stets Eure Pflicht sein, zu lernen, den Naturgeistern zuzuhören und als ihr Avatar zu fungieren. Denkt stets daran.", completion = "Trotz unseres Bündnisses mit den Nachtelfen solltet Ihr kein herzliches Willkommen von ihnen erwarten. Ihr Stolz begrenzt noch immer ihre Sicht, aber das ist nicht unser Problem. Die Lehren der Erdenmutter sind alles, um was Ihr Euch kümmern müsst, und ich werde Euch lehren, was ich weiß, während Eure Weisheit zunimmt.\n\nSucht mich oft auf, {name}. Ihr werden feststellen, dass die Erdenmutter Ihren hingebungsvollsten Anhängern unglaubliche Fähigkeiten gewährt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3095] = { id = 3095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Kriegerlehrers Dannal zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", sourceObjective = "Lest die einfache Schriftrolle und sprecht mit Dannal Stern in Deathknell.", progress = "Ah, Ihr seid also eingetroffen. Gut. Ich habe mitbekommen, dass einige andere dem 'Tod' entrinnen konnten und in die Stadt flohen. Vielleicht zahlt sich diese Widerstandsfähigkeit künftig ebenfalls aus.\n\nIhr könnt Sylvanas für Eure Freiheit danken... die Freiheit von Geist und Körper. Obgleich Ihr noch immer von der Seuche und ihren Auswirkungen heimgesucht seid, steht es Euch jetzt frei, zu kommen und zu gehen wie es Euch beliebt.", completion = "Ich werde hier sein, Euch zu lehren, während Ihr an Erfahrung gewinnt... sucht mich so oft auf, wie Ihr mögt. Ich verlange eine minimale Gebühr, Ihr werdet jedoch alles, was ich Euch lehren kann, lohnenswert finden.\n\nGeht jetzt und prüft Eure Fertigkeiten. Während Ihr an Erfahrung gewinnt, werden sich Euch viele neue Dinge offenbaren; einige davon kann ich hier jetzt nicht mit Euch besprechen. Wisset nur, dass Sylvanas künftig {class} mit Kraft wie Euresgleichen brauchen wird. Ihr werdet das Rückgrat unserer Rettung sein. Vergesst das nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[3096] = { id = 3096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselte Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Schurkenlehrers David Trias zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", sourceObjective = "Lest die verschlüsselte Schriftrolle und sprecht mit David Trias in Deathknell.", progress = "Ihr habt es also hierher geschafft? Gut, wir brauchen mit der Zeit immer mehr Schurken. Die Schattenpirscher werden wahrscheinlich versuchen, Euch zu finden, wenn die Zeit reif ist; seht also zu, dass Ihr nicht in etwas hineingeratet oder etwas tut, was Ihr später bereut. Sie brauchen fähige Agenten ... keine Taschendiebe und Narren.", completion = "Ich habe die meiste Zeit hier im Gasthaus verbracht, auf neue Gesichter geachtet und nach möglichen künftigen Aspiranten Ausschau gehalten. Haltet die Nase frei und ich tue, was ich kann, um Euch einige Dinge zu lehren. Kommt einfach zu mir zurück, wann immer Ihr wollt und wir werden sehen, ob Ihr bereit seid für eine neue Fertigkeit oder zwei.", sourceObjectiveStatus = "unverified-source-field" }
quests[3097] = { id = 3097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligte Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Priesterlehrers Duesten zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", sourceObjective = "Lest die geheiligte Schriftrolle und sprecht mit dem dunklen Kleriker Duesten in der Kirche von Deathknell.", progress = "Ah, so kommt zwischen Feuer, Seuche, Aufständen und Schlimmerem ein Mal mehr ein 'Getreuer' an meine Tür. Nun, seid gegrüßt, {class}. Und lasst mich Euch kurz ein oder zwei Dinge zu erklären, bevor Ihr Euch auf die Suche nach dem macht, was immer Euch im Leben antreibt: Das Heilige Licht betrifft Euch nicht länger, die Geister Eurer Vorväter sind nurmehr schöne Geschichten und die Kreaturen aus dem Nether wollen Euch nicht.\n\nVersteht Ihr mich so weit?", completion = "Ihr müsst nur eins wissen: Wir haben durch schiere Willenskraft überlebt. Es ist der Glaube an uns selbst, der uns von anderen unterscheidet, und mit unserer Macht werden wir große Veränderungen in gesamt Azeroth herbeiführen. Die Schwachen werden auf Euch angewiesen sein. Die Leprakranken werden Euch Lord nennen. Und die Ignoranten werden Euch um Führung ersuchen. Es ist meine Pflicht sicherzustellen, dass Ihr die nötigen Werkzeuge habt, sodass Ihr bereit seid, wenn die Zeit gekommen ist. Sucht mich auf, während Ihr an Erfahrung gewinnt. Ich werde Euch lehren, wie Ihr noch mächtiger werdet, wenn Ihr dazu bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[3098] = { id = 3098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphen-Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel der Magielehrerin Isabella zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", sourceObjective = "Lest die mit Glyphen versehene Schriftrolle und sprecht mit Isabella in der Kirche von Deathknell.", progress = "Ich wusste, Ihr würdet zu mir kommen, {name}. Nicht, weil Ihr nicht den Willen habt, Eurem eigenen Weg zu folgen, sondern weil wir verwandte Geister sind. Beide haben wir Schmerz gefühlt. Beide haben wir gelitten. Und jetzt wollen wir die Macht, um uns das zurückzuholen, von dem wir wissen, dass es unser ist: dieses Land, unser Leben, unser Schicksal. Aber Ihr müsst noch immer viel lernen.", completion = "Ihr müsst oft zu mir zurückkehren, wenn Ihr mächtig genug werden wollt, um unsere Gegner zu vernichten. Die Regeln der Magie gelten noch immer für Euch, {name}. Ihr werdet noch immer feststellen, dass Euch die Verderbnis folgt, wie hungrige Wölfe in der Nacht. Ihr werdet ihre sanften Berührungen fühlen und feststellen, dass sie einer Sucht ähnelt, einem alten Liebhaber, dem es noch immer verlangt, an Eurer Seite zu sein. Ihr könnt diese Dinge jedoch abschütteln. Diese Dinge werden Euch nur kontrollieren, wenn Ihr dies zulasst.\n\nGeht jetzt und kehrt zurück, wenn Ihr mächtiger geworden seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[3099] = { id = 3099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelte Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Hexenmeisterlehrers Maximillion zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", sourceObjective = "Lest die besudelte Schriftrolle und sprecht mit Maximillion in Deathknell.", progress = "Ich heiße Euch willkommen, Bruder. Ich wusste, Ihr würdet kommen. Es war nur eine Frage der Zeit.\n\nWas ich sagte, hat Euch interessiert, nicht wahr? Es schlug eine Saite an... etwas in Euch wusste, dass meine Worte wahr waren. Gut.\n\nDoch wisset dies: Ich bin kein Verräter an Sylvanas. Wenn überhaupt, würde sie meine Worte zu schätzen wissen, wenn man bedenkt, dass es ihre eigenen Überzeugungen waren, die die Verlassenen in die Situation gebracht haben, in der sie sich jetzt befinden.", completion = "Ich sprach davon, dass ein Sklave immer ein Sklave bleibt, ungeachtet des Meisters. Erinnert Ihr Euch? Wir beide wissen, dass es diese Art von Kontrolle - diese Art von Macht - ist, die uns jetzt antreibt. Wir wollen, dass uns Kreaturen dienen. Wir wissen, dass wir mächtiger sind und mehr Respekt verdienen als andere uns zollen... Und somit streben wir jetzt danach, uns den Respekt zu nehmen.\n\nIch werde in diesem Kampf Euer Verbündeter sein - im Kampf um unsere eigene Freiheit. Die Freiheit, unsere eigenen Zugehörigkeiten wählen zu können. Wenn Ihr bereit seid, kommt zurück zu mir und ich werde Euch alles lehren, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[3100] = { id = 3100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfacher Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, {name}. Es scheint sich um einen versiegelten Brief mit den Insignien von Llane, unserem örtlichen Kriegerlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", sourceObjective = "Lest den einfachen Brief und sprecht mit Llane Beshere in der Abtei von Nordhain.", progress = "Ah, Ihr habt meinen Brief erhalten, {name}... gut.\n\nIn letzter Zeit gab es einen Zustrom von Kriegern in Elwynn - was gut ist für Stormwind, jedoch schlecht für die Kobolde und Defias in dieser Gegend.", completion = "Messt Euch mit anderen, macht Euch mit den Gegebenheiten dieses Landes vertraut und kommt zu mir zurück, wann immer Ihr weitere Unterweisung wünscht. Ich werde hier sein, bei Tag und Nacht.\n\nDie Ritter der Silberhand haben viel geleistet und dies zu einem recht sicheren Ort gemacht; wenn Ihr aber andere Einwohner trefft, werdet Ihr wohl feststellen, dass sie alle Probleme haben, bei denen sie ein wenig Hilfe gebrauchen könnten - Hilfe, die ihnen ein {class} gewähren kann. Viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[3101] = { id = 3101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihter Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, {name}. Es scheint sich um einen versiegelten Brief mit den Insignien von Bruder Sammuel, unserem örtlichen Paladinlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", sourceObjective = "Lest den geweihten Brief und sprecht mit Bruder Sammuel in der Abtei von Nordhain.", progress = "Endlich! Wir stehen uns von Angesicht zu Angesicht gegenüber, Bruder und Bruder. Ich heiße Euch willkommen in Nordhain. Hier wird während der kurzen Zeit Euer Zuhause sein, in der Ihr lernt, wie die Dinge laufen, aber wisset, dass Stormwind nicht weit von hier ist und dass Euer Weg Euch über kurz oder lang dorthin führen wird. Bis dahin, habt Geduld... Ritter der Silberhand.", completion = "In der Zwischenzeit solltet Ihr einige andere Dinge wissen. Ihr seid ein Symbol für viele hier im Land - verhaltet Euch entsprechend. Das Heilige Licht leuchtet in Euch und dies ist sowohl für Eure Verbündeten als auch Eure Feinde offensichtlich.\n\nZudem, wenn Ihr an Weisheit und Macht gewinnt, müsst Ihr trainieren, um neue Fähigkeiten zu erlernen. Und da komme ich ins Spiel. Wenn Ihr denkt, dass Ihr genug Erfahrung hier in Nordhain gesammelt habt, kommt zu mir zurück und ich werde Euch die Dinge lehren, zu denen Ihr meiner Meinung nach bereit seid. Viel Glück... {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[3102] = { id = 3102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselter Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, {name}. Es scheint sich um einen versiegelten Brief mit den Insignien von Jorik, einem unserer örtlichen Lehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", sourceObjective = "Lest den verschlüsselten Brief und sprecht mit Jorik Kerridan im Stall hinter der Abtei von Nordhain.", progress = "Ihr habt es in einem Stück hierher geschafft und es sieht so aus, als ob Ihr nicht von zu vielen Leuten gesichtet wurdet. Das reicht mir. Ich mag es nicht, zu viel Aufmerksamkeit auf mich hier zu lenken... ich bin gern für mich und unbehelligt. Ich bin sicher, Ihr versteht mich.\n\nGab es Ärger bisher? Nicht? Freut mich zu hören. Das wird sich jedoch schon bald ändern.", completion = "Ihr werdet feststellen, dass es eine Reihe von Gruppierungen für Eure Fertigkeiten gibt, {name}. Abenteurer, SI:7... sogar die Bruderschaft der Defias hätte gern einen Spion oder zwei in Stormwind. Aber vergesst nicht, es ist Eure Entscheidung. Lasst Euch nicht zu etwas drängen, was Ihr nicht tun wollt! Darüber hinaus halten wir alle Trümpfe in der Hand... zumindest werden wir dies, bevor das Spiel vorbei ist. Versteht Ihr, was ich meine?\n\nEgal, ich wollte mich nur kurz vorstellen und Euch wissen lassen, dass ich hier bin, wenn Ihr Unterweisungen wünscht. Ihr seid jederzeit gern gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3103] = { id = 3103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligter Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, {name}. Es scheint sich um einen versiegelten Brief mit den Insignien der Priesterin Anetta, unserer örtlichen Priesterlehrerin, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", sourceObjective = "Lest den geheiligten Brief und sprecht mit Priesterin Anetta in der Abtei von Nordhain.", progress = "Ah, endlich seid Ihr gekommen. Ich wusste, Ihr würdet Euren Weg zu mir finden. Das Heilige Licht scheint auf Euch und den Weg, den Ihr gewählt habt. Die Zeiten sind hart - die Brennende Legion ist auf Azeroth noch immer allgegenwärtig, ganz Kalimdor sucht neue Wege, um sich vor den eigenen Widerwärtigkeiten zu schützen, und es ist an Euch, so vielen wie möglich zu helfen.", completion = "Während Ihr an Erfahrung gewinnt, sucht mich auf und ich werde tun, was in meiner Macht steht, um Euch mein Wissen zu vermitteln. Bis dahin, geht, haltet das Mitgefühl in Eurem Herzen und lasst Euch von der Weisheit leiten. Denkt daran, die Welt wird nur dann zu einem besseren Ort, wenn Ihr sie dazu macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[3104] = { id = 3104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphen-Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, {name}. Es scheint sich um einen versiegelten Brief mit den Insignien von Kheldon, unserem örtlichen Magierlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", sourceObjective = "Lest den mit Glyphen versehenen Brief und sprecht mit Kheldon Bremen in der Abtei von Nordhain.", progress = "Hallo, {name}. Ich bin Kheldon. Kann ich etwas für Euch tun?", completion = "Haha, ich wusste, meine Notiz würde Euch nicht von Eurem Weg abbringen. Ihr seid also bereit, hm? Bereit, Euer Schicksal anzunehmen? Bereit, die Götter herauszufordern und alle anderen Kräfte, die zwischen Euch und dem Erlangen von Wissen und Macht stehen?\n\nIch werde Euch nicht belügen, {name}, Ihr werdet ebenso gefürchtet wie respektiert werden. Aber wisset auch dies, ich werde hier sein für Euch, wenn Ihr Unterweisung benötigt. Sucht mich einfach auf, während Ihr mächtiger werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[3105] = { id = 3105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelter Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, {name}. Es scheint sich um einen versiegelten Brief mit den Insignien von Drusilla, einer unserer örtlichen Lehrerinnen, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", sourceObjective = "Lest den besudelten Brief und sprecht mit Drusilla La Salle nahe der Abtei von Nordhain.", progress = "Ah, Ihr seid eingetroffen, und das keinen Moment zu früh, {name}. Einige Wachen waren gerade da und sahen mich sehr neugierig an... armselige sterbliche Geschöpfe.", completion = "Während Ihr mächtiger werdet, werdet Ihr in Versuchungen geraten - Ihr müsst stets daran denken die Kontrolle zu bewahren. Ich werde Euch nicht belügen - Verderbnis kann jeden Ausübenden der arkanen Künste ereilen, besonders diejenigen, die sich mit den Kreaturen des wirbelnden Nethers beschäftigen. Habt Geduld und seid vorsichtig... Aber nehmt Euch in Euren Ambitionen nicht zu stark zurück.\n\nWenn Ihr mächtiger werdet, sucht mich erneut auf und ich werde Euch mehr über unsere Lebensart lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[3106] = { id = 3106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Rune", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Kriegerlehrer Thran. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", sourceObjective = "Lest die einfache Rune und sprecht mit Thran Khorman im Coldridgetal.", progress = "Verdammt, ist das kalt heute, was? Es scheint, als ob der Schnee nie schmelzen würde, {name}.\n\nIhr habt es wahrscheinlich längst gemerkt, dass jetzt Gnome in unserer Stadt leben. Und das nur, weil sie sich selbst das Dach überm Kopf weggesprengt haben. Erzählt das nicht weiter, aber ich kann es ihnen nicht mal verübeln ... wenn Ironforge so schlimm mit Dunkeleisenzwergen oder ähnlichen Kreaturen verseucht wäre, würde ich auch zu Sprengstoff greifen.", completion = "Es gibt noch mehr, was Ihr wahrscheinlich auch sehen werdet: Zwerge, die im Kampf Magie statt Gewehre einsetzen. Einige von uns beten das Heilige Licht an, wie einige der Menschen, und nicht zu vergessen, einige der Troggs. Ihr werdet später mehr über sie erfahren. Was Ihr jedoch wissen müsst, ist, dass ich da bin, um Euch zu helfen.\n\nIch werde Euch lehren, ein richtiger {class} zu werden. Jedes Mal, wenn Ihr meint, mehr Unterweisung zu brauchen, kommt Ihr zu mir und ich werde sehen, was ich tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[3107] = { id = 3107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Rune", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Paladinlehrer Bromos. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", sourceObjective = "Lest die geweihte Rune und sprecht mit Bromos Grummner im Coldridgetal.", progress = "Ihr habt es also hierher geschafft! Und das keine Sekunde zu früh. Es gibt viel zu tun im Coldridgetal und in der Umgebung. Ich werde Eure Hilfe brauchen, so wie Ihr die meine!\n\nIhr seid nun ein Ritter der Silberhand, zeigt Euch der Aufgabe gewachsen.", completion = "Die Menschen haben uns viel über das Heilige Licht gelehrt und darüber, wie wichtig der Orden für sie ist... und für den Schutz von ganz Azeroth. Wir haben großen Respekt vor der Bedeutung der Tradition und davor, wie nur ein einziger, eine Opferung, den Unterschied bewirken kann zwischen Schmerz und Erlösung.\n\nWir zwei werden eine Weile zusammenarbeiten. Kommt zu mir zurück, wann immer Ihr meint bereit zu sein, und wir werden ein bisschen üben. Wir können Euch ja nicht unvorbereitet in die Welt hinausziehen lassen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[3108] = { id = 3108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geätzte Rune", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Jägerlehrer Thorgas. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", sourceObjective = "Lest die geätzte Rune und sprecht mit Thorgas Grimson im Coldridgetal.", progress = "Ihr habt's also hierher geschafft! Das ist eine gute Nachricht! Musstet mich wohl auch nicht verfolgen, um den Ort hier zu finden. Ha-ha!\n\nUnsere Profession ist recht traditionslastig, {name}. Die Gegebenheiten des Landes lernen. Einen Bären durch die Berge verfolgen lernen. Selbst das einfache Überleben, nur mit Hilfe des Verstandes, erfordert viel Mut und Schläue. Meint Ihr, dass Ihr dazu fähig seid?", completion = "Eines solltet Ihr niemals vergessen: Ihr müsst die Welt respektieren, in der Ihr lebt. Die Wildtiere, die den Kampf an Eurer Seite wählen; den Glanz Eurer Waffe; das Gewicht Eurer Munition; das Beißen eines schneidenden Windes; all diese Dinge müsst Ihr wie Eure Westentasche kennen.\n\nIch werde alles tun, was ich vermag, um Euch zu helfen; die meiste Arbeit müsst Ihr jedoch allein leisten. Sucht mich auf, wann immer Ihr meint, bereit zu sein. Ich bilde Euch aus, wenn ich kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[3109] = { id = 3109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselte Rune", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Schurkenlehrer Solm. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", sourceObjective = "Lest die verschlüsselte Rune und sprecht mit Solm Hargrin im Coldridgetal.", progress = "Ihr habt es hierher geschafft! Großartig!\n\nWir bemerken in letzter Zeit verstärkte Aktivitäten, daher bin ich froh, ein weiteres Mitglied des Ironforgeklans in unseren Reihen zu wissen. Für meinen Geschmack beschäftigen sich zu viele von uns mit dem Arkanen und Göttlichen. Nichts gegen sie und ihren Glauben, aber es geht doch nichts über eine kalte Klinge in der Hand und einen Schatten, der einen vor dem Licht schützt, wenn Ihr wisst, was ich meine?", completion = "Wie dem auch sei, wenn Ihr Euch in Coldridge umseht, werdet Ihr wahrscheinlich irgendwann in einigen Dingen eine Ausbildung benötigen. Kommt einfach zu mir zurück, wann immer Ihr das Bedürfnis nach Unterweisung verspürt, und ich werde Euch lehren, was ich weiß - einen Trick hier, ein kleines Manöver dort. Ihr wisst schon, alles Mögliche, was einen am Leben erhält und einige Münzen extra einbringt.\n\nHaltet auch Ausschau nach unseren gnomischen Freunden ... bei der Zerstörung von Gnomeregan haben sie wohl ... den Kürzeren gezogen. Sie brauchen unsere Hilfe, um sich hier zu Hause zu fühlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3110] = { id = 3110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligte Rune", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Priesterlehrer Branstock. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", sourceObjective = "Lest die geheiligte Rune und sprecht mit Branstock Khalder in Anvilmar.", progress = "Ahh! Ihr habt's also hierher geschafft, {name}! Großartig!\n\nWas ich sagen wollte, fast hätte ich den Glauben daran verloren, dass Ihr überhaupt erscheint..., versteht Ihr, den Glauben verloren? Nur ein Spaß, Jungchen... äh, ist ja auch egal. Ihr seid ja nicht gekommen, um meine schlechten Witze zu hören.", completion = "Ich kann Euch unterweisen, während Ihr lernt, Euch im Coldridgetal zurechtzufinden. Wenn Ihr Euch bereit fühlt, kommt zurück zu mir und wir werden sehen, ob Ihr schon so weit seid, einen oder zwei neue Zauber zu lernen, um das Tal gegen die verdammten Troggs zu verteidigen.\n\nIhr habt das Licht sowie ganz Ironforge auf Eurer Seite, {name}, ... kein Druck lastet auf Euch, etwas Besonderes zu werden..", sourceObjectiveStatus = "unverified-source-field" }
quests[3112] = { id = 3112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfaches Memorandum", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Kriegerlehrer Thran. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", sourceObjective = "Lest das einfache Memorandum und sprecht mit Thran Khorman im Coldridgetal.", progress = "Ah, nun, ein weiteres Memorandum von einem {race} im Einsatz... ist das nicht kurios.\n\nNein, nein, ich mache mich nicht über Euch lustig, Kleiner. Eure Zähigkeit verdient Respekt, so viel ist sicher. Ich wäre genauso verärgert, wenn Ironforge von Dunkeleisenzwergen eingenommen würde, glaubt also nicht, dass ich kein Mitgefühl verspüre für Eure Not...", completion = "Tja, wie ich sehe, ist dies Eure 'Oberste Direktive', oder wie auch immer Ihr dies heutzutage nennt. Ich habe mein Wort gegeben, dass ich alles in meiner Macht Stehende tun würde, um Euch und die Euren bereit zu machen, Eure Heimat zurückzuerobern... und genau das werde ich jetzt tun.\n\nWann immer Ihr bereit seid, kommt zurück zum alten Thran und ich werde mein Wissen gern mit Euch teilen. Für meine Unterweisungen nehme ich eine geringe Gebühr, aber es wird nicht zu teuer. Viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[3113] = { id = 3113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsseltes Memorandum", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Schurkenlehrer Solm. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", sourceObjective = "Lest das verschlüsselte Memorandum und sprecht mit Solm Hargrin im Coldridgetal.", progress = "Bin froh, dass Ihr meine Nachricht erhalten habt und mich hier aufsucht. Tut mir Leid, dass ich vorgeben musste, das Memorandum stamme von einem Eurer Vorgesetzten... war nicht böse gemeint. Ich weiß einfach, dass wir beide, gemeinsam mit den anderen unserer Art, zusammenhalten müssen.\n\nNicht viele glauben, dass es gut ist, wenn sich Eure Art und meine Art in derselben Stadt verschanzen, aber ich denke, wir bekommen das schon gut hin. Was meint Ihr?", completion = "Ich bin hier in der Gegend ziemlich für mich geblieben, sodass man uns für fehlende Dinge nicht verantwortlich macht; doch wenn Ihr etwas benötigt, Unterweisung oder sonst was, kommt gern auf mich zurück.\n\nIhr und ich, wir verstehen einander. Wir wissen, dass man im Grunde nur der Familie trauen kann - und das ist genau das, was wir hier sein werden, nicht wahr? Ungeachtet dessen, dass Gnomeregan... überrannt wird und was sich uns auch sonst in den Weg stellen mag, wir geben uns gegenseitig Rückendeckung. Nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[3114] = { id = 3114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphen-Memorandum", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Magielehrer Marryk. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", sourceObjective = "Lest das mit Glyphen versehene Memorandum und sprecht mit Marryk Nurribit in Anvilmar oberhalb des Coldridgetals.", progress = "Ja, wie war das, {race}? Sprecht lauter, bitte. Nach einigen Bieren höre ich nicht mehr so gut.", completion = "Oh, ja! Arkane Künste... klaro.\n\nDas müsst Ihr wissen, {name}: Geht Ärger möglichst aus dem Weg. Spart einige Münzen auf, um mir ein Bier zu kaufen... oder irgendwelche Zauber, die Ihr wollt. Und bleibt auf jeden Fall weg von Gnomeregan. Ansonsten wünsche ich Euch einen angenehmen Tag! Ich werde hier sein, wenn Ihr mich braucht oder trainieren wollt... oder was auch immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[3115] = { id = 3115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudeltes Memorandum", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Hexenmeisterlehrer Alamar. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.\n\nUnd passt auf Euch auf, {name}, man traut Leuten wie Euch hierzulande nicht gerade.", sourceObjective = "Lest das besudelte Memorandum und sprecht mit Alamar Grimm in Anvilmar oberhalb des Coldridgetals.", progress = "Großartig! Offensichtlich habt Ihr mein Memorandum erhalten.\n\nIgnoriert die Narren um Euch herum, {name}. Das Heilige Licht?! Das Schwert und Schild?! Dies sind keine Wege für jemanden mit einem so offenen Geist, wie wir ihn haben. Seht, wie \"normale\" Magie Eure Heimat zugerichtet hat. Zusammen mit diesen verdammten Tüftlern wurde unser Volk beinahe ausgerottet! Und jetzt müssen wir auf die Zwerge vertrauen - und die würden sich eher mit den Menschen verbünden, als uns beim Wiederaufbau unserer Heimat zu helfen. Wir sind wie Bürger zweiter Klasse. Habt Ihr gesehen, wie sie uns ansehen?", completion = "Aber nichts davon zählt wirklich. Was zählt ist, dass Ihr Euer eigenes Heiliges Licht gesehen habt! Ihr wisst, woher die Macht wirklich stammt. Ihr erkennt, dass es sehr viel... weiser ist, unsere eigenen Verbündeten zu haben. Spezielle Verbündete. Verbündete, die, ungeachtet der Aufgabe, bis zum letzten Atemzug gehorchen.\n\nUnd da komme ich ins Spiel, {name}. Ich kann Euch die Anfänge dieser speziellen Mächte lehren. Sucht mich häufig auf und ich werde tun, was in meiner Macht steht, um Euch weitere Zauber zu lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[3116] = { id = 3116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfaches Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Kriegerlehrerin Alyissia überreicht. Es sieht so aus, als wollte Alyissia ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", sourceObjective = "Lest das einfache Siegelzeichen und sprecht mit Alyissia in Shadowglen.", progress = "Ihr habt es hierher geschafft. Ich bin so froh.\n\nViel ist in den letzten Jahren geschehen, {name}: Die Erbauung von Teldrassil, die Verderbnis vieler Kreaturen des Waldes hier und in der Fremde, die Entdeckung von Ländern, von denen wir dachten, sie seien für uns verloren wie Feralas ..., so viel in so kurzer Zeit. Aber dies sind nur einige der Gründe, warum wir hier sind, der wichtigste ist, unsere Art vor weiterem Bösen zu schützen.", completion = "Bald werdet Ihr Angehörige anderer Völker im Geäst unserer Heimat sehen... lasst keine Vorurteile in Euch aufkommen. Sie sind willkommen. Sie werden uns helfen, wenn sie können. Nicht alle von ihnen tun dies aus purer Selbstlosigkeit, es sollte ihnen jedoch ein bisschen Vertrauen entgegengebracht werden.\n\nAber all das ist jetzt nicht wichtig. Jetzt müssen wir uns auf Euch konzentrieren und wie Ihr unserem Volk helfen könnt. Aus diesem Grund bin ich auch hier. Ich werde Euch in den Fertigkeiten eines Kriegers unterweisen, während Ihr stärker und stärker werdet. Kehrt zu mir zurück, wann immer Ihr wollt, und ich werde alles in meiner Macht Stehende tun, um Euch zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3117] = { id = 3117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geätztes Siegelzeichen", description = "Dieses Siegelzeichen  wurde mir durch einen Boten von unserer Jägerlehrerin Ayanna überreicht. Es sieht so aus, als wollte Ayanna ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", sourceObjective = "Lest das geätzte Siegelzeichen und sprecht mit Ayanna Everstride oben auf Aldrassil in Shadowglen.", progress = "Ihr seid im passenden Moment eingetroffen, {name}. Willkommen in Shadowglen.\n\nIch hoffe, mein Siegelzeichen erreichte Euch bei guter Laune und Gesundheit.\n\nWie ich bereits sagte, bin ich hier, um Euch als geschickten {class} auszubilden. Das bedeutet, Ihr werdet lernen, wie man Wildtiere zähmt, damit sie Euch im Kampf helfen, wie man den Bogen mit unfehlbarer Zielsicherheit einsetzt. Ihr werdet lernen, das Land, das wir Heimat nennen, zu respektieren und ebenso die Länder jenseits davon.", completion = "Während Ihr erlebt was Shadowglen Euch lehren kann, kommt und besucht mich - ich kann Euch dabei behilflich sein, Eure Aufgabe als {class} besser zu verstehen und zu erkennen, zu was Ihr fähig seid.\n\nWir leben in gefährlichen Zeiten, {name}, nehmt die Fertigkeiten Eurer Tiere nicht als gegeben an - es gibt in dieser Welt gefährlichere Dinge als Ihr Euch vorzustellen vermögt. Geht mit Elune und kommt wieder zu mir zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[3118] = { id = 3118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselte Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Schurkenlehrerin Frahun überreicht. Es sieht so aus, als wollte Frahun ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", sourceObjective = "Lest das verschlüsselte Siegelzeichen und sprecht mit Frahun Shadwhisper in Shadowglen.", progress = "Hallo, {name}. Ich bin erfreut, dass Ihr mich gefunden habt, ich dachte schon, Ihr hättet Euch vielleicht auf dem Weg hierher verirrt.\n\nSeitdem ich Euch mein Siegelzeichen sandte, ist nicht viel Neues in Shadowglen passiert, aber ich überlasse es Euch, Informationen zu sammeln. Ihr könnt gern mit den anderen Leuten in Aldrassil sprechen, wenn Ihr möchtet.", completion = "Bis dahin solltet Ihr wissen, dass unsere Art in diesen bedrückenden Zeiten mehr als sonst gebraucht wird. Der Frieden mit den anderen Völkern kann jeden Moment zusammenbrechen und es wird häufig von Mitgliedern der Horde berichtet, die sich bemühen, eine immer größere Saat des Misstrauens zu säen. Bedenkt dies.\n\nKommt zu mir zurück, wenn Ihr stärker geworden seid und Euch besser vorbereitet fühlt und ich werde mich um Eure Ausbildung kümmern. Es ist unter anderem sehr wichtig, dass Ihr mit der Waffe Eurer Wahl gut umgehen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3119] = { id = 3119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligtes Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Priesterlehrerin Shanda überreicht. Es sieht so aus, als wollte Shanda ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", sourceObjective = "Lest das geheiligte Siegel und sprecht mit Shanda in Aldrassil.", progress = "Ich bin sehr erfreut, dass Ihr so schnell eingetroffen seid, {name}. Willkommen.\n\nWie Ihr vielleicht bereits gehört habt, herrscht in ganz Teldrassil ein ständiges Kommen und Gehen von Reisenden. Sogar den Mitgliedern der Allianz wurde der Zutritt zu Teldrassils Ästen erlaubt, um sich mit anderen Kaldorei zu treffen, die sich auf die kommenden Abenteuer vorbereiten.", completion = "Aber im Moment müsst Ihr Euch nicht um die Welt unterhalb von Teldrassil kümmern. Dafür ist später noch Gelegenheit. Geht nun und sprecht mit den anderen in Shadowglen - sie können Euch mehr von den Ereignissen berichten, die sich zugetragen haben. Helft Ihnen so gut Ihr es vermögt, und wenn Ihr das Gefühl habt, weitere Ausbildung zu benötigen, kommt zu mir zurück und ich werde Euch lehren, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[3120] = { id = 3120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefgrünes Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserem Druidenlehrer Mardant überreicht. Es sieht so aus, als wollte Mardant ein paar Worte mit Euch wechseln, wenn Ihr einen Moment Zeit habt. Lest es und bringt es dann zu ihm.", sourceObjective = "Lest das tiefgrüne Siegel und sprecht mit Mardant Strongoak im großen Baum Aldrassil in Shadowglen.", progress = "Ah, {class}. Ich sehe, dass Ihr es kaum erwarten könnt, Eure Studien fortzuführen. Gut.\n\nIch frage mich, ob Ihr schon viel Zeit im Smaragdgrünen Traum verbracht habt... Vielleicht seid Ihr darauf noch nicht genügend vorbereitet... Irgendwann wird es so weit sein, ganz sicher.\n\nDoch bis dahin sollten wir andere Dinge besprechen.", completion = "Vorerst werde ich Euer Mentor und Führer sein. Es ist meine Pflicht, Euch nicht nur zu lehren, wie man die Mitteilungen der Geister deutet, sondern auch die Komplexität und Geheimnisse des Smaragdgrünen Traums.\n\nJe mehr Ihr lernt und an Macht gewinnt, desto mehr werdet Ihr auch über unseren tranceähnlichen Schlaf erfahren. Aber bis dahin dürft Ihr so oft Ihr wollt zu mir kommen, und ich werde Euch alles, was ich über die Wege unserer Art weiß, lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[3121] = { id = 3121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Anforderung", description = "Neeru Fireblade in Orgrimmar hat, was ich brauche, um hier beginnen zu können! Er hat ein Gebräu zusammengemischt, das ich für mein... na, Ihr werdet es schon sehen.\n\nAb mit Euch... nach Orgrimmar. Hier, nehmt das mit. Es ist ein Schrumpfkopf, den ich Neeru im Tausch für die Kräuter versprochen habe. Es ist der Kopf eines armen Zwergs, der mir im Wald über den Weg gelaufen ist. Ich bin sicher, dass Neeru sehr erfreut sein wird.\n\nIhr werdet Neeru in der Kluft der Schatten finden.", sourceObjective = "Bringt den Schrumpfkopf zu Neeru Fireblade in Orgrimmar.", progress = "Ja?", completion = "Ich habe schon darauf gewartet, dass Uzer'i mir das bringt...\n\nIch möchte Euch diese Kräutermixtur geben, die ich für seine... ähm, Experimente vorbereitet habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[3122] = { id = 3122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Hexendoktor Uzer'i zurück", description = "Hier sind die Kräuter, {name}. Bringt sie zu Hexendoktor Uzer'i.\n\nUnd sagt ihm, dass ich mit dem Schrumpfkopf sehr zufrieden bin.", sourceObjective = "Bringt Neerus Kräuterbeutel zu Hexendoktor Uzer'i in Feralas.", progress = "Habt Ihr mit Neeru gesprochen?", completion = "Das ist genau das, was ich benötige, um das Muisekgefäß vorzubereiten, {name}. Bald schon werden wir sehen, ob meine neuesten Beschwörungen so mächtig sind wie ich gehofft hatte.\n\nEinen Moment, bitte. Ich muss das Ritual durchführen und die Kräuter ansetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3123] = { id = 3123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gefäß wird getestet", description = "Dies ist ein Test, sowohl für das Ritual, das ich durchgeführt habe, als auch für Eure Fähigkeiten. Nehmt dieses Gefäß, {name}. Damit habt Ihr die Macht, eine Kreatur zu schrumpfen und sie darin gefangen zu nehmen.\n\nReist ins Hinterland und sucht nach Kreaturen, die als Wildekin bekannt sind. Sie waren einst die Tiere der Nachtelfengöttin Elune. Die heimtückischen, primitiven oder wilden Eulenbestien sollen Euer Ziel sein, {name}. Vernichtet 10 und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen, bevor ihr Geist flüchten kann.", sourceObjective = "Reist ins Hinterland und spürt die Wildekin auf. Schaltet 10 davon aus und benutzt dann das Muisekgefäß, um die gefallenen Wildekin zu schrumpfen und einzufangen.\n\nBringt anschließend 10 Einheiten Muisek von Wildekins und das Muisekgefäß zu Hexendoktor Uzer'i in Feralas.", progress = "Konntet Ihr einen Wildekin einfangen?\n\nWenn Ihr Erfolg habt, sind wir in der Lage, die Kreaturen von Feralas zu schrumpfen und deren Muisek einzufangen.", completion = "Bei einem grausamen Tod ist es möglich, dass das Muisek der Kreatur entkommt und Rache sucht. Durch das Schrumpfen der Kreaturen, wie Ihr es getan habt, {name}, kann das Muisek nicht entfliehen. Jetzt können wir ihn so benutzen, wie es uns gefällt!", sourceObjectiveStatus = "unverified-source-field" }
quests[3124] = { id = 3124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Hippogryphen", description = "Da Ihr bewiesen habt, dass Ihr vertrauenswürdig und auch in der Lage seid, das Muisekgefäß zu benutzen, möchte ich, dass Ihr eine weitere Kreatur einfangt.\n\nHippogryphen sind seit vielen Jahren die treuen Gefährten der Nachtelfen. Ihre Geister sind loyal und unerschütterlich.\n\nEure Aufgabe besteht darin, 10 Fransenfederhippogryphen auszuschalten, sie schnell zu schrumpfen und mit dem Gefäß einzufangen, sodass ihr Muisek erhalten bleibt. Ihr findet die Hippogryphen in der oberen Wildnis, südlich von hier.", sourceObjective = "Schaltet 10 Fransenfederhippogryphen eines beliebigen Typs aus und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen.", progress = "Konntet Ihr die Hippogryphen einfangen?", completion = "Wenn wir ein Tier töten und dem Muisek erlauben, zu entfliehen, kann es die Gestalt einer noch größeren Kreatur annehmen. Wir wären niemals sicher vor seiner Rache.\n\nIch hatte Euch mit einer gefährlichen Aufgabe betraut, {name}. Und wieder habt Ihr sie gut bewältigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3125] = { id = 3125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Feendrachen", description = "{name}, als Nächstes müsst Ihr für mich eine Kreatur fangen, die vom Aussehen her sehr zerbrechlich scheint, aber ihr mächtiger Geist ist das, was wir eigentlich besitzen wollen. Die Feendrachen, von denen ich spreche, dienen den Nachtelfen als Verbündete. Wir müssen einen von ihnen einfangen, damit auch die Horde von seiner Geisteskraft profitieren kann.\n\nHier ist das Muisekgefäß, {name}. Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus und fangt ihr Muisek ein. Ihr könnt sie westlich von hier finden.", sourceObjective = "Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus. Benutzt das Muisekgefäß, um die gefallenen Feendrachen zu schrumpfen und einzufangen.", progress = "Konntet Ihr das Muisek der Feendrachen einfangen?", completion = "Danke, {name}. Jetzt steht die geistige Macht der Feendrachen auch uns zur Verfügung.\n\nIch hoffe, Ihr seid willens, eine weitere Aufgabe für mich zu vollbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3126] = { id = 3126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Treants", description = "Die umherwandernden Waldgänger, die überall im Wald zu finden sind, sind unser nächstes Ziel, {name}. Nachtelfen haben Treants als Verbündete rekrutiert, um gegen die Horde zu kämpfen. Sie mögen zwar langsam sein, aber als Beschützer sind sie nicht zu unterschätzen.\n\nBald werden wir diese Macht für unsere eigenen Zwecke nutzen können.\n\nFindet 3 umherwandernde Waldgänger, schaltet sie aus und benutzt das Muisekgefäß, um sie zu schrumpfen und einzufangen.", sourceObjective = "Schaltet 3 umherwandernde Waldgänger aus. Benutzt das Muisekgefäß, um die gefallenen Treants zu schrumpfen und einzufangen.", progress = "Konntet Ihr die umherwandernden Waldgänger einfangen?", completion = "Danke, {name}. Unsere Muiseksammlung ist nahezu vollständig.", sourceObjectiveStatus = "unverified-source-field" }
quests[3127] = { id = 3127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Bergriesen", description = "Bei der letzten Aufgabe, die ich Euch stelle, sollt Ihr nach Nordwesten reisen und den letzten Feind finden.\n\nAls die Brennende Legion in der Welt erschien, haben die Bergriesen ihre Berge verlassen, um den Nachtelfen zu helfen. Ihr erkennt sie an ihrer enormen Größe und daran, wie der Boden erzittert, wenn Ihr durch ihr felsiges Gelände reist.\n\nIch kann es kaum erwarten, eine Macht von dieser Größe zu zähmen. Schaltet 7 Bergriesen aus und benutzt dann das Muisekgefäß, um ihr mächtiges Muisek einzufangen.", sourceObjective = "Schaltet 7 Landgänger oder Klippenriesen aus. Benutzt das Muisekgefäß, um die gefallenen Bergriesen zu schrumpfen und einzufangen.", progress = "Konntet Ihr die Bergriesen einfangen?", completion = "Denkt nur an all die Möglichkeiten, die wir jetzt besitzen, {name}. Zusammen mit den Materialien, die Ihr gesammelt habt, kann ich nun das Muisek dieser Kreaturen auf ewig in jeglicher Gestalt gefangen halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[3128] = { id = 3128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natürliche Materialien", description = "Ich benötige bestimmte Materialien, um mein Vorhaben zu vervollständigen... Ihr könnt das für mich erledigen, zusammen mit den anderen Aufgaben, die ich Euch stellen werde.\n\nIch brauche einen abgesplitterten Stamm eines Treants aus Feralas. Verkrustete Mineralien könnt Ihr an den Bergriesen und Feendrachen im Westen finden. Sucht mir einige widerstandsfähige Sehnen von den Eulenbestien im Hinterland oder den Hippogryphs von Feralas. Als Letztes benötige ich eine große Menge metallischer Fragmente von einer der Bestien, die ich erwähnt habe.", sourceObjective = "Bringt 2 abgesplitterte Baumstämme, 6 verkrustete Mineralien, 20 Stücke widerstandsfähige Sehne und 40 metallische Fragmente zu Hexendoktor Uzer'i ins Camp Mojache.", progress = "Konntet Ihr die Materialien, die ich benötige, finden?", completion = "Exzellent! Diese Materialien, zusammen mit dem Muisek, sollten uns genau die Ergebnisse liefern, die wir benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3129] = { id = 3129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen des Geistes", description = "Es ist ein äußerst komplizierter Vorgang, die Waffen mit dem Muisek zu erfüllen. Aber da ich jetzt sowohl über alle erforderlichen Materialien als auch über das Muisek der von Euch eingefangenen Kreaturen verfüge, kann ich endlich beginnen. Bitte wartet hier, ich werde gleich zurück sein.", sourceObjective = "Hexendoktor Uzer'i will, dass Ihr einen Moment wartet, während er die Waffen vorbereitet.", completion = "Wie versprochen, habt Ihr nun die Wahl, {name}. Das Muisek dieser Kreaturen wurde auf ewig in die Macht dieser Waffen eingeschlossen.\n\nIhre Energie ist nun die Eure. Verwendet sie gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[3130] = { id = 3130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Hasskämme", description = "Ich werde Euch jetzt zu meinem Stellvertreter Lactronicus schicken. Er hat bisher ein wachsames Auge auf die Nagastreitkräfte gehabt. Ich werde die allgemeine Lage hier in Bezug auf die Naga bewerten. Liebend gern würde ich eine ganze Armee gegen sie aussenden, aber es ist nicht unbedingt ratsam, die Festung einem direkten Angriff der Horde - oder Schlimmerem - schutzlos auszusetzen.\n\nWie dem auch sei, Latronicus erwartet Euch. Gute Arbeit bisher, {name}. Nur weiter so.\n\nIhr könnt wegtreten.", sourceObjective = "Meldet Euch bei Latronicus Moonspear in der Festung Feathermoon.", completion = "Exzellent, {name}... ich schätze eine \"Geht klar\"-Einstellung bei Leuten, mit denen ich arbeite.\n\nIch wurde von General Feathermoon beauftragt, die Naga direkt anzugehen. Mein Plan besteht aus zwei Teilen: Abschnitt eins sieht vor, dass wir sie sowohl zahlenmäßig als auch hinsichtlich ihrer Befehlshaber schwächen, und danach werden wir herausfinden, was sie in den Ruinen vorhaben. Mit Eurer Hilfe werden wir den Naga entgegentreten, ohne die allgemeine Sicherheit der Festung zu beeinträchtigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3141] = { id = 3141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loramus", description = "Ihr wollt also gegen Dämonen kämpfen? Dann tätet Ihr gut daran, Euch meine Geschichte anzuhören.", sourceObjective = "Lasst Loramus Thalipedes seine Geschichte erzählen.", progress = "Unterbrecht mich nicht, {race}.", completion = "So sei es...", sourceObjectiveStatus = "unverified-source-field" }
quests[3161] = { id = 3161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gahz'ridian", description = "{name}, ich bin zwar Wissenschaftler, aber im Grunde meines Herzens bin ich auch Schatzsucher!\n\nVor langer Zeit, als Trolle dieses Land besetzt hielten, schufen sie eine große Anzahl von Ornamenten nach dem Vorbild der Gahz'rilla, einer Hydra, die sie als Göttin verehrten. Diese Ornamente werden aus einem Element herausgeschnitzt, das ich nach der Hydragöttin \"Gahz'ridian\" nenne.\n\nIch selbst habe schon einige dieser Ornamente gefunden, aber ich hätte gern noch mehr, um sie zu untersuchen - vielleicht findet Ihr ja noch welche ...\n\nIch habe sogar einen Detektor erfunden, der es zu einem Kinderspiel macht, Gahz'ridian zu finden! Legt ihn einfach an und die Suche kann beginnen!", sourceObjective = "Marvon Rivetseeker in Tanaris möchte, dass Ihr 30 Gahz'ridian-Ornamente sammelt.", progress = "Habt Ihr Probleme?\n\nIhr könnt Gahz'ridian fast überall in Tanaris finden, {name}, also sucht weiter!", completion = "Perfekt, diese Ornamente sind einfach perfekt für meine Studien. Ich danke Euch sehr für Eure Hilfe, {name}.\n\nAch ja, kann ich meinen Helm zurückhaben?", sourceObjectiveStatus = "unverified-source-field" }
quests[3181] = { id = 3181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn der Bestie", description = "Das gigantische Horn hat viele Kratzer und Risse. Ein ungewöhnliches Metallobjekt klemmt in der rauen Oberfläche fest.\n\nBeim näheren Hinschauen entdeckt Ihr, dass das Metall in Wirklichkeit ein zerbrochener Axtkopf ist. In das Metall wurden diese Wörter eingeätzt:\n\nEigentum von Gebirgsjägerin Pebblebitty.\n\nAls Ihr versucht, den zerbrochenen Axtkopf herauszuziehen, zerfällt er in unzählige Teile.\n\nUps!", sourceObjective = "Bringt Margols gigantisches Horn zu Gebirgsjägerin Pebblebitty.", progress = "Nein, ich werde das Tor nicht öffnen.", completion = "Was habt Ihr denn da? Offensichtlich eine Fälschung!\n\nIch stand Margol von Angesicht zu Angesicht gegenüber und weiß ganz genau, dass das Horn mindestens acht Mal so groß ist wie dasjenige, das Ihr in Euren Händen haltet, {name}. Das da habt Ihr wahrscheinlich von einer Sturmschnauze aus dem Brachland. Nein, werter Herr, Pebblebitty könnt Ihr nichts vormachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[3182] = { id = 3182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besitznachweis", description = "Ihr erwartet wirklich, dass ich eine solche Geschichte glaube? Wenn es das echte Horn wäre, dann würde meine zerbrochene Axt ja immer noch drinstecken.\n\nHört zu, bringt diese dreiste Fälschung zu Kurator Thorius in Ironforge. Falls er Eure Behauptung bestätigt, werdet Ihr eine Beweisurkunde für Eure Tat erhalten. Bringt mir diesen Beweis und ich werde Euch den Schlüssel für die sengende Schlucht geben.\n\nGeht schon!", sourceObjective = "Bringt Margols gigantisches Horn zu Kurator Thorius in Ironforge.", progress = "Ah, guten Tag, junger Herr. Hättet Ihr gern eine Führung durch das Museum?", completion = "Was ist denn das?\n\nOh nein, das kann ich gar nicht glauben! Wisst Ihr, was Ihr da habt, {race}? Dies ist das Horn von Margol! Margol ist der Fluch eines jeden Archäologen, der jemals seinen Fuß in die sengende Schlucht gesetzt hat.\n\nKann ich es behalten?", sourceObjectiveStatus = "unverified-source-field" }
quests[3201] = { id = 3201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich!", description = "Ich kann kaum glauben, dass Pebblebitty die Echtheit des Horns angezweifelt hat. Unter uns, ich denke, sie ist einfach nur eifersüchtig. Ich weiß, dass sie diese Bestie gern selbst getötet hätte, nach dem, was bei dem 'Ereignis' so vorgefallen ist.\n\nIhr braucht also eine Urkunde für Eure Tat? Nachdem Ihr nun gerade dem Museum ein solches Geschenk gemacht habt, sollte das kein Problem sein.\n\n<Kurator Thorius fängt an, ein großes Dokument auszufüllen.>\n\nHier bitte! Das könnt Ihr Pebblebitty zurückbringen.", sourceObjective = "Bringt die Urkunde für die Tat zurück zu Gebirgsjägerin Pebblebitty.", progress = "Ich kann es nicht glauben.", completion = "Ich weiß zwar nicht, wie jemand, der so schwach ist wie Ihr, Margol überwältigen konnte, aber eine Abmachung ist eine Abmachung. Hier habt Ihr den Schlüssel.\n\nSollte Euch jetzt etwas zustoßen, ist es Eure eigene Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[3221] = { id = 3221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Renferrel", description = "Während Ihr fort wart, um unseren Todespirschern zu helfen, hat Apotheker Renferrel Euch eine Einladung geschickt. Er hat mir keinerlei Einzelheiten mitgeteilt, aber er wollte mit Euch über die Wolfherzen sprechen, die Ihr ihm gegeben habt.", sourceObjective = "Sprecht mit Apotheker Renferrel in dem Grabmal.", completion = "Ah, sehr gut. Es gibt da etwas bezüglich der Wolfherzen, die Ihr mir gebracht habt, das unserer Aufmerksamkeit bedarf.", sourceObjectiveStatus = "unverified-source-field" }
quests[3261] = { id = 3261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorn Skyseer", description = "Eure Zeit bei mir ist vorbei, {name}. Wenn Ihr mehr lernen wollt, müsst Ihr ins Camp Taurajo gehen und mit Jorn Skyseer sprechen. Er wird Eure Weiterbildung übernehmen.", sourceObjective = "Sprecht im Camp Taurajo mit Jorn Skyseer.", completion = "Seid gegrüßt. Ihr seid hier, um den Pfad des Jägers zu beschreiten?\n\nSehr gut. Lasst uns beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3281] = { id = 3281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlenes Silber", description = "Ihr habt zwar die Raptoren getötet, aber das Silber, das sie gestohlen haben, muss wiederbeschafft werden! Ich habe Berichte darüber, dass die Raptoren eine große Ansammlung von Nestern südlich von Ratchet haben, Raptorgründe genannt. Es ist sehr wahrscheinlich, dass sie unser gestohlenes Silber dorthin gebracht haben.\n\nGeht zu dieser Raptorzuflucht und haltet nach dem gestohlenen Silber Ausschau. Wenn Ihr es gefunden habt, kommt damit zu mir zurück.", sourceObjective = "Bringt das gestohlene Silber zu Gazrog in Crossroads.", progress = "Habt Ihr das Silber?", completion = "Aha! Also haben die Raptoren das Silber in ihrem Unterschlupf versteckt. Es ist kaum zu glauben, dass es diese Bestien nach Silber verlangt. Vielleicht sind diese Geschichten über ihre Intelligenz doch nicht so weit von der Wahrheit entfernt, wie ich dachte.\n\nDanke, {name}. Nehmt dies als Belohnung für Eure uns erwiesenen Dienste und wisset, dass die Wachen am Scheideweg ihren nächsten Monatslohn Euch verdanken.", sourceObjectiveStatus = "unverified-source-field" }
quests[3301] = { id = 3301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mura Runetotem", description = "Meine Klangefährtin, Mura Runetotem, ist nach Silberwald gereist, um unseren untoten Verbündeten zu helfen. Der Silberwald ist ein kranker Wald, ein sterbender Wald, und Muras Hoffnung war, ihm neues Leben zu bringen. Vielleicht kann dieses seltsame Leben, das wir im Brachland gefunden haben, ihr bei ihrer Arbeit im Silberwald helfen.\n\nBringt eine Probe der von Euch gesammelten Schalen zu Mura nach Silberwald. Sie hält sich in dem Grabmal auf. Mit etwas Glück vermittelt ihr das Studium der Schalen den Einblick, den sie benötigt, um diesen sterbenden Ort zu heilen.", sourceObjective = "Sprecht mit Mura Runetotem in dem Grabmal.", progress = "Ich kann den Staub des Brachlandes an Euch riechen, {class}. Ihr seid weit gereist.", completion = "Ah... was ist denn das? Diese Schale glüht von innen, als ob in ihr noch Leben pulsierte. Erstaunlich! Ich muss sie weiter untersuchen.\n\nDanke, {name}. Wenn wir Glück haben, enthält diese Schale ein Geheimnis, das ich verwenden kann, um dem armen Land Silberwald zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3321] = { id = 3321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Habt Ihr das verloren?", description = "Ihr habt viel für den Orden getan, {name}. Allein die Hingabe, derer es bedarf, um hierher zu gelangen, hätte jede normale Person abgehalten. Galvan und auch ich haben keinerlei Zweifel, dass Ihr einer von uns seid.\n\nAus diesem Grund denke ich, dass Ihr Euch eine kleine Belohnung verdient habt. Es ist nichts Besonderes, nur eine Kleinigkeit. Vielleicht sind Euch seine Eigenschaften vertraut, denn ich glaube, dass es der Grund war, warum Ihr überhaupt zu uns gekommen seid.", sourceObjective = "Wartet, bis Trenton seine Arbeit erledigt hat.", completion = "Erhebt Euch und seid gewürdigt, {name}, Schmied des Mithrilordens.", sourceObjectiveStatus = "unverified-source-field" }
quests[3341] = { id = 3341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende bringen", description = "Im Brachland liegt ein schreckliches Dickicht aus ineinander verschlungenen Ranken, Hügel von Razorfen genannt. Unsere ersten Beobachtungen haben zwar auf keine große Bedrohung schließen lassen, aber die neuesten Funde geben doch allen Grund zur Sorge...\n\nDie Stacheleber der Hügel von Razorfen haben sich mit der Geißel zusammengetan. Ein Lich namens Amnennar der Kältebringer beherrscht sie jetzt und nutzt die Macht seines riesigen Bewusstseins, um jede ihrer Bewegungen zu kontrollieren.\n\nAmnennar verfügt über eine direkte telepathische Verbindung zu Ner'zhul. Diese Bindung müssen wir durchtrennen, {name}. Dem Kältebringer muss ein Ende gemacht werden.", sourceObjective = "Andrew Brownell will, dass Ihr Amnennar den Kältebringer tötet und ihm dessen Schädel bringt.", progress = "Diese Angelegenheit ist von äußerster Wichtigkeit, {name}. Wir müssen jeden Versuch der Geißel zunichte machen, ihre Reihen zu vergrößern.", completion = "Die Loyalität eines Lich ist unerschütterlich, {name}. Lasst sie wissen, dass diese Loyalität ihnen nur Verderben bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3361] = { id = 3361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dilemma eines Flüchtlings", description = "Wir haben die Troggs aus Gnomeregan vertrieben, aber dann ist alles schrecklich schief gegangen! Jetzt ist unsere Heimat völlig von Strahlen verseucht und wir Gnome sind überall in Dun Morogh zerstreut.\n\nIn meiner Hast, der Strahlung zu entkommen, habe ich all mein ganzes Hab und Gut und auch meine Werkzeuge verloren. Die Trolle haben sie geholt. Sie haben meine Truhe, meine Kiste, und meinen Bolzeneimer gestohlen! Alles das haben sie in ihre Lager südwestlich von Anvilmar mitgenommen.\n\nIch bin nur leider kein Abenteurer - könntet Ihr bitte meine Sachen suchen und sie mir herbringen?", sourceObjective = "Bringt Felix Whindlebolt in Anvilmar den Kasten, die Truhe und den Bolzeneimer von Felix.", progress = "Liebe Güte {name}, diese Stadt ist für Leute wie mich nicht sehr geeignet. Hier gibt es ja ebenso viele widerliche Kreaturen wie in Gnomeregan vor diesem Unfall!\n\nHabt Ihr meine Habseligkeiten? Falls nicht... oje, wer weiß, was die Trolle damit angestellt haben...", completion = "Hurra, Ihr habt sie gefunden! Ihr seid wirklich eine echte Hilfe. Hier, es ist zwar nicht viel, aber doch etwas, um Euch für den Ärger zu entlohnen, den Ihr meinetwegen hattet. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[3362] = { id = 3362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disteltal", description = "Habt Ihr jemals das Disteltal gesehen? Es ist ein sehr gefährlicher Ort, {name}.\n\nDiesen merkwürdigen Bestien dort traue ich nicht für eine Minute! Ich glaube, man nennt sie knorrige Distelwandler und Distelwurzelformer...\n\nIch möchte in das Tal hinein, aber solange es dort von Distelwandlern wimmelt, kehre ich auf keinen Fall dorthin zurück. Und an dieser Stelle kommt Ihr ins Spiel - wenn Ihr einige von ihnen erledigt, würde ich vielleicht doch dorthin zurückkehren. Was meint Ihr, {name}? Helft Ihr mir?", sourceObjective = "Tran'rek in Gadgetzan möchte, dass Ihr 8 knorrige Distelwandler und 8 Distelwurzelformer erledigt.", completion = "So groß sind die? Ich muss meinen Plan vielleicht noch einmal überdenken...\n\nAber Ihr habt Euren Teil der Abmachung gehalten, also bekommt Ihr auch, was ich versprochen habe. Hier, nehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3363] = { id = 3363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Liedblume", description = "Nehmt mich auf.", sourceObjective = "Blah.", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", sourceObjectiveStatus = "unverified-source-field" }
quests[3364] = { id = 3364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung des kochend heißen Morgengebräus", description = "Bah! Ich sollte dieses köstliche, kochend heiße Morgengebräu schon vor einer ganzen Weile zu Durnan Furcutter im Anvilmar bringen, aber ich musste erst eine Ladung zu Grelin hier bringen. Ich werde es niemals bis nach Anvilmar schaffen, bevor das Gebräu kalt wird!\n\nIhr seht hurtig aus. Vielleicht könnt Ihr es schaffen. Diese Tasse wird nur noch fünf Minuten lang heiß bleiben, und Durnan bestellte kein \"eisiges\" Morgengebräu, also beeilt Euch. Anvilmar liegt im Nordosten. Es ist eine Siedlung, die in den Berg gebaut wurde.\n\nDanke, {name}, und vergesst nicht, mir meinen Becher zurückzubringen!", sourceObjective = "Bringt ein kochend heißes Morgengebräu zu Durnan Furcutter ins Anvilmar hinein, bevor es innerhalb von fünf Minuten kalt wird!", progress = "Jawohl, ich bin Durnan Furcutter. Habt Ihr denn etwas für mich?", completion = "Ah, sehr gut, das trifft sich ja wunderbar. Erlaubt mir eine kleine Pause, um dieses kochend heiße Morgengebräu zu genießen!", sourceObjectiveStatus = "unverified-source-field" }
quests[3365] = { id = 3365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Becher zurückbringen", description = "Das kam genau zur rechten Zeit! Es geht doch nichts über ein heißes - neee, KOCHEND HEISSES Morgengebräu an einem kalten Wintertag, um einem das Herz zu wärmen.\n\nHier, bitte {name}... seid so nett und bringt für mich den leeren Becher zurück zu Nori, ja?", sourceObjective = "Bringt Nori Pridedrift den Becher zurück.", progress = "Ich hoffe ja, dass das kochend heiße Morgengebräu Durnan rechtzeitig erreicht hat! Habt Ihr daran gedacht, mir meinen Becher zurückzubringen?", completion = "Exzellent, {name}! Ihr wärt überrascht, wenn ich Euch erzähle, wie viele Kuriere etwas so Einfaches wie das Zurückbringen des Bechers vergessen. Es heißt nicht umsonst, dass Becher nicht auf Bäumen wachsen!\n\nHier habt Ihr etwas für Eure Mühe. Ich danke Euch nochmals für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[3366] = { id = 3366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der leuchtende Splitter", description = "Der Splitter ist von einem glänzenden Grün und obwohl er fest ist, scheint etwas wie Rauch genau unterhalb der Oberfläche herumzuwirbeln. Ihr möchtet am liebsten in die Tiefen des Kristalls schauen, aber gleichzeitig wisst Ihr, dass es etwas sehr Beunruhigendes damit auf sich hat.\n\nVielleicht solltet Ihr in Ratchet nach jemandem suchen, der Euch mehr über diesen seltsamen Splitter erzählen kann.", sourceObjective = "Reist nach Ratchet, um die Bedeutung des Alptraum-Splitters herauszufinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[3367] = { id = 3367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suntara-Steine", description = "<Dorius stöhnt.>\n\nIch bin schwer verletzt, {race}. Fühle mich... benommen... Alles dreht sich... Innere... Blutungen.\n\nIch muss zurück nach Ironforge. Helft mir, {name}.", sourceObjective = "Helft Dorius, zurück nach Ironforge zu kommen.", progress = "Ich schaffe es nicht...", completion = "Dorius ließ diesen Brief fallen, als er erschossen wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[3368] = { id = 3368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suntara-Steine", description = "Bruder,\n\nwenn Du diesen Brief liest, bin ich nicht mehr. Wie er zu dir gelangt, weiß ich nicht, aber danke und belohne denjenigen, der ihn dir bringt.\n\nZu den Steinen: Es gibt sie wirklich und sie befinden sich im Besitz der Dunkeleisenzwerge. Ihr Anführer, Lathoric der Schwarze, benutzt die Kraft der Steine, um mein Ausgrabungsteam zu versklaven. Sie wurden zum Kessel gebracht. Ihre Gedanken wurden verdreht, sie arbeiten Tag und Nacht, um etwas, das Obsidion heißt, zu vollenden.\n\nHilf ihnen, Bruder. Das ist der letzte Wunsch eines toten Mannes.\n\n- Dorius", sourceObjective = "Bringt den angesengten Brief zu Thorius in Ironforge. Er befindet sich in der Halle der Forscher.", progress = "<Thorius schluchzt.>", completion = "<Thorius wischt sich sein Gesicht ab.>\n\nIm Namen des Lichts, sein Wunsch soll erfüllt werden. Das schwöre ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[3369] = { id = 3369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alptraum", description = "Dieser Splitter enthält große Geheimnisse; er ist die pure Essenz des Smaragdgrünen Traums. Was ich jedoch in diesem Splitter sehe, ist kein Traum, diese Art der Vision ist eher ein Alptraum.\n\nIch möchte Euch nicht beunruhigen, {name}, aber ich denke, es ist am besten, wenn Ihr diesen Splitter so schnell wie möglich in die Hände eines weisen Druiden gebt.\n\nIhr müsst Hamuul Runetotem auf der Anhöhe der Ältesten finden. Geht nach Thunder Bluff. Mehr vermag ich Euch nicht zu sagen.", sourceObjective = "Bringt den Alptraum-Splitter zu Hamuul Runtetotem auf der Anhöhe der Ältesten.", progress = "Kann ich Euch behilflich sein?", completion = "Falla hat Euch zu mir gesandt? Dann lasst mich mal jenen Splitter sehen, über den sie nur so ungern sprechen mochte, wie Ihr sagt...\n\n<Hamuul sieht in den Splitter>\n\nOh... Ich habe nicht... Nun ja.\n\n{name}, ich danke Euch, dass Ihr mir das hier gebracht habt. Lasst mich Euch jedoch sagen, dass es nicht sehr klug ist, von Dingen wie diesen zu sprechen. Das sind Dinge, mit denen Ihr Euch nicht beschäftigen solltet.\n\nSagen wir einfach mal, dass die Dinge im Smaragdgrünen Traum nicht so sind, wie wir es dachten...\n\nVielleicht werden wir uns einmal wiedersehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3370] = { id = 3370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alptraum", description = "Dieser Splitter trägt große Geheimnisse in sich; es ist die pure Essenz des Smaragdgrünen Traums. Was ich jedoch in diesem Splitter sehe ist kein Traum, diese Art der Vision ist eher ein Alptraum.\n\nIch möchte Euch nicht beunruhigen, {name}, aber ich denke, es ist am besten, wenn Ihr diesen Splitter in die Hände eines weisen Druiden gebt, sobald Ihr könnt ... \n\nIhr müsst Mathrengyl Bearwalker im Zirkel des Cenarius finden. Geht nach Darnassus. Mehr vermag ich Euch nicht zu sagen.", sourceObjective = "Bringt den Alptraum-Splitter zu Mathrengyl Bearwalker in Darnassus.", progress = "Kann ich Euch behilflich sein?", completion = "Falla hat Euch zu mir gesandt? Dann lasst mich mal jenen Splitter sehen, über den sie nur so ungern sprechen mochte, wie Ihr sagt...\n\n<Mathrengyl sieht in den Splitter>\n\nOh... Ich habe nicht... Nun ja.\n\n{name}, ich danke Euch, dass Ihr mir das hier gebracht habt. Lasst mich Euch jedoch sagen, dass es nicht sehr klug ist, von Dingen wie diesen zu sprechen. Das sind Dinge, denen sich die cenarischen Druiden allein stellen müssen.\n\nSagen wir einfach mal, dass die Dinge im Smaragdgrünen Traum nicht so sind, wie wir es dachten...\n\nVielleicht werden wir uns einmal wiedersehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3371] = { id = 3371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwergengerechtigkeit", description = "Wo mein Herz einst schlug, ist jetzt ein leeres Loch, {name}. Über den Verlust von Dorius werde ich so schnell nicht hinwegkommen. Ich muss seinen letzten Wunsch erfüllt sehen - diejenigen, die diesen kaltblütigen Mord durchführten, müssen der Gerechtigkeit zugeführt werden.\n\nKehrt zur sengenden Schlucht zurück und erfüllt seine letzte Bitte. Befreit seine Männer.", sourceObjective = "Kehrt zur sengenden Schlucht zurück und sucht Dorius' Archäologenteam.", completion = "Lasst mich, helft den anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3372] = { id = 3372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlöst sie", description = "Befreit sie, {race}. Selbst nachdem ihre Körper aufgegeben haben, zwingt die Macht der Suntara sie, ihre Aufgaben weiter zu erfüllen.\n\nDer Altar von Suntara ist der Schlüssel. Geht nach Norden, in die Hügel oberhalb der Höhle... Die Twilight-Hammer bewachen dort ein Relikt. Bringt es herbei und stellt es auf den Altar von Suntara.\n\n<Der sterbende Archäologe bricht zusammen.>", sourceObjective = "Sucht das mysteriöse Artefakt, das im Norden von den Twilight-Hammer bewacht wird.", progress = "Der Altar ist leer.", completion = "Ihr stellt das mysteriöse Artefakt auf den Altar von Suntara.", sourceObjectiveStatus = "unverified-source-field" }
quests[3373] = { id = 3373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz des Eranikus", description = "Als Ihr den Edelstein berührt, ertönt eine tiefe Stimme in Eurem Geist.\n\n\"Sterbliches Wesen, hört diese Bitte. Ich bin Eranikus vom grünen Drachenschwarm, der Hüter dieses verfluchten Tempels. Meine Aufgabe, sicherzustellen, dass die Trolle nie wieder ihre Monstrosität von einem Gott in diese Welt bringen, ist nun fehlgeschlagen. Während ich diesen Edelstein mit einem Teil meiner magischen Essenz fülle, fühle ich, wie mein Traum sich zum Chaos hinbewegt. Ich bitte Euch... legt diesen Edelstein in den Essenzborn in meinem Unterschlupf und lasst unsere Magie dort den Makel von meiner Psyche nehmen, sodass ich endlich ruhen kann.\"", sourceObjective = "Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet.", progress = "Während Ihr Euch dem Essenzborn nähert, von dem Eranikus Euch berichtet hat, ertönt seine Stimme erneut in Eurem Kopf.\n\n\"Ja, sterbliches Wesen, dieser Essenzborn wird den reinen Teil meiner Psyche, die sich noch innerhalb dieses Edelsteins befindet, erlösen. Legt den Edelstein in den Born hinein und lasst die Magie des grünen Drachenschwarms Verderbnis und Besudelung von meinem Wesen entfernen. Erst dann werde ich wahre Erlösung finden und erst dann wird der Drachenschwarm in der Lage sein, seine Führung über den Atal'ai wieder zu bestätigen.\"", completion = "Ihr legt den Edelstein in den Essenzborn hinein.\n\n\"Ich danke Euch, sterbliches Wesen, Ihr habt - nein... das, das darf nicht sein! Nein! Die Verderbnis dieses verfluchten Gottes hat sogar die Reinheit eines Essenzborns des grünen Drachenschwarms beschmutzt! Bitte, nein, ich fühle, wie meine Essenz von mir gerissen wird! DER SCHMERZ! Ich fühle, wie mich die Umklammerung eines ewigen Alptraums umschlingt...\"\n\n\"Sterbliches Wesen, ich flehe Euch an! Findet einen vom grünen Drachenschwarm, um dem ein Ende zu bereiten... helft mir... Ich bin in der Dunkelheit gebunden... auf ewig in Schmerzen... bitte nicht... foltern...\"", sourceObjectiveStatus = "unverified-source-field" }
quests[3374] = { id = 3374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz des Eranikus", description = "Ihr aktiviert den Schwurstein und Itharius spricht Euren Geist direkt durch den Stein an.\n\n\"Indem Ihr die Ladung dieses Schwursteins angenommen habt, erklärt Ihr Euch einverstanden, meiner Sache und der Sache von Yseras Drachenschwarm behilflich zu sein, und die verderbte Seele von Eranikus zu erlösen. Das erste Opfer, eines von vielen, die Ihr ohne Zweifel bringen müsst, ist, mir den Edelstein zu übergeben, der den Teil von Eranikus' Psyche gefesselt hat, der noch über einen freien Willen verfügt.\"\n\n\"Tut dies, {name}, und wir werden zusammen an der Erlösung einer Seele arbeiten, die es verdient hat, erlöst zu werden.\"", sourceObjective = "Bringt den Schwurstein von Yseras Drachenschwarm sowie die gekettete Essenz von Eranikus zu Itharius in die Sümpfe des Elends. Dort werdet Ihr Eure Entscheidung treffen, ob Ihr Yseras Drachenschwarm helfen wollt oder nicht.", progress = "Hier sind wir nun, {name}, wieder an einem Scheideweg. Es ist jetzt an der Zeit, eine weitere Entscheidung zu treffen. Welche Wahl werdet Ihr treffen?", completion = "Ihr habt Eure Wahl getroffen und so beginnt es. Bis jetzt waren Eure Entscheidungen, soweit es mich betrifft, die richtigen. Eure Taten und Aktionen werden nun bestimmen, ob dies weiterhin der Fall sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[3375] = { id = 3375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzphiole", description = "Ähm... Ihr braucht eine weitere Wahrsagephiole? Das soll wohl ein Witz sein! Was habt Ihr denn mit der Ersten angestellt?! Wir haben eine Menge Arbeit vor uns, {race}. Diese Phiolen wachsen nun mal nicht auf Bäumen! Eigentlich wünschte ich, es wäre so, dann könnte ich nämlich einfach eine pflücken gehen. Ich habe nämlich keine mehr!\n\nUm Euch eine zu machen, brauch ich Folgendes: Einen Manatrank, ein Stück Kohle und etwas süßen Nektar. Fragt mich ja nicht, warum, bringt mir einfach, was ich brauche, und ich werde Euch eine neue Phiole machen.", sourceObjective = "Bringt einen Manatrank, Kohle und Süßen Nektar zu Talvash del Kissel in Ironforge, um einen Ersatz für Talvashs Wahrsagephiole zu bekommen.", progress = "Um eine weitere Phiole herzustellen, brauche ich einen Manatrank, ein Stück Kohle und etwas süßen Nektar.\n\nUnd außerdem anscheinend noch jede Menge Geduld.", completion = "Der mächtige Abenteurer bringt die Sachen herbei. Wie schön für mich. Übrigens, ich hab gelogen... ich hatte noch eine Phiole. Hng, nehmt sie.\n\nNa, was habt Ihr denn erwartet? \"Oh, hier, nehmt die hier! Ich bin ja nur ein Idiot, der nichts Besseres zu tun hat, als magische Kommunikationsgeräte an Abenteurer zu verschleudern!\" Eins ist jedoch sicher, das, was Ihr mir gebracht habt, reicht aus, um Euch eine weitere Phiole zu machen, wenn Ihr diese hier auch verlieren solltet.\n\nEs wäre jedoch schön, wenn ich mich irren würde und Ihr die neue nicht verliert, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[3376] = { id = 3376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Spitzhauer!", description = "{name}... Ihr seid ein Neuling, ich habe von Euch gehört. Vielleicht könnt Ihr uns ja helfen, wo andere bereits versagt haben.\n\nWir Tauren haben in diesem Land unsere Heimstatt geschaffen, aber nicht, ohne teuer dafür zu bezahlen. Die Stacheleber des Borstennackenstamms aus der Dornrankenklamm, mit Häuptling Spitzhauer Dornenmantel als Anführer, machen uns mit ihrem ständigen Krieg das Leben schwer. Ich beauftrage Euch, mir den Kopf des Häuptlings zu bringen!\n\nIhr könnt ihn in der Klamm östlich von hier in dem heruntergekommenen Dorf finden.", sourceObjective = "Bringt den Kopf von Häuptling Spitzhauer Dornenmantel zu Kriegerheld Windfeather nach Red Cloud Mesa.", progress = "Spitzhauer wird uns nicht mehr belästigen, sobald Ihr mir den Beweis seines Todes liefert. Ich will seinen Kopf, {name}.\n\nWir {race} leben für die Jagd und es gibt keine größere Jagd als gegen einen, der schlau genug ist, uns vielleicht auch zu jagen. Wenn Ihr in dieser Aufgabe erfolgreich seid, werdet Ihr anfangen zu begreifen, was ich meine.", completion = "Der Gerechtigkeit wurde heute durch Eure schnellen Taten Genüge getan, {name}. Möge sein Tod allen als Warnung dienen, die unsere Heimat bedrohen.\n\nIhr habt diese Belohnung verdient, die Euch auf Euren Reisen helfen soll, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[3377] = { id = 3377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebet an Elune", description = "Werdet Ihr mir helfen, sterbliches Wesen? Hört meine Geschichte.", sourceObjective = "Hört Zamaels Geschichte.", progress = "Erlaubt mir, meine Geschichte zu beenden.", completion = "Ich habe mich mit meinem Schicksal hier in diesem Käfig abgefunden, aber das Gebet muss gefunden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[3378] = { id = 3378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebet an Elune", description = "Werdet Ihr mir helfen, sterbliches Wesen? Werdet Ihr das Gebet an Elune finden?\n\nWie ich bereits sagte, wurde das Gebet auf eine goldene Schrifttafel geätzt. Einer dieser Götzenanbeter muss sie bei sich tragen.\n\nWenn Ihr mein Gebet wiederfindet, bringt es zu Astarii Starseeker in Darnassus. Dass mein Glauben nach den zahllosen widerwärtigen Aktionen, die ich gegen diese Welt und seine Einwohner begangen habe, wiederbelebt wurde, ist vollkommen unwichtig, aber mein Gebet muss gehört werden. Absolution ist das Letzte, was ich erwarte.", sourceObjective = "Findet das Gebet an Elune und bringt es zu Astarii Starseeker in Darnassus.", progress = "Was führt Euch in den Tempel des Mondes, {name}?", completion = "Heute Abend lächelt Elune auf Euch herab, {name}. Ihr habt ihr eine verlorene Seele zurückgebracht. Bitte nehmt dies als ein Zeichen unserer Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[3379] = { id = 3379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenweber", description = "Die Spinnen der sengenden Schlucht sind eine unschätzbare Quelle für Schattenseide. Wie Ihr wisst, ist Schattenseide bei den Fachleuten unseres Gewerbes heiß begehrt.\n\nSeit kurzem hat sich eine Gruppe von Wilderern in diesem Land eingenistet, die achtlos massenhaft Spinnen töten, ohne darüber nachzudenken, welche Auswirkungen ihre Taten auf Dauer haben können. Die erste Aufgabe, die ich von Euch verlange, ist recht einfach: Findet sie... und macht ihnen ein Ende.\n\nBeginnt Eure Suche im Norden.\n\nWenn Ihr Hilfe benötigt, sprecht mit Schleifer.", sourceObjective = "Tötet die Gruppe der Schattenseidewilderer, die in der sengenden Schlucht umherstreifen. Nilith hat Grund zu der Annahme, dass es fünf von ihnen gibt, die ausgeschaltet werden müssen.", progress = "Welche Informationen bringt Ihr?", completion = "Ausgezeichnete Arbeit, {name}.\n\nIch bin sicher, dass Ihr ein solches Stück Schattenzwirn bis jetzt noch nicht gesehen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3380] = { id = 3380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der versunkene Tempel", description = "Es gibt rastlose Geister in dieser Welt, {name}. Es sind Geister, die durch ihre Einsamkeit besudelt wurden und an ein altes Übel gebunden sind...\n\nIch habe von einem Ort gehört, der tief unter der Erdoberfläche liegt... größere Mächte als ich jemals gesehen habe, haben ihn dorthin verbannt.\n\nWenn Ihr mehr über diesen Ort, den Versunkenen Tempel, erfahren wollt, sucht einen Goblin namens Marvon Rivetseeker auf. Er hat viele alte Gebiete der Welt erforscht. Zuletzt hieß es, dass er sein Heim in Ratchet verlassen habe, um die Trollruinen von Tanaris zu erforschen.", sourceObjective = "Sucht Marvon Rivetseeker in Tanaris.", completion = "Ja, der Versunkene Tempel, ich darf behaupten, dass ich ihn mit meinen eigenen Augen gesehen habe. Vielleicht möchtet Ihr etwas mehr darüber erfahren?\n\nIhr scheint mir von der abenteuerlustigen Sorte zu sein - und ich weiß von Dingen, die Euch interessieren könnten ...", sourceObjectiveStatus = "unverified-source-field" }
quests[3381] = { id = 3381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit dem Meister", description = "Ah, ein {race}, noch dazu jung, der mit Sanath sprechen möchte. Was für ein wundervoller Tag! Ich fühle mich so geehrt, dass Ihr mich mit Eurer Anwesenheit beehrt. Danke!\n\nBitte... seid nicht so arrogant anzunehmen, dass mein Sarkasmus ein Kompliment war. Lasst uns eine Sache klarstellen: Ich mag Euch nicht. Aber diese kleine Unterhaltung hat nichts mit uns zu tun... es geht um meinen Meister.\n\nBringt mir ein Paar Hippogryphenfedern für meine Pfeile und ich werde Euch zu ihm führen. Er bat darum, dass ich ihm Abenteurer schicke, sofern sie sich würdig erweisen.", sourceObjective = "Bringt 2 unbeschädigte Hippogryphenfedern zu Sanath Lim-yo in Azshara, wenn Ihr mit seinem Meister sprechen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3382] = { id = 3382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Mannschaft in Bedrängnis", description = "Wir waren kurz vor der Küste und suchten nach einem sicheren Hafen, um vor Anker zu gehen. Die Sonne war noch keine Stunde untergegangen, als sie angriffen... diese verdammten Naga!\n\nIch weiß nicht genau, wonach sie gesucht haben, aber sie haben es offensichtlich nicht gefunden - sie sind bereits schon einmal wiedergekommen. Einige meiner Späher stehen am Eingang zum Tal Wache, um uns zu warnen, wenn der nächste Angriff kommt.\n\nEs tut mir Leid, dass Ihr gerade jetzt vorbeikommt, {name}, aber das liegt nicht in meiner Macht.\n\nSeid Ihr bereit für den Kampf Eures Lebens?", sourceObjective = "Verteidigt Kapitän Vanessa Beltis, ihre Mannschaft und die Passagiere der HERRIN DES HORIZONTS gegen den Angriff der Naga. Captain Vanessa Beltis muss überleben.", completion = "Ihr habt es geschafft! Danke! Das war mit Sicherheit eine der brutalsten Schlachten, an denen ich jemals teilgenommen habe. Ich kann Euch gar nicht genug danken.\n\nIch wünschte nur, ein größerer Teil meiner Mannschaft hätte diese Prüfung überlebt.\n\nIch möchte Euch bitten, mit den überlebenden Passagieren der HERRIN DES HORIZONTS zu sprechen. Einige von ihnen hatten hier geschäftlich zu tun und haben vielleicht ein oder zwei Aufträge für Euch, wenn Ihr wollt. Nochmals danke für all Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[3385] = { id = 3385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untermarkt", description = "Sie bezeichnen sich selbst als den Untermarkt: Halsabschneider von Händlern, die verkaufen, verschieben, handeln und zu fast allem bereit sind, vorausgesetzt, der Preis stimmt.\n\nEs kommt noch schlimmer, {name}. Sie haben einen Stützpunkt für ihre Operationen hier in der sengenden Schlucht errichtet. Handelsmeister Kovic führt diese Operationen an und hat enge Verbindungen zu den Dunkeleisenzwergen des Gebietes.\n\nWir müssen hart zuschlagen und den Anführern ein Zeichen setzen. Erschlagt Handelsmeister Kovic und seinen Diener Clunk. Bringt seinen Händlerranzen zurück, sobald die Tat ausgeführt ist.\n\nZum Kessel!", sourceObjective = "Erschlagt Handelsmeister Kovic und seinen Diener Clunk. Nehmt den Händlerranzen von seinem Leichnam und bringt ihn zu Nilith.", progress = "Der Handelsmeister lebt noch?", completion = "Ihr habt einen entscheidenden Schlag gegen den Untermarkt geführt. Seine Anführer werden es sich gut überlegen, bevor sie weitere Übeltäter in die Schlucht schicken.\n\nAch, ich habe auch nichts Nützliches im Händlerranzen finden können. Ihr könnt behalten, was immer Ihr im Innern findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[3402] = { id = 3402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untermarkt", description = "Ich will, dass Ihr Vizzklick in Gadgetzan persönlich die Nachricht von Kovics Niederlage überbringt. Ich bin ziemlich sicher, Kovics Tod wird ihn so erfreuen, dass er Euch eine großartige Belohnung geben wird.", sourceObjective = "Sprecht mit Vizzklick in Gadgetzan.", completion = "Kovic ist tot??! Was für ein glorreicher Tag, {name}! Seit Jahren hat dieser Halunke undurchsichtige Untermarktgeschäfte getätigt und so ehrliche und hart arbeitende Händler in der ganzen Welt unterboten und betrogen.\n\nFür diese Leistung verdient Ihr eine feine Belohnung! Und Ihr werdet eine feine Belohnung erhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[3421] = { id = 3421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückreise", sourceObjective = "Ich werde Euch jetzt zu Sanaths Lager zurückbringen.\n\nMacht Euch nichts aus seinen schlechten Manieren - er ist zu allen unhöflich, außer zum Meister. Vielleicht wird er seine Lektion eines Tages lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3441] = { id = 3441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Göttliche Vergeltung", description = "Hört meine Geschichte, Abenteurer.", sourceObjective = "Lasst Velarok Windblade seine Geschichte erzählen.", progress = "Lasst mich beenden, w... {race}.", completion = "Habt Ihr genug gehört? Seid Ihr bereit zu handeln?", sourceObjectiveStatus = "unverified-source-field" }
quests[3442] = { id = 3442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fehlerlose Flamme", description = "Ihr habt die richtige Entscheidung getroffen, {name}.\n\nWir müssen dort zuschlagen, wo wir den größten Schaden anrichten: an den vier Wachpostentürmen.\n\nWenn die vier Wachpostentürme in Flammen stehen, starten wir eine Offensive, bevor sie reagieren können.\n\nIhr benötigt das passende Werkzeug, um die Türme in Brand zu setzen. Für die Herstellung des Werkzeugs wird einiges an Materialien benötigt.\n\nBringt mir vier Herzen der Flamme und vier Kugeln Golemöl, und ich werde die Fackel der fehlerlosen Flamme herstellen können.\n\nIhr solltet Euch also zuerst die Golems und Elementare dieses Landes vornehmen.", sourceObjective = "Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Velarok Windblade.", progress = "Habt Ihr die Materialien gesammelt?", completion = "Gut gemacht, {name}. Wir sind fast so weit.", sourceObjectiveStatus = "unverified-source-field" }
quests[3443] = { id = 3443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schmieden des Schafts", description = "Um die fehlerlose Flamme halten zu können, brauchen wir noch einen Schaft und eine Ummantelung. Ihr müsst zunächst einen geeigneten Schaft finden.\n\nDie Zuchtmeister und Sklavenhändler der Dunkeleisenzwerge des Kessels benutzen Waffen aus verzaubertem Thorium, eine besonders stabile Legierung. Wenn Ihr mir acht mit Thorium beschichtete Dolche bringen könnt, kann ich die Legierung aufbrechen und einen Schaft schmieden.", sourceObjective = "Bringt 8 mit Thorium beschichtete Dolche zu Velarok Windblade.", progress = "Acht, {name}. Ich brauche acht!", completion = "Ihr seid ein außergewöhnlicher Arbeiter, {name}. Habt Ihr jemals darüber nachgedacht, einer anderen Berufung zu folgen? Vielleicht der eines Detektivs? Plundersammlers? Oh, ich weiß, Ihr könntet einer dieser dummen Gnome werden, die über die Strände von Azeroth schleichen und mit ihren Metalldetektor-Apparaten nach verlorenen Schätzen suchen. Ja, das wäre ein idealer Beruf für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[3444] = { id = 3444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der runde Stein", description = "Ich habe einst die furchteinflößenden Kammern des Versunkenen Tempels betreten. Das Böse an jenem Ort durchdringt alle, die eintreten. Mit Mühe und Not habe ich es geschafft, irgendwie meinen Weg wieder nach draußen zu finden, indem ich durch den Brühschlamm watete, der jetzt den Boden bedeckt. Ich kann mich nur daran erinnern, dass ich durch einen großen, kreisrunden Raum gestolpert bin, der angefüllt war mit Schlangenstatuen ...\n\nKürzlich habe ich einen runden Stein entdeckt, der anscheinend das gleiche Schlangensymbol trägt. Ich habe ihn verpackt und in meine Werkstatt nach Ratchet geschickt. Bringt ihn her und ich kann Euch vielleicht mehr erzählen.", sourceObjective = "Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet.", progress = "Ratchet ist nicht weit von hier, {name}. Die Reise dürfte nicht lange dauern.", completion = "Ja... Das ist der Stein.\n\nIch erinnere mich jetzt an alles, {name}...", sourceObjectiveStatus = "unverified-source-field" }
quests[3445] = { id = 3445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der versunkene Tempel", description = "Ich habe von einem Ort gehört, der tief unter der Oberfläche der Erde liegt - dorthin verbannt durch größere Mächte, als ich jemals gesehen habe.\n\nWenn Ihr mehr über diesen Ort, den Versunkenen Tempel, erfahren wollt sucht einen Goblin namens Marvon Rivetseeker auf. Genau wie Troyas und ich hat er viele alte Gebiete der Welt erforscht. Zuletzt hieß es, dass er seine Heimstatt in Ratchet verlassen habe, um die Trollruinen von Tanaris zu erforschen.\n\nViel Glück bei Eurer Suche, man hat schon seit längerem nichts mehr von ihm gehört.", sourceObjective = "Sucht Marvon Rivetseeker in Tanaris.", completion = "Ja, der Versunkene Tempel, ich darf behaupten, dass ich ihn mit meinen eigenen Augen gesehen habe. Vielleicht möchtet Ihr etwas mehr darüber erfahren?\n\nIhr scheint mir von der abenteuerlustigen Sorte zu sein - und ich weiß von Dingen, die Euch interessieren könnten ...", sourceObjectiveStatus = "unverified-source-field" }
quests[3446] = { id = 3446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Tiefen", description = "Im Tempel fand ich einen kreisrunden Raum mit sechs Altaren, und am Rand eines jeden stand eine Schlangenstatue. Neugierig drückte ich gegen eine von ihnen, um zu sehen, was passieren würde. Es war eine Falle! Durch die Explosion wurde ich fast getötet. Als ich da auf einem Vorsprung lag, sah ich nach unten und bemerkte, dass eine weitere Statue unten im Raum stand; es war ein Altar der Art ... Hakkar, ich glaube, so wurde er genannt.\n\nIch denke, dass dieser Altar das Geheimnis ist ... Ihr müsst dieses Zeichen zum Altar in den Versunkenen Tempel bringen.", sourceObjective = "Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends.", progress = "Während Ihr die Statue untersucht, bemerkt Ihr eine Vertiefung an ihrer Seite, die genau die Größe des Zeichens hat, das Marvon Euch mitgab...", completion = "Ihr legt den runden Stein in die Öffnung hinein und hört, wie er an seinem Platz einrastet.\n\nNun, da der Stein an seinem Platz ist, könnt Ihr weitermachen... aber was solltet Ihr als Nächstes tun?\n\nVielleicht solltet Ihr diesen Altar etwas näher untersuchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[3447] = { id = 3447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des Kreises", description = "Meine Erinnerungen sind verworren, aber ich werde Euch alles sagen, was ich weiß. Der Kreis der Statuen im Versunkenen Tempel mag ja gefährlich sein, ich glaube dennoch, dass sie das Geheimnis eines noch größeren Schatzes in sich bergen.\n\nVom Hauptaltar aus konnte ich eine Reihe von Lichtern aktivieren. Ich glaube, dass Ihr, wenn Ihr die Bedeutung dieser Lichter herausfindet, auch die weiteren Geheimnisse lüften könnt, die sich in diesem Raum verstecken.\n\nAber ich warne Euch, {name}. In dem Tempel ist etwas unermesslich Böses. Es ist anzunehmen, dass alles Wertvolle äußerst streng bewacht wird.", sourceObjective = "Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt.", completion = "Sogar in dem Halbdunkel des Tempels glitzert das Auge des Götzenbildes hell. Seine Transparenz enthüllt etwas Glänzendes, das dahinter versteckt ist. Ihr schiebt es zur Seite, fasst hinein und ergreift das, was im Inneren der Statue liegt.\n\nDer Schatz der Atal'ai gehört nun Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[3448] = { id = 3448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bürde weitergeben", description = "Kürzlich erhielt ich den Auftrag, Azshara zu untersuchen, einen einst wunderschönen Landstrich, den die Elfen ihr Zuhause nannten. Das war damals, als sie noch Magie praktizierten. Jetzt ist es dort eher gefährlich als schön, aber das hält uns nicht davon ab, jeden Stein umzudrehen, um Hinweise auf unsere Vergangenheit zu erhalten.\n\nEin Gefährte von mir namens Tymor bot mir seine Hilfe bei der Untersuchung dieses Gebietes an, da er ein besonderes Interesse an solchen Dingen hat.\n\nEr besitzt ein kleines Anwesen rechts neben der Halle der Mysterien hier in der Stadt.", sourceObjective = "Sprecht mit Magier Tymor in Ironforge.", completion = "Ah, Karnik hat Euch also geschickt? Ich habe darauf gewartet, bald von ihm zu hören. Ich habe solch wundersame Dinge über Azshara erfahren... Ich weiß zwar, dass Nachtelfen eine unglaubliche Lebensspanne haben, aber jeder vergisst doch einige der... unglücklicheren Geschehnisse in seinem Leben. Das ist jetzt nicht als Kritik zu verstehen, es ist nur eine Beobachtung.\n\nVor langer Zeit schufen die Elfen Städte, die erfüllt waren mit Wissen über Magie und andere verlorene Künste. Da ich nun solche Dinge selbst studiere, habe ich meine eigenen Nachforschungen angestellt. Was ich herausfand, war äußerst fesselnd.", sourceObjectiveStatus = "unverified-source-field" }
quests[3449] = { id = 3449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Runen", description = "Einstmals wurde Magie von einigen Elfen genauso verehrt wie Elune selbst. Einige ihrer mächtigsten Magier erstellten Runen und Schrifttafeln, die die Regeln des Arkanen zitierten und Einsichten in ihre Funde gaben. Sie ließen sie an öffentlichen Plätzen aufstellen, damit jeder darüber nachdenken konnte.\n\nIch hätte sehr gern Abpausbilder dieser Runen aus den Ruinen von Eldarath. Ich habe ein Set für Euch, mit dem Ihr Abpausbilder herstellen könnt, aber Ihr müsst sie selbst finden. Seid aber vorsichtig, die Forscherliga ist nicht die Einzige, die sich dafür interessiert.", sourceObjective = "Verwendet das Zeichenset, um Abpausbilder von der Rune von Beth'Amara, der Rune von Jin'yael, der Rune von Markri und der Rune von Sael'hai herzustellen, bevor Ihr Euch zu der kleinen Insel vor der südlichen Halbinsel von Azshara aufmacht und dem Piloten Xiggs Fuselighter signalisiert, dass er sie abholen kann.", progress = "Ach nein, wie schön zu sehen, dass Ihr es hierher geschafft habt, {name}. Konntet Ihr die Abpausbilder für Tymor machen?\n\nAuch wenn es hier ganz schön gefährlich ist, entlang der Küste war nicht viel los. Das kann natürlich an den Naga liegen, die da unter Wasser herumschwimmen, aber das ist nicht mein Problem ... Ich patrouilliere den Himmel.", completion = "Schön, dass Ihr wohlauf und gesund seid, {name}. Ich hoffe, es war nicht zu anstrengend für Euch.\n\nIch werde das sofort zu Tymor bringen. Er wird so aufgeregt sein, endlich einen Blick darauf werfen zu können.\n\nLos, werft die Leuchtfeuerwaffe weg... wird Euch wahrscheinlich eh nicht mehr viel nützen, und ich hab auch schon eine neue.", sourceObjectiveStatus = "unverified-source-field" }
quests[3450] = { id = 3450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine einfache Ladung", description = "Ich will diese Abpausbilder sofort in meinen Turm geliefert haben, aber Ihr müsst nicht den ganzen Weg selbst gehen. Ich werde sie einfach per Luftfracht aus Azshara bringen lassen.\n\nXiggs Fuselighter schuldet mir noch einen oder zwei Gefallen und wird sich bald in der Nähe aufhalten - er wurde zur Küstenpatrouille abkommandiert. Sprecht mit ihm, bevor Ihr weggeht. Er kann Euch eine Leuchtfeuerwaffe geben, damit Ihr ihm signalisieren könnt. Sobald Ihr die Abpausbilder zusammen habt, begebt Euch an den Ort, den er Euch nennt und übergebt sie ihm dann, damit er sie sicher zu meinem Turm bringen kann. Er sollte sich im Hangar im Militärviertel aufhalten.", sourceObjective = "Sprecht mit Xiggs Fuselighter in Ironforge.", completion = "Was kann ich für Euch tun, {name}? Bin ein wenig beschäftigt im Moment, bereite mein Schiff für eine lange Reise vor. Kam gerade nur vorbei, um mit einigen Panzerpiloten zu sprechen - ich brauche einige Wendigomähnen um mein Cockpit auszupolstern, und meist haben sie welche übrig.\n\nIhr habt eine Minute, wenn Ihr Euch kurz fasst... einer der Jungs ist gerade zu Steelgrills Depot, um nachzusehen, ob die Piloten dort Mähnen für mich übrig haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[3451] = { id = 3451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal zum Abholen", description = "Ah, Tymor hat Euch also geschickt, hm? Ja, dem schulde ich noch einen oder zwei Gefallen. Wie war das? Nein, der kleine Teufel. Ja, da kann ich ihm helfen. Ihr braucht also eine Leuchtfeuerwaffe und einen Ort... nichts leichter als das.\n\nKurz vor der südlichen Halbinsel von Azshara liegt eine kleine Insel, auf der wir eine Landungsplattform gebaut haben. Ihr nehmt diese Leuchtfeuerwaffe und schießt sie dort ab. Ich sehe dann Euer Signal und werde vorbeikommen, um diese... was auch immer er da haben will, mitzunehmen.", sourceObjective = "Sprecht mit Xiggs Fuselighter in Ironforge und erhaltet von ihm eine Standardausrüstung-Leuchtfeuerwaffe.", completion = "Hier ist meine Standardausrüstung-Leuchtfeuerwaffe, und habt nach dem Abfeuern der Waffe etwas Geduld - diese Sorte hat nur zwei Aufladungen und ich werde wahrscheinlich etwas Zeit brauchen, um bei Euch zu landen, je nachdem, wie weit draußen ich auf See bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[3452] = { id = 3452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ummantelung der Flamme", description = "Wir brauchen noch ein letztes Teil, um die Fackel zu formen.\n\nIn den Bergen nordwestlich von hier könnt Ihr ein großes Lager der Twilight-Hammer finden. Es heißt, dass sie Symbole und Götzenbilder zur Verehrung ihres Gottes mit sich herumtragen. Diese Symbole und Götzenbilder besitzen vielleicht genügend Verzauberung, um daraus eine magische Ummantelung herzustellen. Bringt mir ein einziges Symbol von Ragnaros und ich werde versuchen, die Magie aus dem Gegenstand zu extrahieren, um die Ummantelung zu erschaffen.", sourceObjective = "Bringt ein Symbol von Ragnaros zu Velarok Windblade.", progress = "Ohne die geeignete Quelle arkaner Energie kann die Fackel der Vergeltung nicht vollendet werden.", completion = "Das Symbol strahlt elende Magie aus; wunderbar geeignet für unsere Zwecke.", sourceObjectiveStatus = "unverified-source-field" }
quests[3453] = { id = 3453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fackel der Vergeltung", description = "Gebt mir einen Augenblick, um die Teile zusammenzufügen und die notwendigen Verzauberungen anzuwenden.", sourceObjective = "Wartet bis Velarok Windblade die Fackel der Vergeltung vollendet hat.", completion = "Ihr müsst noch eine allerletzte Aufgabe erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3454] = { id = 3454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fackel der Vergeltung", description = "Die Fackel muss jetzt an ihren Besitzer gebunden werden. Nehmt die Fackel auf, {name}.", sourceObjective = "Nehmt die Fackel der Vergeltung.", completion = "Ihr greift die Fackel mit beiden Händen, und Wellen von Hass und Wut pulsieren durch Euer ganzes Wesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3461] = { id = 3461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Magier Tymor", description = "Tymor hat mir nichts gegeben, um Euch zu bezahlen, also schlage ich vor, dass Ihr das mit ihm besprecht, wenn Ihr zurück in Ironforge seid. Ich bin mir sicher, er wird dann immer noch an seiner Wohnung im Mystikerviertel sein. Klopft einfach bei ihm an, und er soll Euch ja gut bezahlen. Das hier ist nicht gerade ein Spaziergang... das ist schon mal sicher.\n\nDanke nochmals für Eure Hilfe und viel Glück.\n\nOh, das Zeichenset brauche ich nicht. Warum bringt Ihr es nicht selbst Tymor zurück, wenn Ihr ihn besucht?", sourceObjective = "Bringt Magier TymorsZeichenset zu ihm zurück nach Ironforge.", progress = "Ihr seid zurück! Exzellent. Habt Ihr auch mein Zeichenset dabei?", completion = "Großartig! Es freut mich, das zu hören.\n\nIch kann es kaum erwarten, in meinen Turm zu kommen und die ganzen Abpausbilder zu betrachten. Ich beneide Euch sehr... an einen Ort wie Azshara zu reisen. Das ist der Traum eines jeden Arkanen-Schülers, nehme ich an.\n\nNun, wir haben nie über irgendeine Belohnung gesprochen, da Ihr ja gerade für die Forscherliga gearbeitet habt, aber Ihr verdient etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[3462] = { id = 3462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knappe Maltrake", description = "Sprecht mit meinem Gesandten, dem Knappen Maltrake. Er wird Euch weiter unterweisen, wie die Fackel der Vergeltung zu benutzen ist.", sourceObjective = "Sprecht mit dem Knappen Maltrake.", completion = "Seid Ihr bereit, Euren Schlag auszuführen?", sourceObjectiveStatus = "unverified-source-field" }
quests[3463] = { id = 3463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt sie in Brand!", description = "Hört gut zu, {name}. Obgleich die vier Türme niemals zerstört werden können, könnt Ihr dennoch die Fackel der Vergeltung benutzen, um sie für lange Zeit in Brand zu setzen. Ein Feuer, das kein Element und keine Macht löschen kann.\n\nWährend sie in Flammen stehen, kann keine Wache oder Wachposteneinheit die Posten besetzen, und so ist ihre erste Verteidigungslinie außer Kraft gesetzt.\n\nIhr müsst in jeden Turm eindringen und die Fackel der Vergeltung innerhalb ihrer Befestigung verwenden. Nehmt Euch in Acht vor den Elitewachposteneinheiten der Dunkeleisenzwerge, {name}.", sourceObjective = "Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt.", progress = "Habt Ihr Euch verlaufen, {name}?", completion = "Es ist glorreich! Ist es nicht glorreich, Meister?", sourceObjectiveStatus = "unverified-source-field" }
quests[3481] = { id = 3481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunder...", description = "Die Truhe scheint verschlossen zu sein.", sourceObjective = "Öffnet die Truhe.", completion = "Bei Eurer Berührung öffnet sich die Truhe. Wie viel Käse kann hier wohl drin sein? Es gibt nur einen Weg, das herauszufinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[3483] = { id = 3483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal zum Abholen", sourceObjective = "Ah, noch eine Leuchtfeuerwaffe, hm? Die kann ich Euch geben.\n\nUnd vergesst nicht, Südspitze von Azshara. Es ist eine kleine Insel, die in eine Landungsplattform verwandelt wurde. Ihr könnt sie gar nicht verfehlen, wenn Ihr an der richtigen Stelle sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[3501] = { id = 3501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dutzend besser", description = "Obgleich Ihr wohl niemals eine fehlerlose Draenethystsphäre finden werdet, könnt Ihr zweifelsohne auf Euren Reisen durch dieses Land einige unvollständige Draenethystfragmente entdecken.\n\nEs ist zwar unwahrscheinlich, dass Kum'isha die fehlerhaften Fragmente benutzen kann, um nach Hause zurückzukehren, dennoch können diese Stücke für andere nützliche Zwecke der Draenei dienen.\n\nBringt mir alle fehlerhaften Draenethystfragmente, die Ihr finden könnt, und ich werde Euch belohnen.", sourceObjective = "Bringt Kum'isha unvollständige Draenethystfragmente und Ihr werdet für jedes, das Ihr bringt, belohnt.", progress = "Hattet Ihr Glück bei Euren Forschungen?", completion = "Ihr widert mich an, {race}. Ein erwachsener Mann, sabbernd über einem Haufen Plunder? Jämmerlich! Nehmt Eure Belohnung und geht mir aus den Augen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3502] = { id = 3502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Draeneis Plunder...", description = "Nach einer solchen Zurschaustellung von ekelhafter Gier ist mir richtig übel.\n\nWie dem auch sei, ich werde mich nicht allzu lange mit Eurer materiellen Abhängigkeit beschäftigen.\n\nFür jedes unvollständige Draenethystfragment, das Ihr mir bringt, werde ich Euch mit weiterem Plunder belohnen. Mein Haufen Plunder wird kleiner werden, und der Eurige dafür anwachsen. Auf Draeneor nennen wir das eine Situation, bei der alle nur gewinnen können.", sourceObjective = "Bringt Kum'isha unvollständige Draenethystfragmente. Jede Art von Monster in den verwüsteten Landen könnte ein Fragment bei sich tragen.", progress = "Also? Draenethyst? Erinnert Ihr Euch?\n\n<Kum'isha ballt seine Faust und klopft an Euren Kopf.>\n\nJemand zu Hause?", completion = "Ihr widert mich an, {race}. Ein erwachsener Mann, sabbernd über einem Haufen Plunder? Jämmerlich! Nehmt Eure Belohnung und geht mir aus den Augen.\n\nKommt Euch das bekannt vor? Das sollte es, denn ich sage das ungefähr tausend Mal am Tag.\n\nOh, wie ich diese Welt verabscheue.", sourceObjectiveStatus = "unverified-source-field" }
quests[3503] = { id = 3503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen mit dem Meister", sourceObjective = "Es gab Zeiten, in denen ich alles von denen, die meinen Meister aufsuchen wollten, verlangen konnte. Heute ist es anders, Ihr müsst nur nach ihm fragen und ich schicke Euch zu ihm.\n\nEs ist ärgerlich für mich, aber ich stelle seine Befehle nicht in Frage. Ich kann mich lediglich an Eurer lächerlichen Aufmachung oder Eurem jämmerlichen Gesichtsausdruck erfreuen. Selbst das langweilt mich...\n\nSogar dieses Geschwafel langweilt mich! Möchtet Ihr meinen Meister sehen oder nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[3504] = { id = 3504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verraten", description = "Verräterische, diebische Elfin! So nenne ich sie... und genau das wird sie immer sein!\n\nIch habe wahrscheinlich einen großen Fehler gemacht, {name}. Ich habe einem Blutelfen vertraut.\n\nSie behauptete, in Azshara lägen große Reichtümer... mächtige Gegenstände. Ich sollte ihr nur ein paar Krieger zu ihrem Schutz schicken und dafür würde ich belohnt. Und wer ist jetzt wohl der Dumme - sie hat sie alle umgebracht.\n\nIch will Rache, {name}, aber ich kann es mir nicht leisten, noch jemanden zu schicken. Sucht Ag'tor bei Valormok auf, nördlich des Lagers der Haldarr. Er kann Euch mehr berichten.", sourceObjective = "Bringt den versiegelten Brief zu Ag'tor Bloodfist nach Azshara.", progress = "Ah, Belgrom ist schließlich zur Vernunft gekommen und hat jemanden geschickt, der nicht zu seinesgleichen gehört, um uns zu helfen, wie?\n\nDieses Lager wurde einmal von einem Dutzend Krieger bewohnt, {name}, aber jetzt sind sie alle tot. Diese Magierin, Rimtori, hat sie alle getötet. Sie hat mit Belgrom gespielt wie mit einer Puppe... hat ihn sogar verführt. Es geht mich zwar nichts an, aber ganz unter uns, sie ist eine ziemliche Verführerin. Das ist wahrscheinlich der Grund, warum ich immer noch hier bin und Belgrom helfe, ich hätte nämlich bestimmt genauso gehandelt.", completion = "Wir haben alles, was wir hatten, gegen sie und ihre Tagelöhner geschickt, aber sie sind sehr stark im Kampf. Keiner ist zurückgekehrt. Ich nehme zwar an, dass einige gestorben sind, aber ich bin sicher, dass andere einfach wegliefen... diese Feiglinge.\n\nAber da nun Verstärkung eingetroffen ist, können wir vielleicht doch noch was ausrichten. Vielleicht können wir sie für ihre Lügen und den Verrat an Belgrom bestrafen.\n\nWas sagt Ihr dazu, seid Ihr dabei?", sourceObjectiveStatus = "unverified-source-field" }
quests[3505] = { id = 3505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verraten", description = "Das hatte ich mir gedacht.\n\nWir werden unseren Kreuzzug gegen ihre Tagelöhner entlang der westlichen Steilhänge an der nördlichen Halbinsel von Azshara beginnen. Tötet sie mit blutiger Wut - lasst sie wissen, dass sie die falschen Verbündeten verraten haben.\n\nUm sie selbst müsst Ihr Euch jetzt noch nicht kümmern - sie verbringt die meiste Zeit zusammen mit ihren Leibwachen auf der Suche nach Azshara. Es ist wahrscheinlich am klügsten, erst ihre Tagelöhner zu erschlagen und dann ihr persönliches Lager zu suchen. Es wäre weise auszukundschaften, wo wir sie angreifen können. Vielleicht gibt es ja etwas, womit wir sie provozieren können.", sourceObjective = "Tötet 10 Blutelf-Wiederbeschaffer und 10 Blutelf-Feldmesser, bevor Ihr Magus Rimtoris Lager sucht. Sobald Ihr es gefunden habt, sucht nach etwas, das für sie von Bedeutung ist und das wir nehmen können, um sie in einen Kampf zu locken.", progress = "Der Titel des Buches ist mit Goldbuchstaben in den schwarzen Ledereinband eingeprägt... Kaldorei-Foliant der Beschwörung. Während Ihr die Seiten aufschlagt, erkennt Ihr, dass das Buch zwar sehr alt, aber in einem sehr gut erhaltenen Zustand ist.\n\nIhr geht davon aus, dass der Text in einer uralten Sprache geschrieben wurde... vielleicht Kaldorei?\n\nEuer Instinkt sagt Euch, dass Ihr hierher zurückkehren solltet, sobald Ihr bei den Blutelfen Vergeltung für ihren Verrat geübt habt.", completion = "Ihr blättert einige Seiten durch, bis Ihr an eine Seite kommt, die mit einem dünnen, schwarzen Seidenstreifen markiert wurde.\n\nWährend Ihr versucht, das Manuskript zu entziffern, entdeckt Ihr ein Diagramm unten auf einer der Seiten. Ihr seht Euch kurz um und bemerkt, dass die Kristalle, der Kreis und auch andere Komponenten auf dem Boden ein Muster ergeben, dass dem des Diagramms im Buch sehr ähnlich ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[3506] = { id = 3506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verraten", description = "Nach einigen Momenten des Nachdenkens kommt Ihr auf ein paar Ideen, eine davon bringt Euch zum Lächeln: Vielleicht würde die Zerstörung der Kristalle die Blutelfin ärgern, die für das Abschlachten so vieler Orcs und den Verrat an Belgrom verantwortlich ist?\n\nIhr fahrt fort, mehr vom Manuskript und den Bildern zu entschlüsseln und erkennt, dass einer der Kristalle an den Schöpfer des Kreises gebunden ist - die anderen sind an etwas weitaus Finstereres gebunden.\n\nIhr schließt das Buch und beginnt Euch zu entscheiden, welchen Kristall Ihr zerstören wollt.", sourceObjective = "Zerstört den arkanen Fokussierkristall, der an Magus Rimtori gebunden ist, und tötet sie danach. Bringt dann den Kopf von Magus Rimtori zu Ag'tor Bloodfist nach Azshara.", progress = "Wie geht Euer Beseitigen der Blutelfen-Verräter voran, {name}? Konntet Ihr Fortschritte machen?\n\nIch hoffe, dass Ihr stark genug seid, diese Hündin in die Knie zu zwingen! Sie verdient für das, was sie getan hat, nur eines: einen schmerzhaften Tod!", completion = "RAR!! Unglaublich!\n\nIhr habt es geschafft! Das wird Belgrom erfreuen! Nun endlich können die Geister von Dutzenden unserer Krieger ihren Frieden finden. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[3507] = { id = 3507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verraten", description = "Kehrt zu Belgrom nach Orgrimmar zurück. Er wird ihren Kopf höchstpersönlich sehen wollen. Wir werden in Kürze dorthin zurückkehren.\n\nAh, dies ist heute wahrlich ein Freudentag. Danke für Eure Hilfe, {name}.", sourceObjective = "Sprecht mit Belgrom Rockmaul in Orgrimmar.", progress = "Ich erinnere mich an Euch, {class}. Ich habe Euch gebeten, nach Azshara zu gehen und dieses Weib zu erledigen, das mich verraten hat! Das scheint so viele Monde her zu sein. Sagt mir nicht, dass Ag'tor und die anderen auch tot sind!", completion = "HAHA! Sieh dich an, lächerliches Weib! Ich spucke auf deine Überreste!\n\nDanke, {name}. Ich danke Euch aus tiefstem Herzen! Das ist wirklich ein großer Tag!\n\nWenn es in meiner Macht stünde, würde ich Euch ein Königreich geben! Aber ich hoffe, Ihr seid auch hiermit zufrieden.\n\n\n\nHa-ha! Blöde Blutelfin, schau dich nur mal an... in einem Sackleinenbeutel und ohne Körper! Du hättest Belgrom nicht verraten sollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[3508] = { id = 3508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Zauberschutz brechen", description = "Ihr seid tollkühn, {name}. Es ist eine bewundernswerte Eigenschaft Eurer Art, sich blind in die Schlacht zu stürzen, auch wenn nur wenig oder gar keine Aussicht auf Erfolg besteht. Ich werde Euch behilflich sein, sei es auch nur, um einen einzigen von Razelikhs Dienern fallen zu sehen.\n\nDen Zauberschutz, der auf Razelikhs Untergebenen liegt, zu brechen, kostet Zeit und macht es nötig, rare Artefakte zu erwerben.\n\nSeid still, ich muss erst das Erleuchtungsritual durchführen. Die Information, die ich dabei erhalte, wird mir helfen, Waffen von großer Macht zu schmieden.", sourceObjective = "Wartet, bis Loramus den Erleuchtungszauber vollendet hat.", completion = "Der Name der Bestie muss erst gefunden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[3509] = { id = 3509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Name der Bestie", description = "Es gibt nur eine Möglichkeit, den Dämonenlord und seine Diener zu verletzen. Eine Waffe der Macht muss geschmiedet werden, die seinen wahren Namen trägt.\n\nWird eine solche Waffe geschmiedet, sind der Dämon und alle, die unter seinem Kommando stehen, verwundbar.\n\nIn Azshara residiert eine geringe Gottheit: Lord Arkkoroc. Ihn müsst ihr aufsuchen. Aber seid gewarnt - wenn man Euch entdeckt, werden seine Diener alles tun, um Euch zu vernichten.\n\nZweifelsohne müsst Ihr einen Preis für solche Informationen bezahlen.", sourceObjective = "Sprecht mit Lord Arkkoroc in Azshara. Beginnt Eure Suche am Rand des Wassers, um den Tempel von Arkkoran zu finden.", completion = "Ein Dämonenlord?\n\n<Lord Arkkoroc lacht.>\n\nVielleicht kann der Eine Euch mit der passenden Information helfen, doch vorher müsst Ihr dem Einen helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3510] = { id = 3510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Name der Bestie", description = "Sie tötet meine Kinder, sterbliches Wesen. Sie nennt sich selbst die Herrscherin dieser Meere. Eine falsche Göttin, nichts weiter. Zermalmt sie und bringt mir all ihre Köpfe.\n\nDafür erhaltet Ihr den Namen, den Ihr sucht, und etwas anderes von gleicher Bedeutsamkeit.\n\nSie weilt im Gelege... Genannt wird sie Hetäre.\n\n<Lord Arkkoroc zeigt in Richtung Südwesten.>\n\nGeht!", sourceObjective = "Erschlagt Hetäre und bringt den blutigen Hetärenkopf, den geschlagenen Hetärenkopf und den verwundeten Hetärenkopf zu Lord Arkkoroc.", progress = "<Lord Arkkoroc beugt sich nach unten, um Euch zu betrachten.>\n\nWo sind sie?", completion = "Endlich jemand, der der Weisheit von Arkkoroc würdig ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[3511] = { id = 3511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Name der Bestie", description = "Wie versprochen, werde ich den Namen des Dämonenlords enthüllen: Es ist Razelikh der Entweiher. Zuerst muss ich jedoch etwas vorbereiten, das für Eure Reise von äußerster Wichtigkeit ist.\n\nDie Waffe, die Ihr herstellen wollt, benötigt einen Härter. Gebt mir einen Moment Zeit, um das Blut aus diesen Köpfen herauszupressen.\n\n<Lord Arkkoroc drückt die Köpfe mit seinen gigantischen Fäusten zusammen, sodass das Blut aus ihnen herausfließt.>\n\nBringt diesen Härter zurück zu Loramus, zusammen mit dem Namen der Bestie: Rakh'likh.", sourceObjective = "Bringt den Härter zurück zu Loramus Thalipedes.", progress = "Ihr seid zurückgekehrt! Erstaunlich, {race}. Habt Ihr den wahren Namen erfahren?", completion = "Durch den Härter wird das notwendige Vitriol, das wir zum Schmieden der Waffen benötigen, hinzugefügt. Es fehlt nur noch ein Schritt bis zu ihrer Herstellung.", sourceObjectiveStatus = "unverified-source-field" }
quests[3512] = { id = 3512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Eranikus' eigenen Worten", description = "{name}, als Erstes werden wir eine Methode ersinnen, um durch den Edelstein mit Eranikus zu sprechen. Zurzeit befindet er sich in einem gefährlichen Zustand zwischen Schlaf und Tod, verstrickt in ein Gewebe aus Alpträumen. Zwar ist die Essenz, die Ihr mir gegeben habt, stark besudelt, aber es gibt dennoch Hoffnung, dass wir zu ihm durchdringen.\n\nReist weit hinaus in das eisige Land des östlichen Winterspring und sucht einen unserer sterblichen Verbündeten, Umbranse den Geistsprecher. Er ist ein menschliches Medium, der für die Toten spricht. Zwar ist Eranikus noch nicht wirklich tot, trotzdem könnte er uns eine Hilfe sein.", sourceObjective = "Reist in den östlichen Teil von Winterspring und sprecht mit Umbranse, dem Geistsprecher.", completion = "Itharius war sehr weise, Euch zu mir zu senden. Eranikus ist in Eurem Sinne nicht wirklich tot, er wird uns bald mit seinen eigenen Worten Ratschläge erteilen. Im Moment vermag ich Euch nicht direkt zu helfen... zumindest noch nicht.\n\nIch werde Euch meine Fertigkeit des Totensprechens gern zur Verfügung stellen, aber zunächst benötige ich die Hilfe von jemandem, der - im Gegensatz zu mir - nicht durch die Gebrechlichkeit des Alters eingeschränkt ist. Mein machtvollstes Vorzeichengerät wurde mir gegen meinen Willen genommen, und solange ich es nicht wieder zurückerhalten habe, werden wir Eranikus nicht helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[3513] = { id = 3513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die runenverzierte Rolle", description = "Die offiziell aussehende Rolle wurde mit einem silbrigen Band eng verschnürt. Ihr seid Euch sicher, dass jemand das hier sehen möchte, aber wer?\n\nEs gibt einen Außenposten im Norden in der Nähe der Grenze von Ashenvale, und wenn die Informationen auf dieser Rolle die Nachtelfen betreffen, dann sollte die Rolle dorthin gebracht werden.", sourceObjective = "Bringt die runenverzierte Rolle zum nördlichen Wachturm des Brachlandes.", progress = "Was habt Ihr da?", completion = "Ach... Wo habt Ihr das gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[3514] = { id = 3514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hordenpräsenz", description = "Diese Rolle ist von der Ränke schmiedenden Dryade Rynthariel, Schlüsselmeisterin des Krallenbaus auf dem Steinkrallengipfel.\n\nMit dem Boten, von dem Ihr diese Rolle erbeutet habt, hat sie jetzt ja wohl keinen Kontakt mehr, aber nachgeben dürfen wir trotzdem nicht. Die Horde wird ihre Kundschafter hier nicht tolerieren.\n\n{name}, reist zum Krallenbau. Tötet Rynthariel und stellt ein Symbol auf, das alle sehen können. Nehmt diese Hordenflagge mit Euch, {name}. Hisst sie im Krallenbau, damit sie es sich zweimal überlegen, bevor sie einen weiteren Boten durch unser Gebiet schicken.", sourceObjective = "Tötet die Anführerin des Krallenbaus, Rynthariel die Schlüsselmeisterin.", completion = "Ihr seid ganz schön dreist! Rynthariel aus dem Bau zu beseitigen, ist ein großer Schritt, {name}. Sie werden sich nur langsam neu formieren und so können wir im Brachland künftig mit weniger Allianzläufern rechnen. Sie werden es sich gut überlegen, bevor sie noch mal einen hier entlangschicken.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[3517] = { id = 3517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen stehlen", description = "Ich muss zugeben, {name}, ich habe das Beste aus meiner Situation in Azshara gemacht. Belgroms Bestrafung hatte schon seine Vorteile.\n\nBevor ich wegging, habe ich einige Nachforschungen angestellt. Ihr wärt überrascht darüber, wie viele wertvolle Gegenstände hier einfach so herumliegen.\n\nIch erzähle Euch noch mehr von meinen Geschäften und gebe Euch sogar einen Anteil an meinen Gewinnen, wenn Ihr mir helft, ein paar von den Sachen einzusammeln.\n\nIn den östlichen Ruinen von Eldarath gibt es Schrifttafeln, die ich benötige. Alle vier wurden nach Hochgeborenenhexern benannt. Bringt sie mir und wir können weiterreden.", sourceObjective = "Sucht die Schrifttafel von Beth'Amara, die Schrifttafel von Jin'yael, die Schrifttafel von Markri und die Schrifttafel von Sael'hai, bevor Ihr zu Jediga in Azshara zurückkehrt.", progress = "Die Schrifttafeln, die Ihr für mich sammeln sollt, dürften den richtigen Leuten ein hübsches Sümmchen einbringen. Ich werde Euch sagen, an wen sie geliefert werden sollen, sobald Ihr sie gefunden habt. Ich bin nicht dumm... Ihr werdet Euren Anteil erst bekommen, wenn ich den Beweis erhalten habe, dass sie geliefert worden sind.\n\nAlso macht Euch an die Arbeit... wir haben nicht den ganzen Tag Zeit. Sonst muss ich vielleicht einen anderen suchen, der mir behilflich ist.", completion = "Wunderbar, {name}, und auch noch in gutem Zustand. Dies sollte uns von den beteiligten Gruppen einen guten Preis einbringen.\n\nLasst uns hier nicht länger als nötig verweilen. Lasst uns Geld verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3518] = { id = 3518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an Magatha", description = "Die erste Schrifttafel geht an einen weiblichen Tauren... mit Namen Magatha. Sie gehört zu den Ältesten in Thunder Bluff und zu den Befürwortern der Allianz zwischen den Tauren und den Verlassenen. Sie ist mehr als jeder andere der Ältesten der Meinung, dass die Tauren und ihre Lebensart den Verlassenen helfen können, einen Weg zurück zum Menschsein zu finden.\n\nBringt Ihr die Schrifttafel von Beth'Amara. Die Schrifttafel kann das fehlende Glied sein, das sie benötigt, um den Verlassenen zu helfen... das behauptet sie jedenfalls.", sourceObjective = "Bringt die Schrifttafel von Beth'Amara zu Magatha in Thunder Bluff.", progress = "Ja, {name}. Was kann ich für Euch tun? Ich muss mich um viele Dinge kümmern, also fasst Euch bitte kurz.", completion = "Ah, endlich, die Schrifttafel von Beth'Amara. Ich fragte mich schon, ob meine Zusammenarbeit mit Jediga ein Fehler war oder ob die Arme in Azshara ihren Tod gefunden hat. Ich freue mich, dass sie erfolgreich war.\n\nBeth'Amara war einer der einflussreichsten Alchimisten der Hochgeborenen. Unter anderem wird gesagt, dass der Hexer in der Lage war, Metall zu transmutieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[3519] = { id = 3519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund in Not", description = "Aghhh... Ich wurde ziemlich schlimm von einer Spinne namens Githyiss die Üble gebissen, während ich die Spinnenhöhle ganz in ihrer Nähe erforschte. Ich bin sicher, dass ich ernsthaft vergiftet bin; Ihr müsst mir helfen.\n\nSagt es bitte Dirania Silvershine. Sie wird mir helfen können.\n\nBeeilt Euch... Mir ist so schwindelig...", sourceObjective = "Sprecht mit Dirania Silvershine in Shadowglen.", completion = "Oh nein, ich habe mich schon gefragt, warum ich Iverron heute noch nicht gesehen habe. Dabei habe ich ihn immer vor diesen Spinnen gewarnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3520] = { id = 3520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreischergeister", description = "Ich suche die Geister der Talkreischer von Feralas. Sie sind die Cousins eines alten, alten Gottes und ihre Geister sind mit ihm verbunden.\n\nNehmt diesen Dornbuschzauberstab und reist nach Feralas. Sucht und besiegt die Talkreischer in Süd- und Mittel-Feralas, und schwingt meinen Dornbuschzauberstab dann über ihre gefallenen Körper. Dadurch wird ihr Geist dazu gebracht, sich zu zeigen. Berührt den Geist und sammelt seine Essenz.\n\nKommt mit meinem Dornbuschzauberstab und der gesammelten Essenz zu mir zurück, und ich werde Euch mehr von dem alten Gott erzählen, von dem ich sprach.", sourceObjective = "Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück.", progress = "Habt Ihr die Essenz der Kreischergeister gesammelt, {name}?", completion = "Ihr habt Eure Sache gut gemacht, {name}. Vielleicht ist es jetzt an der Zeit, mehr zu erzählen...\n\nEs gibt bei den Trollen eine alte Prophezeiung, laut der der tote Gott Hakkar der Seelenschinder eines Tages auf diese Erde zurückkehren wird. Einige sagen, die Ankunft von Hakkar würde Freude und Ruhm für alle Trolle bringen, andere glauben hingegen, dass seine Auferstehung das Ende aller Dinge bedeutet.\n\nIch glaube diese Geschichten nicht, aber ich weiß, dass die Essenz von Hakkar eine große Macht enthält, und diese Macht sollte von jenen fern gehalten werden, die sie missbrauchen würden...", sourceObjectiveStatus = "unverified-source-field" }
quests[3521] = { id = 3521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iverrons Gegengift", description = "Wir dürften in der Lage sein, Iverron zu helfen, denn ich kenne ein Gegengift, das gegen das Gift wirkt. Bevor ich es herstellen kann, benötige ich allerdings einige Zutaten.\n\nIch brauche Hyazinth-Pilze. Sie wachsen unter Bäumen. Ihr könnt sie aber auch von den Grell südlich von hier sammeln; sie scheinen sie sehr zu mögen. Außerdem brauche ich noch Mondblütenlilien, die nur an Wasserteichen wachsen.\n\nDie letzte Zutat könnte die Schwierigste sein. Sammelt Waldwebersekret von genau den Spinnen, die Iverron vergiftet haben.", sourceObjective = "Sammelt 7 Hyazinth-Pilze, 4 Mondblütenlilien und 1 Waldwebersekret für Dirania Silvershine in Shadowglen.", progress = "Bitte sammelt die Zutaten, {name}. Iverron braucht unsere Hilfe!", completion = "Elune sei Dank, dass Ihr diese Zutaten so schnell gesammelt habt.\n\nEs dauert nur einen Moment, bis ich das Gegengift zubereitet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[3522] = { id = 3522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iverrons Gegengift", description = "Das Gegengift ist fertig, {name}. Bitte achtet darauf, dass Iverron es auch trinkt.\n\nEs gibt jedoch etwas, das Ihr wissen sollt: Das Gegengift ist nur 5 Minuten wirksam. Ihr müsst es ihm rechtzeitig bringen.\n\nMögen Eure Füße beflügelt sein, {name}.", sourceObjective = "Bringt Iverrons Gegengift zu Iverron, bevor die Zeit um ist. Ihr findet Iverron bei der Höhle im Norden.", progress = "Oh... {name}, ich bin so froh, dass Ihr wieder zurückgekommen seid.", completion = "Was ist das, {name}?\n\nOh, ich wusste, Dirania würde mir helfen können!\n\n\n\nIch gerate ständig in Schwierigkeiten und Dirania, na ja, sie schafft es immer wieder, mir da herauszuhelfen.\n\nIch fühle mich schon viel besser, aber ich denke, ich werde hier noch eine Weile sitzen bleiben, bis ich wieder ganz in Ordnung bin. Na ja, das ist der eine Grund, und ich hoffe außerdem, dass Ihr für mich einen Weg durch diese heimtückischen Waldweberspinnen frei macht...", sourceObjectiveStatus = "unverified-source-field" }
quests[3523] = { id = 3523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißel der Niederungen", description = "Phantastisch! Mein Name ist Belnistrasz und ich danke Euch für meine Rettung. Ich hatte mich schon tot gewähnt... oder schlimmer, als Mahlzeit für dieses von der Geißel befallene Gezücht. Ja, richtig gehört, ich sagte Geißel; sie haben anscheinend mit den Stachelebern hier eine Art Vereinbarung getroffen, und dieser Alptraum ist das Ergebnis.\n\nHört mir zu... anstatt einfach wegzulaufen, möchte ich doch uns allen zuliebe versuchen, etwas zu ändern. Könntet Ihr mir dabei helfen? Es ist wahrscheinlich gefährlich, aber Ihr scheint ein Typ zu sein, dem das nicht viel ausmacht.", sourceObjective = "Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab.", progress = "Ich schere mich nicht um Politik; mich interessiert nicht, ob Ihr Euch auf die Seite der Horde oder der Allianz schlagt. Ich bin eher daran interessiert, direkte und schreckliche Drohungen gegen alle Völker auszuschalten... und das hier ist eine ziemlich große.\n\nWenn Ihr willens seid, für alle Völker ein wahrer Held zu sein, dann übergebt mir den Schwurstein, den ich Euch gab, als Zeichen der Verpflichtung. Ich bin... nicht aus dieser Gegend, ein Schwurstein bedeutet für Leute wie mich ein Bund der Übereinkunft.", completion = "Phantastisch, ich dachte schon, dass Ihr heldenmutig ausseht! Ich will Euch nicht anlügen, {name}, wir haben eine Menge Arbeit vor uns. Wenn wir uns auf die vor uns liegende Aufgabe konzentrieren, sollten wir in der Lage sein, als Sieger aus der Sache hervorzugehen.\n\nJetzt will ich Euch auf den neuesten Stand der Dinge bringen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[3524] = { id = 3524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Land gespült", description = "Majestätische Meereskreaturen begeben sich häufig an die Ufer von Dunkelküste, und liegen dort gestrandet, bis sie sterben. Vor kurzem wurden diese Kreaturen in immer größerer Zahl an Land gespült. Ich wurde vom Tempel des Mondes zur Untersuchung dorthin geschickt, aber die Anwesenheit der Murlocs entlang des Wassers hat meine Forschungen schwierig gemacht.\n\nEs gibt eine riesige Kreatur, die unmittelbar südlich von Auberdine an Land gespült wurde und die von den widerlichen Grauflossenmurlocs umringt ist. Könntet Ihr Euch dorthin begeben und Knochen von dieser Kreatur für unsere Studien sammeln?", sourceObjective = "Sammelt Meereskreaturknochen von der gestrandeten Meereskreatur unmittelbar südlich von Auberdine und kehrt dann mit ihnen zu Gwennyth Bly'Leggonde nach Auberdine zurück.", progress = "Diese Kreaturen begannen erst vor kurzem, in solch alarmierender Zahl an den Ufern von Dunkelküste zu landen. Ich kann mir nicht helfen, aber ich glaube, dass dies irgendein schlechtes Omen ist. Wenn Ihr eine Probe der Knochen dieser Kreatur im Süden beschaffen könntet, würde uns das in Darnassus sehr bei der Einschätzung der Situation helfen!", completion = "Ich hoffe, die Murlocs haben Euch keine allzu großen Schwierigkeiten bereitet, als Ihr das für uns geholt habt! Ich werde das definitiv mit dem nächsten Hippogryph nach Darnassus schicken. Der Tempel des Mondes hat mir einige Geldmittel zur Verfügung gestellt, um damit Hilfe zu belohnen; bitte nehmt dies mit unserem Dank.\n\nAufgrund Eures Erfolges hier wage ich, Euch eine Gelegenheit zu bieten, dem Tempel des Mondes erneut zu helfen, falls Ihr interessiert seid ...", sourceObjectiveStatus = "unverified-source-field" }
quests[3525] = { id = 3525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausschalten des Götzen", description = "In der Nähe des Eingangs befindet sich ein Götze, der als makabrer Ofen für die Stacheleber fungiert; die Bestien... verzehren die aus dem Brachland Entführten. Ich kann den Götzen außer Funktion setzen und verhindern, dass sie ihn erneut nutzen, aber ich benötige dabei Eure Hilfe. Mein Plan: Begleitet mich zum Götzen. Wenn wir dort angekommen sind, werde ich das Ritual einleiten. Ich werde kaum in der Lage sein, mit Euch zu kommunizieren, geschweige denn, mich zu verteidigen. Schützt mich, während ich den Götzen außer Funktion setze. Wenn sie mich erschlagen, dann ist alles aus.\n\nSteht Ihr mir bei?", sourceObjective = "Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln von Razorfen.\n\nBeschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten.", completion = "Belnistrasz' plötzlicher Abgang hat eine brennende Kohlenpfanne hinterlassen. Während Ihr in die Flammen starrt, erfüllt das Bild eines roten Großdrachen mit riesigen Flügeln Euren Geist. Eine rauere Version von Belnistrasz' Stimme spricht direkt zu Euch.\n\n\"Wahrlich, sterbliche Wesen, Ihr seid die Helden, die ich mir erhofft hatte. Dank Euch gehören die Schlächtereien, die diese Bestien begangen haben, der Vergangenheit an. Mein Glaube an sterbliche Wesen wie Euch ist wieder einmal erneuert worden. Nehmt dies als Belohnung, die eines Helden würdig ist.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[3526] = { id = 3526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Ingenieurskunst", description = "Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Natürlich ist die Goblin-Ingenieurskunst die Wahl aller brillanten Ingenieure. Durch den klugen Einsatz von hochempfindlichen Sprengstoffen und phantastischen Ausrüstungsgegenständen lernt Ihr, die Welt zu meistern!\n\n{name}, lest diese Anleitung. Wenn Ihr etwas über Goblin-Ingenieurskunst wissen wollt, dann bringt sie zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.", progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, {name}, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, {name}, und Ihr könnt vielleicht was lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3527] = { id = 3527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prophezeiung von Mosh'aru", description = "Die alte Prophezeiung von Mosh'aru berichtet von einer Methode, die Essenz des Gottes Hakkar zu bewahren. Sie wurde auf zwei Schrifttafeln niedergeschrieben und zu der Troll-Stadt Zul'Farrak gebracht, westlich von Gadgetzan.\n\nBringt mir die Mosh'aru-Schrifttafeln!\n\nDie erste Schrifttafel hat der Troll Theka der Märtyrer, der schon lange tot ist. Man sagt, dass seine Verfolger zu Skarabäen verflucht wurden und nun an seinem Schrein herumhuschen.\n\nDie zweite Schrifttafel hat die Wasserbeschwörerin Velratha, in der Nähe des hochheiligen Teiches von Gahz'rilla.\n\nWenn Ihr die Schrifttafeln habt, bringt sie zu mir.", sourceObjective = "Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris.", progress = "Habt Ihr die Schrifttafeln der Prophezeiung von Mosh'aru, {name}?\n\nWenn ich die Schrifttafeln in meinen Besitz bringe, werde ich sie studieren und erfahren, wie die Essenz von Hakkar bewahrt werden kann!", completion = "Ah, das ist gut. Ich kann diese alten Schrifttafeln zusammenfügen und dann ihre verborgenen Geheimnisse studieren.\n\nMeine Schuld Euch gegenüber wächst, {name}. Und sie wird noch weiter wachsen!", sourceObjectiveStatus = "unverified-source-field" }
quests[3528] = { id = 3528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gott Hakkar", description = "Jetzt wird es Zeit, die Essenz des Avatars von Hakkar einzufangen.\n\nBringt das Ei von Hakkar in das Sanktum des Gefallenen Gottes im Versunkenen Tempel in Azeroth. Ruft die Macht des Eies an, um den toten Gott aufzuwecken.\n\nEr wird seine Diener gegen Euch ausschicken. Besiegt seine Bluttrinker und nehmt ihr Hakkari-Blut an Euch; dann benutzt das Blut, um die ewigen Flammen auszulöschen, die Hakkars Geist halten. Erst wenn alle Flammen gelöscht sind, wird der Avatar von Hakkar unsere Welt betreten.\n\nBesiegt ihn und gebt seine Essenz in das Ei von Hakkar.", sourceObjective = "Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris.", progress = "Habt Ihr den Avatar von Hakkar besiegt, {name}? Hat seine Essenz das Ei, das ich Euch gab, schon ermächtigt?", completion = "Die Essenz von Hakkar wurde eingefangen! Gerade jetzt beginnt sich das Leben im Ei zu regen! Sind die Geschichten von Hakkar doch wahr?\n\nDas darf nicht wahr sein! Ich fürchte mich vor dem, was Hakkar tun könnte, wenn er erneut geboren wird. Ich werde dieses Ei sicher aufbewahren und darauf achten, dass es niemals in böse Hände gerät.\n\nEure Dienste für mich sind nun zu Ende, {name}. Ihr habt eine Legende berührt und Eure Taten werden eines Tages das Antlitz unserer Erde verändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[3541] = { id = 3541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an Jes'rimon", description = "Ich kenne einen Hehler in Orgrimmar. Er wohnt in der Gasse. Er ist ziemlich schwer zu finden, wenn Ihr nicht wisst, wo Ihr suchen sollt. Wenn Ihr Euch dort in einem der höchsten Gebäude umschaut, solltet Ihr ihn jedoch ohne Probleme finden können.\n\nTut mir aber bitte einen Gefallen und posaunt nicht in ganz Kalimdor herum, dass er dort ist und was er so tut, das wäre schlecht für uns beide.\n\nEr wird uns einen mehr als fairen Preis für die Schrifttafel von Jin'yael geben. Ich weiß zwar nicht genau warum, aber Ihr hättet mal sehen sollen, wie aufgeregt er war, als er von ihrem Aufenthaltsort erfahren hat.", sourceObjective = "Bringt die Schrifttafel von Jin'yael zu Jes'rimon nach Orgrimmar.", progress = "Ja? Was wollter denn, Mann? Hab heute noch viel zu tun, und Ihr seid in mei'm Terminkalender nich' eingetrag'n. Wenner mich weiter belästigt, kann sich das aber sicherlich noch ändern.", completion = "Ahhh, Jediga hat ihr Päckchen den weit'n Weg von Azshara hergeschickt. Gut. Hab da schon drauf gewartet.\n\nJediga, das is' mal 'ne feine Frau... 'ne tödliche dazu. Was könnt da besser sein?\n\nSeht Euch das an... die Schrifttafel is' in perfekt'm Zustand. Ihr seid 'n guter Bote, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[3542] = { id = 3542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an Andron Gant", description = "Andron Gant ist mein nächster Kontakt. Normalerweise hält er sich in Undercity auf... ganz in der Nähe des Apothekariums.\n\nEr war ein bisschen redselig, als das Gespräch darauf kam, warum er die Schrifttafel haben wollte. Anscheinend wollen einige der Magier von Undercity die Arkanzauber studieren, die die Hochgeborenen benutzt haben. Sie glauben, dass ihnen diese Schrifttafel dabei helfen würde. Markri war sehr bewandert im Beschwören von Kreaturen, besonders von Elementaren.\n\nNehmt die Schrifttafel von Markri und kommt zu mir zurück, um Euch Euren Teil der Belohnung abzuholen.", sourceObjective = "Bringt die Schrifttafel von Markri zu Andron Gant nach Undercity.", progress = "Nun... <hick>... was für eine Überraschung? Ein Abenteurerererer... <hick>!\n\nWasss k'nn ich für Euch tun... <hick>?", completion = "Hier, nehmt ein paar Münzen... holt Euch'n... <hick>... neue Rüstung oder so was...\n\nDas gibt'n nettes Gold für die richt'gen... <hick> Leute.", sourceObjectiveStatus = "unverified-source-field" }
quests[3561] = { id = 3561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Erzmagier Xylem", description = "Die letzte Schrifttafel geht an eine sehr gefährliche Person, {name}. Hört auf mich, wenn ich Euch sage, dass ich dieser Person viel weniger traue als irgendeiner der anderen, die Ihr in meinem Namen getroffen habt.\n\nErzmagier Xylem hat einen Turm in den Hügeln mit Ausblick auf ganz Azshara. Er ist zwar ein Mensch, aber er benimmt sich wie kein Mensch, den ich jemals getroffen ... oder getötet habe. Er strahlt Macht aus, und ich wage nicht, ihn zu fragen, was er mit der Schrifttafel vorhat.\n\nEr kam zu mir, aber er teilte mir mit, dass seine Leibwache Sanath mir helfen würde, zum Turm zu kommen, wenn ich bereit sei, ihn zu treffen. Sucht nach Sanath im Norden.", sourceObjective = "Bringt die Schrifttafel von Sael'hai zu Erzmagier Xylem in Azshara.", progress = "Wie kann ich Euch helfen, {name}?", completion = "Ah, die Schrifttafel von Sael'hai... wie lange habe ich darauf gewartet, sie zu erforschen.\n\nDanke, {name}. Ihr könnt Jediga mitteilen, dass sie ihre Sache gut gemacht hat. Das ist mit Sicherheit die Bezahlung wert, die sie gefordert hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[3562] = { id = 3562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magathas Bezahlung für Jediga", description = "Bringt diese Notiz zu Jediga. Sagt ihr, dass ihre Bezahlung hier auf sie wartet, wenn sie zurückkommt. Und sagt ihr, dass ich mit ihrer Arbeit zufrieden bin.\n\nBeeilt Euch, {name}. Sagt Eurer Meisterin, dass ich hier auf sie warten werde.", sourceObjective = "Bringt Magathas Notiz zu Jediga in Azshara.", progress = "Na, was hat Magatha gesagt? Die alte Greisin... Ich wette, sie war nicht sehr höflich.", completion = "Ah, gut. Sie war ja vernünftiger, als ich es erwartet habe... zumindest zu Euch. Ich habe schon fast damit gerechnet, dass sie Euch für meine Ungebührlichkeit, jemand anderes an meiner Stelle zu schicken, bestrafen würde. Sie will diese Schrifttafel anscheinend wirklich dringend haben. Interessant.\n\nIch werde ein anderes Mal darüber nachdenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[3563] = { id = 3563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jes'rimons Bezahlung für Jediga", description = "Bringt diesen Brief zu Jediga. Lasst sie wissen, dass unser Handel vorteilhaft ist und ich mit ihrer Arbeit zufrieden bin.\n\nSagt ihr, sie soll schnell nach Orgrimmar zurückkommen, und Jes'rimon würde gut für sie sorgen.\n\nSagt ihr das! Und, vielleicht benötige ich in Zukunft noch einmal Eure Dienste, {name}.", sourceObjective = "Bringt Jes'rimons Notiz zu Jediga in Azshara.", progress = "Habt Ihr schon mit Jes'rimon gesprochen?\n\nEr ist zwar ein Eber unter Trollen, aber seine Informationen sind eigentlich immer korrekt, und er bezahlt gut.\n\nWenn Ihr mit seinem Benehmen umgehen könnt, habt Ihr einiges an Geld von seinen geschäftlichen Bemühungen zu erwarten.", completion = "Wie ich an seiner Notiz erkennen kann, war er sehr erfreut... vielleicht ein wenig zu sehr.\n\nVielleicht werde ich mir eines Tages die Zeit nehmen, ihn wissen zu lassen, wie sehr ich seine Avancen schätze. Na, das ist immerhin ein Grund, sich auf eine längere Anwesenheit in Azshara zu freuen.\n\nHier habt Ihr Euren Anteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[3564] = { id = 3564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Androns Bezahlung für Jediga", description = "Hier... bringt... <hick> das zu Jediga. Viel Glück!", sourceObjective = "Bringt Androns Notiz zu Jediga in Azshara.", progress = "Habt Ihr Euch schon mit Andron getroffen? Er verlässt Undercity nur selten, Ihr müsstet ihn leicht finden können.", completion = "Perfekt... moment mal.\n\nHaha! Was habt Ihr ihm gesagt, als Ihr die Schrifttafel gebracht habt, {name}? Er hat uns viel zu viel bezahlt! Nicht, dass ich mich beschweren wollte. Habt Ihr ihm gesagt, dass der Preis sich geändert hat? Oder war er wieder mal betrunken?\n\nAuch egal... hier, Ihr sollt auch einen Extra-Anteil haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[3565] = { id = 3565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xylems Bezahlung für Jediga", description = "Was ist? Oh, ja, Eure Bezahlung. Natürlich.\n\nNehmt das und fort mit Euch. Jediga wartet bestimmt schon voller Geduld auf Eure Rückkehr.", sourceObjective = "Bringt Xylems Notiz zu Jediga in Azshara.", progress = "Nun, was hat Xylem gesagt? Er hat Euch doch nichts getan, oder? Hat er Euch verzaubert? Oder Euch dazu gebracht, für ihn zu arbeiten?", completion = "Keine Probleme? Überhaupt keine? Also das ist ja schon bemerkenswert... Ich habe erwartet, dass er einigen Widerstand zeigt oder zumindest unsere Übereinkunft verrät. Hmm, vielleicht kann man ihm ja doch trauen.\n\nGut, darüber muss ich jetzt nicht nachdenken. Hier ist Euer Anteil. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[3566] = { id = 3566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Obsidion!", description = "Es... Es... Es war alles eine Falle.\n\nVergebt... mir.\n\nTötet den Bastard... Tötet ihn für uns... für Thorius.", sourceObjective = "Tötet Lathoric den Schwarzen und Obsidion. Kehrt zurück zu Thorius nach Ironforge mit dem Kopf von Lathoric dem Schwarzen und dem Herzen von Obsidion.", progress = "Ich glaube Euch nicht! Bringt mir Beweise!", completion = "<Thorius wird ganz blass.>\n\nDas... das darf nicht wahr sein. Mein eigener Bruder? Er hat all das inszeniert?\n\n<Thorius' Gesicht verzerrt sich vor Wut.>\n\nEr hat mich verraten, er hat Ironforge verraten! Es scheint, als sei der Einfluss der alten Götter in diesem Land immer noch sehr stark. Ich fürchte, wenn mein Bruder - ein einst so edler und ehrenwerter Mann - so leicht dem Willen von Ragnaros unterworfen werden konnte, ist hier niemand mehr sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[3567] = { id = 3567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Spitze", sourceObjective = "Würdet Ihr den Ausblick von einem der Zwillingskolosse bevorzugen? Ich kann Euch dorthin schicken, {race}.\n\nAber überlegt, wie Ihr wieder herunterkommt. Ich kann Euch nur nach oben schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[3568] = { id = 3568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitete Verderbnis", description = "Seht Ihr die Tauren hinter mir - diejenige, die aussieht, als müsste sie sich jeden Moment übergeben? Sie war erst vor kurzem in Azshara. Sie behauptet, dass sie von einigen Naga verwundet wurde, als sie sich den Weg durch die Ruinen von Eldarath bahnte.\n\nNachdem sie einige von ihnen zurückschlagen konnte, machte sie eine Pause am Strand und trank aus einem der Gezeitenteiche. Jetzt ist ihr ein wenig übel ... unter anderem.\n\nIch würde gern herausfinden, was sie getrunken hat. Nehmt diesen Kasten, darin befinden sich einige leere Phiolen, die ich mit Etiketten versehen habe. Füllt jede an einem anderen Teich und kehrt dann zurück.", sourceObjective = "Füllt alle 4 leeren Phiolen an den Gezeitenteichen entlang der Küste der Ruinen von Eldarath in Azshara und kehrt dann zu Chemiker Cuely zurück.", progress = "Ihr wisst, wohin das hier führt, nicht wahr, {name}? Sie wird dies nicht überleben... seht sie Euch an. Das Beste, was sie jetzt noch tun kann, ist, uns bei der Suche nach einem Heilmittel für die Seuche zu helfen. Das Wasser, das sie getrunken hat, könnte einen Hinweis enthalten, wie wir das anstellen können. Sie wird sowieso sterben; dann könnte sie doch, ehe sie stirbt, etwas Großmütiges für unser Volk tun. Ist es nicht so?", completion = "Großartig. Ihr seid zurück, bevor sie gestorben ist. Gut, gut.\n\nDann lasst uns mal anfangen, ja?\n\nIch habe ihre Symptome nun schon eine Weile beobachtet, und es ist sehr hässlich. Ich bin überrascht, dass sie noch steht. Sie musste sich schon drei oder vier Mal übergeben ... ein sehr angenehmer Geruch.\n\nBitte wartet einen Moment, bis ich etwas zusammengemischt habe, um es an unserer ... Freundin ... zu testen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3569] = { id = 3569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitete Verderbnis", description = "Gebt das Thersa. Vielleicht wird das hier sie heilen... vielleicht aber auch nicht. Wir werden es nicht wissen, solange sie es nicht getrunken hat.", sourceObjective = "Gebt Cuelys ElixierThersa Windsong in Undercity.", progress = "Ich kam nach Undercity, weil ich gehört habe, die Alchimisten hätten hier intensiv geforscht, um ein Heilmittel für ihre eigene Krankheit zu finden. Es hieß, dass sie vielleicht auch mir helfen könnten.\n\nObwohl dieser Ort mich alles andere als willkommen heißt, blieb mir keine Wahl - die Erkrankung, die mich befallen hat, zerreißt mich innerlich, und ich benötigte ihre sofortige Hilfe.", completion = "Chemiker Cuely war sehr zuvorkommend... beängstigend zuvorkommend sogar. Aber da er sagt, dass mir das hier helfen wird, habe ich wohl keine andere Wahl. Ich habe keine Zeit, um eine andere Lösung zu suchen. Ich habe bereits mit Priestern und Schamanen gesprochen. Keiner konnte mir helfen.\n\nHoffen wir, dass die Erdenmutter über meinen Geist wacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[3570] = { id = 3570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitete Verderbnis", sourceObjective = "Ich hätte mir nie träumen lassen, dass das Elixier so schnell Wirkung zeigen würde. Danke, {name}. Ich werde mich sofort an die Untersuchung der restlichen Proben machen. Bestimmt werden sie für Lady Silvanas und die Verlassenen schon bald von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[3601] = { id = 3601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kim'jael, fürwahr!", description = "Kim'jael, fürwahr! Wisst Ihr, was Kim'jael für die Blutelfen bedeutet, {name}? Kleine Ratte... oder so etwas in der Art. Diese großen Angeber!\n\nSie haben mich angeworben, damit ich ihnen helfe, das Gebiet auszukundschaften und nach einer Art verlorenen Schatz zu suchen. Natürlich habe ich sofort zugegriffen, als sie das Wort 'Schatz' erwähnten und die Summe, die sie mir bezahlen wollten. Aber dann haben sie sich gegen mich gewandt und versucht, mich zu töten... MICH!\n\nDas zeigt einmal mehr, dass einem Blutelfen nicht zu trauen ist.\n\nMein Problem ist: Sie haben immer noch meine Ausrüstung, und ich kann sie nicht wiederbekommen. Helft Ihr mir?", sourceObjective = "Durchsucht den Thalassian-Stützpunkt nach Kim'jaels Kompass, Zielfernrohr, ausgestopftem Huhn und Wizzlegoober und bringt ihm dann alles nach Azshara zurück.", progress = "Diese stinkenden Blutelfen. Ich sag Euch, wenn ich so stark wäre wie Ihr, würde ich mich dorthin begeben und ihnen selbst ein paar Dinge beibringen! Aber ich muss mich damit begnügen, Euch zu bezahlen, damit Ihr Euch um sie kümmert.", completion = "Haha! Denen habt Ihr's kräftig gezeigt, was?!\n\nDas ist toll! Das wird diese Blutelfen lehren, ihre Partner zu betrügen... besonders jemanden, der so loyal ist wie ein Goblin-Händler! Pah, Blutelfen...!\n\nTja, das Mindeste, was ich für Euch tun kann, ist, für Eure Zeit zu zahlen... so wie ich es gesagt habe.\n\nBitteschön... das hier sollte nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[3602] = { id = 3602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsharit", description = "Die uralten Klippenriesen aus dem südlichen Azshara ernähren sich von Felsen und Gebäuden des Landes. Ihre Ausscheidung ist, bedingt durch die Ernährung, ein höchst formbarer und extrem starker Kristall, der als Azsharit bekannt ist.\n\nDer südliche Bogen ist übersät mit diesen Gebilden, aber es konnten nur wenige geborgen werden, da die Riesen über ein extrem angriffslustiges Naturell verfügen.\n\nIhr sollt nach Süden vorstoßen und genügend Azsharit einsammeln, um den Waffenkörper herzustellen. Meine Teufelshunde werden Euch beim Einsammeln der Kristalle behilflich sein.", sourceObjective = "Sammelt 20 kristallisierte Azsharite im südlichen Azshara. Ihr könnt den Teufelshund benutzen, damit er Euch beim 'Erschnüffeln' der gut versteckten Ablagerungen behilflich ist.\n\nKehrt zu Loramus zurück, sobald Ihr die Aufgabe erfüllt habt.", progress = "Das Böse schläft nicht, Dummkopf. Ihr werdet genug Zeit zum Ausruhen haben, wenn Ihr erst einmal tot seid. Aber jetzt, bringt mir diese Kristalle.", completion = "Eure Aufgaben in Azshara sind abgeschlossen, sterbliches Wesen. Ich muss nun die notwendigen Komponenten für den nächsten Schritt Eures Abenteuers schmieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[3621] = { id = 3621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herstellung von Teufelsbann", description = "Die Waffen können jetzt geschmiedet werden. Ihr müsst den ausgehärteten Azsharit zu jemandem bringen, der die Fähigkeit besitzt, Teufelsenergie zu bändigen.\n\nIm Schlingendorntal gibt es einen solchen Schmied. Galvan der Alte, Anführer des Mithrilordens, wird die Waffen nach Euren Angaben fertigen. Ihr könnt sein Lager zwischen Zul'Gurub und dem Ogerhügel der Mosh'Ogg finden.\n\nMögen Eure Entschlossenheit und Euer Glaube Euch durch diese Tortur leiten. Solltet Ihr versagen, wisset, dass Euer Gott auf Euch herablächelt, sterbliches Wesen.", sourceObjective = "Bringt die Lieferung zu Galvan dem Alten im Schlingendorntal.", progress = "Loramus, eh? Es ist schon viele Jahre her, dass ich diesen Namen hörte.", completion = "Meine Güte, allein der Gedanke, was Ihr wohl durchmachen musstet, um an dieses Material zu gelangen! Nur wenige wagen sich nach Azshara und kehren lebend zurück, ganz zu schweigen von denen, die sich mit Halbgöttern und Riesen messen!", sourceObjectiveStatus = "unverified-source-field" }
quests[3625] = { id = 3625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberte Azsharit-Teufelswaffe", description = "{name}, die Herstellung jeder einzelnen Waffe wird einige Zeit in Anspruch nehmen.\n\nAußerdem dürft Ihr die Macht des Teufelsfluchs nur einmal alle drei Minuten verwenden. Seine schwächenden Eigenschaften gegen Razelikh den Entweiher und seine Diener können unterschiedlich lang dauern. Aus diesem Grund dürft Ihr den Teufelsfluch erst dann freigeben, wenn der richtige Zeitpunkt gekommen ist!\n\nGebt mir jetzt einen Moment, damit ich Eure Waffen fertigen kann, {name}.", sourceObjective = "Wartet, bis Galvan die Waffen fertig geschmiedet hat.", progress = "Wenn der Schmiedevorgang unterbrochen wird, könnte die Waffe fehlerhaft sein. Habt Geduld, {name}.", completion = "<Galvan wischt sich den Schweiß von der Stirn.>\n\nEinen besseren Dämonentöter als diesen hier gab es noch nie, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[3626] = { id = 3626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr in die verwüsteten Lande", description = "Die Stunde der Erlösung rückt näher, {name}. Ihr müsst mit Eurer neuen Waffe in die verwüsteten Lande zurückkehren und mit dem Gefallenen Helden der Horde sprechen, um Eure letzte Aufgabe zu erhalten.", sourceObjective = "Kehrt zum Gefallenen Helden der Horde zurück.", completion = "Ihr seht aus wie ein erprobter Kämpfer, {name}. Seid Ihr bereit, Euch Razelikh und seinen Dienern zu stellen?", sourceObjectiveStatus = "unverified-source-field" }
quests[3627] = { id = 3627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das zerbrochene Amulett vereinen", description = "Um den Entweiher zu erreichen, müsst Ihr zunächst das Dreigestirn der Macht zerstören und die Teile des Amuletts beschaffen. Wenn Ihr alle drei Teile beschafft habt, kommt zu mir zurück, und ich werde Euch weitere Anweisungen geben.\n\nGeht, {name}! Auf in die verwüsteten Lande! Sevine, Allistarj und Grol müssen fallen!", sourceObjective = "Tötet Grol den Zerstörer, Lady Sevine und Erzmagier Allistarj. Nehmt das Amulett von Grol, das Amulett von Sevine und das Amulett von Allistarj von ihren Leichen.\n\nDenkt daran, Eure Verzauberte Azsharit-Teufelswaffe zu BENUTZEN, um die Triade zu schwächen. Auf eine andere Weise können sie nicht getötet werden - aber verwendet sie weise...", progress = "Die drei werden das Eine formen, das Eine wird den Weg erhellen.", completion = "Das Amulett von Razelikh dem Entweiher wurde wieder zusammengefügt, aber er spürt die Störung seiner Befehlskette. Er weiß, dass Ihr kommt...", sourceObjectiveStatus = "unverified-source-field" }
quests[3628] = { id = 3628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid Rakh'likh, Dämon", description = "Razelikhs Unterschlupf befindet sich auf dem Gipfel des höchsten Berges in den verwüsteten Landen. Einzig durch Einsatz der Teleport-Runen in der Nähe des Berges kann man zu diesem Unterschlupf gelangen. Solange Ihr das Amulett habt, könnt Ihr den Unterschlupf erreichen. Nachdem Ihr erst den Unterschlupf erreicht habt, müsst Ihr die Bestie herbeizaubern. Das Amulett ist Euer Schlüssel, {name}. Benutzt es auf dem Altar des Entweihers.\n\nFalls Ihr den Entweiher besiegen könnt, bringt sein Horn zurück. Es wird ein Symbol der Hoffnung für alle sein, die es sehen, ein Beweis dafür, dass es tatsächlich Helden in dieser vom Krieg zerrissenen Welt gibt.", sourceObjective = "Vernichtet Razelikh den Entweiher und bringt das abgespaltene Horn des Entweihers zum Gefallenen Helden der Horde. Ihr müsst außerdem den Zauberschutz des Entweihers mit zurückbringen, damit der Gefallene Held ihn zerstören und somit verhindern kann, dass er jemals in die falschen Hände fällt.", progress = "Es gibt nichts mehr zu fürchten.", completion = "Heute ist ein Tag, der bis in alle Ewigkeit unvergessen bleiben wird. Der dämonische Oberanführer der verwüsteten Lande ist endlich gefallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[3629] = { id = 3629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Ingenieurskunst", description = "Experten-Ingenieurskunst beinhaltet zwei unterschiedliche Disziplinen: für Gnome und für Goblins. Ich erwähne Goblin-Ingenieurskunst nur, weil ich ein fairer Lehrer bin. Sie machen gern Dinge, die in die Luft gehen und es ist ihnen dabei meistens egal, ob was im Weg herumsteht - auch wenn sie es selbst sind.\n\n{name}, lest diese Anleitung. Wenn Ihr lernen wollt, Euch selbst in die Luft zu jagen, dann bringt sie zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft, es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.", progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, {name}, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, {name}, und Ihr könnt vielleicht was lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3630] = { id = 3630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomen-Ingenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: für Gnome und für Goblins. Gnomen-Ingenieurskunst ist die weit Überlegenere der beiden! Es geht um die Konstruktion von wunderbaren Apparaten und Geräten, die das Leben schöner machen.\n\n{name}, lest diese Anleitung. Wenn Ihr mehr über Gnomen-Ingenieurskunst lernen wollt, dann bringt sie zu Tüftlermeister Overspark in Ironforge. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge.", progress = "Ja, ja, um welche Eurer Bedürfnisse darf ich mich heute bemühen? Ich habe ja offensichtlich Zeit dafür, da ich nur hier herumstehe, während unsere geliebte Stadt unter einer Wolke bestrahlten Todes liegt.", completion = "Ah, ein junger Ingenieur, der an der einen, wahren Disziplin der Ingenieurskunst interessiert ist! Entschuldigt meine Dramatik, Freund. Zwar ist unsere Lage immer noch sehr betrüblich, doch es ist immer ein guter Tag, wenn man einen weiteren Ingenieur findet, der dem Ruf der wahren Ingenieurskunst folgt!", sourceObjectiveStatus = "unverified-source-field" }
quests[3631] = { id = 3631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsross beschwören", description = "Hmpf. Ich sage, Ihr seid nicht vorbereitet, aber das ist nicht meine Entscheidung. Strahad empfindet das anders und es ist seine Entscheidung... dieses Mal.\n\nEr wünscht mit Euch zu sprechen, und das schnell. Ihr werdet ihn immer noch über Ratchet im Brachland finden, in seinem kleinen Turm dort, mit seinen Akolythen.\n\nTrödelt nicht herum.", sourceObjective = "Sprecht mit Strahad Farsan im Brachland.", completion = "Soso, Ihr habt also beschlossen, mich erneut mit Eurer Anwesenheit zu beehren. Wie nett von Euch.\n\nMeine Akolyten haben sich schon gefragt, ob Ihr jemals auftauchen würdet. Ich habe ihnen gesagt, daran bestünde kein Zweifel. Von der Macht werdet Ihr angezogen wie eine Motte vom Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[3632] = { id = 3632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomen-Ingenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: Gnom und Goblin. Gnomen-Ingenieurskunst ist die weit Überlegenere der beiden! Es geht um die Konstruktion von wunderbaren Apparaten und Geräten, die das Leben schöner machen.\n\n{name}, lest diese Anleitung. Wenn Ihr mehr über Gnomen-Ingenieurskunst lernen wollt, dann bringt sie zu Tüftlermeister Overspark hier in Ironforge. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge.", progress = "Ja, ja, um welche Eurer Bedürfnisse darf ich mich heute bemühen? Ich habe ja offensichtlich Zeit dafür, da ich nur hier herumstehe, während unsere geliebte Stadt unter einer Wolke bestrahlten Todes liegt.", completion = "Ah, ein junger Ingenieur, der an der einen, wahren Disziplin der Ingenieurskunst interessiert ist! Entschuldigt meine Dramatik, Freund. Zwar ist unsere Lage immer noch sehr betrüblich, doch es ist immer ein guter Tag, wenn man einen weiteren Ingenieur findet, der dem Ruf der wahren Ingenieurskunst folgt!", sourceObjectiveStatus = "unverified-source-field" }
quests[3633] = { id = 3633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin-Ingenieurskunst", description = "Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Natürlich ist die Goblin-Ingenieurskunst die Wahl aller brillanten Ingenieure. Durch den klugen Einsatz von hochempfindlichen Sprengstoffen und phantastischen Ausrüstungsgegenständen lernt Ihr, die Welt zu meistern!\n\n{name}, lest diese Anleitung. Wenn Ihr etwas über Goblin-Ingenieurskunst wissen wollt, dann bringt sie zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.", progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, {name}, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, {name}, und Ihr könnt vielleicht was lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3634] = { id = 3634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomen-Ingenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: für Gnome und für Goblins. Ich bin zwar der Meinung, dass es Verschwendung ist, aber Ihr solltet doch etwas über die Gnomen-Spezialisierung wissen. Sie machen Geräte und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.\n\n{name}, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Tüftlermeister Overspark in Ironforge. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[3635] = { id = 3635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomen-Ingenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen: Gnom und Goblin. Ich bin zwar der Meinung, dass es reine Verschwendung ist, aber Ihr solltet doch etwas über die Spezialisierung der Gnome wissen. Sie machen Gegenstände und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.\n\n{name}, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Oglethorpe Obnoticus in Booty Bay. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr mehr über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Oglethorpe Obnoticus nach Booty Bay.", progress = "Hallo! Wenn Ihr gekommen seid, um Euch über einen Leitroboter zu beschweren, der durch eine Wand Eures Domizils gebrochen ist, dann lasst mich Euch gleich zu meinem Anwalt weiterleiten. Anderenfalls, was kann ich heute für Euch tun?", completion = "Ihr seid gekommen, um die Gnomen-Ingenieurskunst zu erlernen, eh? Tja, da seid Ihr hier genau bei dem richtigen Gnom gelandet. Auch wenn die herrschende Fraktion in Gnomeregan die Politik benutzt, um diejenigen, die sie als intellektuelle Bedrohung sieht, zu ächten, wissen sie doch genau, dass Wissen ihrer Kontrolle nicht unterworfen werden kann.\n\nSie und ich wissen, dass sie einen ihrer größten noch lebenden Gnomen-Ingenieure verloren haben, als ich Gnomeregan verlassen habe. Wenn Ihr ein fähiger Student seid, werde ich Euch alles lehren, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[3636] = { id = 3636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht bringen", description = "Die Geißel ist eine dauerhafte Bedrohung für die Allianz. Ich bin sicher, Euch ist diese Tatsache vertraut. Kürzlich erst stießen wir auf einige sehr seltsame Funde, {name}.\n\nIm Brachland gibt es ein fürchterliches Dickicht von Dornsträuchern, das Hügel von Razorfen heißt. Früher war es die Heimat von einfachen Stachelebern, aber nun ist offensichtlich, dass ein Pakt mit der Geißel geschlossen wurde, die viel schlimmere Kreaturen hervorbrachte... Sie werden jetzt von dem Lich, Amnennar dem Kältebringer, beherrscht.\n\nStellt Euch auf die Seite des Lichts, {name}, und macht diesem bösen Verbund ein Ende.", sourceObjective = "Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln von Razorfen tötet.", completion = "Danke, {name}. Die Geißel wird es sich nun zweimal überlegen, bevor sie erneut versucht, ihre Reihen zu verstärken.\n\nMöge das Licht Euch segnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3637] = { id = 3637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomen-Ingenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen: Gnom und Goblin. Ich bin zwar der Meinung, dass es reine Verschwendung ist, aber Ihr solltet doch etwas über die Spezialisierung der Gnomen wissen. Sie machen Gegenstände und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.\n\n{name}, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Oglethorpe Obnoticus in Booty Bay. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr mehr über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Oglethorpe Obnoticus nach Booty Bay.", progress = "Hallo! Wenn Ihr gekommen seid, um Euch über einen Leitroboter zu beschweren, der durch eine Wand Eures Domizils gebrochen ist, dann lasst mich Euch gleich zu meinem Anwalt weiterleiten. Anderenfalls, was kann ich heute für Euch tun?", completion = "Ihr seid gekommen, um die Gnomen-Ingenieurskunst zu erlernen, eh? Tja, da seid Ihr hier genau bei dem richtigen Gnom gelandet. Auch wenn die herrschende Fraktion in Gnomeregan die Politik benutzt, um diejenigen, die sie als intellektuelle Bedrohung sieht, zu ächten, wissen sie doch genau, dass Wissen ihrer Kontrolle nicht unterworfen werden kann.\n\nSie und ich wissen, dass sie einen ihrer größten noch lebenden Gnomen-Ingenieure verloren haben, als ich Gnomeregan verlassen habe. Wenn Ihr ein fähiger Student seid, werde ich Euch alles lehren, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[3638] = { id = 3638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur der Geheimhaltung", description = "Bei der Goblin-Ingenieurskunst geht es um praktische Anwendungen mit hohem Profit und noch höherer Explosionskraft! Unsere Baupläne ermöglichen uns, mächtige Bomben und gewaltige Waffen hervorzubringen. Die Anleitung, die Ihr gelesen habt, berichtet darüber.\n\nDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Goblin-Ingenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Gnomen-Ingenieurskunst.\n\nWenn Ihr immer noch ein Goblin-Ingenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, {name}.", sourceObjective = "Wenn Ihr ein Goblin-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Nixx Sprocketspring in Gadgetzan sprechen.", progress = "Wenn Ihr das Dokument unterzeichnet habt und bereit seid, es mir zu übergeben, dann war's das. Ihr wisst, dass diese Reise nur in eine Richtung geht. Wenn Ihr bereit seid, dann kommt an Bord!", completion = "Willkommen an Bord, Goblin-Ingenieur {name}! Ihr werdet bald Zugang zu den mächtigsten Ingenieurskunst-Schemata in ganz Azeroth haben.\n\nNun, da Ihr Euch dem Erwerb dieses Wissens verschrieben habt, ist es Zeit, Eure Goblin-orientierten Ingenieursarbeiten zu begutachten. Von dort ausgehend, werden wir Euch helfen, einen Plan zu erstellen, Eure Goblin-Ingenieurstalente voll auszuschöpfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[3639] = { id = 3639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt Eure Arbeit", description = "Als Euer Mentor will ich Proben Eurer Arbeit sehen. Ihr seid ein geschickter Ingenieur, das steht ganz außer Frage, {name}. Ich möchte sie gern analysieren, um Möglichkeiten zu erarbeiten, Goblin-orientierte Techniken in Euren zukünftigen Bemühungen noch weiter zu unterstreichen. Ich brauche Folgendes: Zwanzig große Eisenbomben, zwanzig Stäbe robustes Dynamit und fünf explosive Schafe - und achtet darauf, dass sie gesichert sind!\n\nBringt mir diese Gegenstände und ich werde Euch Eure eigene Goblin-Ingenieur-Mitgliedskarte ausstellen, die notwendig ist, um Zugang zu allen Goblin-Ingenieurskunstlehrern zu erhalten!", sourceObjective = "Bringt 20 große Eisenbomben, 20 robuste Dynamitstangen und 5 explosive Schafe zu Nixx Sprocketspring nach Gadgetzan.", progress = "Sobald ich die von Euch gefertigten Ingenieurskunst-Gegenstände zur Ansicht erhalten habe, werde ich Euch eine echte Goblin-Ingenieur-Mitgliedskarte aushändigen. Solange die Karte gültig ist, habt Ihr unbegrenzten Zugang zu jedem Goblin-Ingenieurskunstlehrer auf der ganzen Welt.", completion = "Hier ist Eure erste Goblin-Ingenieur-Mitgliedskarte!\n\nDiese Karte wurde für vierzehn Tage im Voraus bezahlt; alle Karten laufen nach zwei Wochen Aktivität ab. Ist das geschehen, zahlt Ihr Euren nächsten Beitrag bei einem beliebigen Goblin-Ingenieurskunstlehrer ein, um eine weitere Karte zu erhalten. Ohne die Karte wird Eure Mitgliedschaft zeitweilig unterbrochen und Ihr habt keinen Zugriff auf neue Baupläne.\n\nDas hat natürlich keinen Einfluss auf das, was Ihr bereits wisst. Einmal Goblin-Ingenieur, immer Goblin-Ingenieur.", sourceObjectiveStatus = "unverified-source-field" }
quests[3640] = { id = 3640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur der Geheimhaltung", description = "Die Gnomen-Ingenieurskunst beruht auf der Ingenieurskunsttheorie, die besagt, dass sie unseren Bedürfnissen zu dienen hat! Unsere Baupläne ermöglichen uns, Geräte hervorzubringen, die die Welt um uns kontrollieren. Die Anleitung, die Ihr gelesen habt, berichtet darüber.\n\nDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Gnomen-Ingenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Goblin-Ingenieurskunst.\n\nWenn Ihr immer noch ein Gnomen-Ingenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, {name}.", sourceObjective = "Wenn Ihr ein Gnomen-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Tüftlermeister Overspark in Ironforge sprechen.", progress = "Wenn Ihr das Dokument unterzeichnet habt und bereit seid, es mir zu übergeben, dann war's das.\n\nDie Geheimnisse, die ich mit Euch teilen werde, sind von solcher Bedeutung, dass der Schwur der Geheimhaltung ein absolutes Muss ist. Ich habe ein solches Dokument unterschrieben, genau wie alle Gnomeningenieure. Ihr werdet einer viel versprechenden Zunft beitreten, Ingenieur {name}!", completion = "Willkommen an Bord, {name}! Ihr werdet bald Zugang zu den am höchsten entwickelten Ingenieurskunst-Schemata in ganz Azeroth haben.\n\nNun, da Ihr Euch dem Erwerb dieses Wissens verschrieben habt, ist es Zeit, Eure Gnomen-orientierten Ingenieursarbeiten zu begutachten. Von dort ausgehend, werden wir Euch helfen, einen Plan zu erstellen, Eure Gnomen-Ingenieurstalente voll auszuschöpfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[3641] = { id = 3641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt Eure Arbeit", description = "Als Euer Mentor will ich einige Proben Eurer Arbeit sehen. Ihr seid ein geschickter Ingenieur, das steht ganz außer Frage, {name}. Ich möchte Eure Arbeit daher analysieren, um Möglichkeiten zu erarbeiten, Gnomen-orientierte Techniken in Euren zukünftigen Bemühungen noch weiter zu fördern. Ich brauche folgende Proben: 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen.\n\nBringt mir diese Gegenstände und ich werde Euch Eure höchsteigene Gnomen-Ingenieur-Mitgliedskarte ausstellen, die notwendig ist, um Zugang zu allen Gnomen-Ingenieurskunstlehrern zu erhalten!", sourceObjective = "Bringt 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Tüftlermeister Overspark in Ironforge.", progress = "Sobald ich Eure gefertigten Ingenieurskunst-Gegenstände zur Ansicht erhalten habe, werde ich Euch eine echte Gnomen-Ingenieur-Mitgliedskarte aushändigen. Solange die Karte gültig ist habt Ihr unbegrenzten Zugang zu jedem Gnomen-Ingenieurskunstlehrer auf der ganzen Welt.", completion = "Hier ist Eure erste Gnomen-Ingenieur-Mitgliedskarte!\n\nDiese Karte wurde für vierzehn Tage im Voraus bezahlt; alle Karten laufen nach zwei Wochen Aktivität ab. Ist das geschehen, zahlt Ihr Euren nächsten Beitrag bei einem beliebigen Gnomen-Ingenieurskunstlehrer ein, um eine weitere Karte zu erhalten. Ohne die Karte wird Eure Mitgliedschaft zeitweilig unterbrochen und Ihr habt keinen Zugriff auf neue Baupläne.\n\nDas hat natürlich keinen Einfluss auf das, was Ihr bereits wisst. Einmal Gnomen-Ingenieur, immer Gnomen-Ingenieur.", sourceObjectiveStatus = "unverified-source-field" }
quests[3642] = { id = 3642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur der Geheimhaltung", description = "Die Gnomen-Ingenieurskunst beruht auf der Ingenieurskunsttheorie, die besagt, dass sie unseren Bedürfnissen zu dienen hat! Unsere Baupläne ermöglichen uns, Geräte hervorzubringen, die die Welt um uns kontrollieren. Die Anleitung, die Ihr gelesen habt, berichtet darüber.\n\nDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Gnomen-Ingenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Goblin-Ingenieurskunst.\n\nWenn Ihr immer noch ein Gnomen-Ingenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, {name}.", sourceObjective = "Wenn Ihr ein Gnomen-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Oglethorpe in Booty Bay sprechen.", progress = "Wenn Ihr das Dokument unterzeichnet habt und bereit seid, es mir zu übergeben, dann war's das.\n\nObwohl meine politische Überzeugung sich extrem von der in Gnomeregan vorherrschenden unterscheidet - besonders von der dieses Dummkopfes, Tüftlermeister Overspark -, geht doch der Schwur der Geheimhaltung über alles! Ihr müsst Euch einem einzigen Weg verschreiben und diesem Weg Euer ganzes Leben lang treu ergeben bleiben.", completion = "Willkommen an Bord, {name}! Ihr werdet bald Zugang zu den am höchsten entwickelten Ingenieurskunst-Schemata in ganz Azeroth haben.\n\nNun, da Ihr Euch dem Erwerb dieses Wissens verschrieben habt, ist es Zeit, Eure Gnomen-orientierten Ingenieursarbeiten zu begutachten. Von dort ausgehend, werden wir Euch helfen, einen Plan zu erstellen, Eure Gnomen-Ingenieurstalente voll auszuschöpfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[3643] = { id = 3643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt Eure Arbeit", description = "Als Euer Mentor will ich einige Proben Eurer Arbeit sehen. Ihr seid ein geschickter Ingenieur, das steht ganz außer Frage, {name}. Ich möchte Eure Arbeit daher analysieren, um Möglichkeiten zu erarbeiten, Gnomen-orientierte Techniken in Euren zukünftigen Bemühungen noch weiter zu fördern. Ich brauche folgende Proben: 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen.\n\nBringt mir diese Gegenstände und ich werde Euch Eure höchsteigene Gnomen-Ingenieur-Mitgliedskarte ausstellen, die notwendig ist, um Zugang zu allen Gnomen-Ingenieurskunstlehrern zu erhalten!", sourceObjective = "Bringt 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Oglethorpe Obnoticus in Booty Bay.", progress = "Sobald ich Eure gefertigten Ingenieurskunst-Gegenstände zur Ansicht erhalten habe, werde ich Euch eine echte Gnomen-Ingenieur-Mitgliedskarte aushändigen. Solange die Karte gültig ist habt Ihr unbegrenzten Zugang zu jedem Gnomen-Ingenieurskunstlehrer auf der ganzen Welt.", completion = "Hier ist Eure erste Gnomen-Ingenieur-Mitgliedskarte!\n\nDiese Karte wurde für vierzehn Tage im Voraus bezahlt; alle Karten laufen nach zwei Wochen Aktivität ab. Ist das geschehen, zahlt Ihr Euren nächsten Beitrag bei einem beliebigen Gnomen-Ingenieurskunstlehrer ein, um eine weitere Karte zu erhalten. Ohne die Karte wird Eure Mitgliedschaft zeitweilig unterbrochen und Ihr habt keinen Zugriff auf neue Baupläne.\n\nDas hat natürlich keinen Einfluss auf das, was Ihr bereits wisst. Einmal Gnomen-Ingenieur, immer Gnomen-Ingenieur.", sourceObjectiveStatus = "unverified-source-field" }
quests[3644] = { id = 3644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitgliedskarten-Erneuerung", progress = "Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen.", completion = "Da Ihr praktizierender Goblin-Ingenieur seid und einen guten Ruf habt, kann ich eine abgelaufene Mitgliedskarte gegen die Gebühr von zwei Goldstücken erneuern. Sobald diese Gebühr entrichtet wurde, werdet Ihr eine neue Mitgliedskarte erhalten. Diese wird Euch Zugang zu Goblin-Ingenieurskunst-Bauplänen von geeigneten Lehrern gewähren.\n\nDiese Karte ist gültig für zwei Wochen Aktivität, danach wird Eure Mitgliedsgebühr erneut fällig! Wenn Ihr Zugang zu Bauplänen benötigt, müsst Ihr Euren Beitrag begleichen." }
quests[3645] = { id = 3645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitgliedskarten-Erneuerung", progress = "Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen.", completion = "Da Ihr praktizierender Gnomen-Ingenieur seid und einen guten Ruf habt, kann ich eine abgelaufene Mitgliedskarte gegen die Gebühr von zwei Goldstücken erneuern. Sobald diese Gebühr entrichtet wurde, werdet Ihr eine neue Mitgliedskarte erhalten. Diese wird Euch Zugang zu Gnomen-Ingenieurskunst-Bauplänen von geeigneten Lehrern gewähren.\n\nDiese Karte ist gültig für zwei Wochen Aktivität, danach wird Eure Mitgliedsgebühr erneut fällig! Wenn Ihr Zugang zu Bauplänen benötigt, müsst Ihr Euren Beitrag begleichen." }
quests[3646] = { id = 3646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitgliedskarten-Erneuerung", description = "[\n]", progress = "Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen.", completion = "Da Ihr praktizierender Goblin-Ingenieur seid und einen guten Ruf habt, kann ich eine abgelaufene Mitgliedskarte gegen die Gebühr von zwei Goldstücken erneuern. Sobald diese Gebühr entrichtet wurde, werdet Ihr eine neue Mitgliedskarte erhalten. Diese wird Euch Zugang zu Goblin-Ingenieurskunst-Bauplänen von geeigneten Lehrern gewähren.\n\nDiese Karte ist gültig für zwei Wochen Aktivität, danach wird Eure Mitgliedsgebühr erneut fällig! Wenn Ihr Zugang zu Bauplänen benötigt, müsst Ihr Euren Beitrag begleichen." }
quests[3647] = { id = 3647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitgliedskarten-Erneuerung", progress = "Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen.", completion = "Da Ihr praktizierender Gnomen-Ingenieur seid und einen guten Ruf habt, kann ich eine abgelaufene Mitgliedskarte gegen die Gebühr von zwei Goldstücken erneuern. Sobald diese Gebühr entrichtet wurde, werdet Ihr eine neue Mitgliedskarte erhalten. Diese wird Euch Zugang zu Gnomen-Ingenieurskunst-Bauplänen von geeigneten Lehrern gewähren.\n\nDiese Karte ist gültig für zwei Wochen Aktivität, danach wird Eure Mitgliedsgebühr erneut fällig! Wenn Ihr Zugang zu Bauplänen benötigt, müsst Ihr Euren Beitrag begleichen." }
quests[3661] = { id = 3661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Lieblinge?", description = "Wildekins sind unberechenbare Kreaturen, {name}. Sie sind zu einer außerordentlichen Zärtlichkeit fähig, aber diese Kreaturen können auch eine enorme Wildheit an den Tag legen, wenn etwas für sie sehr Wichtiges bedroht wird.\n\nDiese Kreaturen wurden angeblich von Elune geschaffen und ich bin daran interessiert herauszufinden, ob dies wirklich der Wahrheit entspricht.\n\nVor kurzem habe ich etwas von einer Population von Wildekins gehört, die im Hinterland leben - heimtückische, primitive und wilde Eulenbestien. Man findet sie unter den wild lebenden Tieren dort. Würdet Ihr einige Wildekin-Federn für mich sammeln?", sourceObjective = "Sammelt 15 Wildekinfedern aus dem Hinterland für Erelas Ambersky in Rut'theran.", progress = "Versucht, ihnen möglichst aus dem Weg zu gehen, {name}. Die Wildekin könnten Euer Interesse missverstehen und denken, Ihr habt vor, sie zu verletzen...", completion = "Danke, dass Ihr sie mir gebracht habt, {name}.\n\nWas habt Ihr über die Wildekin erfahren können?\n\nVielleicht werden uns diese Federn mehr sagen. Wilde Monster oder einfach fehlgeleitete Tiere? Eines Tage möchte ich die Wahrheit kennen...\n\nIch werde meine Forschungen fortsetzen - kommt zu mir zurück und sprecht erneut mit mir, nachdem einige Zeit vergangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[3681] = { id = 3681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Offenbarung", description = "Verzeiht, dass wir Eure Reise unterbrechen, {race}, aber ich dachte, Ihr solltet wissen, dass uns vor kurzem eine Meldung aus Stormwind erreicht hat, dass sich Paladine zum Training dort melden sollen.\n\nWenn ich es nicht besser wüsste, würde ich sagen, dass bald etwas Besonderes geschehen wird und es für Euch an der Zeit ist, die Folianten zu studieren.\n\nSucht Duthorian Rall in Stormwind auf. Er trainiert für gewöhnlich Paladine in der Kathedrale des Lichts.", sourceObjective = "Sprecht mit Duthorian Rall in Stormwind.", completion = "Willkommen in der Kathedrale des Lichts, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[3701] = { id = 3701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die glimmenden Ruinen von Thaurissan", description = "Begebt Euch zu den glimmenden Ruinen von Thaurissan in der brennenden Steppe und sammelt so viele Informationen wie möglich.\n\nEs heißt, dass geheimnisvolle Relikte in den Ruinen verstreut seien. Vielleicht solltet Ihr Eure Suche dort beginnen, {name}. Nehmt Euch vor den Thaurissan-Wächtern in Acht: Es sind Auftragsmörder, die die Ruinen bewachen und die dort möglicherweise noch immer begrabenen Geheimnisse beschützen, wie auch immer sie aussehen mögen.", sourceObjective = "Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt.", progress = "Bringt Ihr neue Informationen?", completion = "Oh je! Diese Informationen erklären einiges in Bezug auf Thaurissan.\n\nEs gibt ja noch so viel mehr zu erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[3702] = { id = 3702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die glimmenden Ruinen von Thaurissan", description = "Würdet Ihr gern einen Überblick über die Geschichte der Dunkeleisenzwerge erhalten?", sourceObjective = "Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan.", progress = "Erlaubt mir, Euch die Geschichte von Thaurissan zu Ende zu erzählen.", completion = "Sollen wir fortfahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[3721] = { id = 3721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein eigener OOX", sourceObjective = "Ihr habt drei meiner OOX-Leitroboter gefunden! Ihr habt viel mehr als das getan, worum ich Euch gebeten hatte. Daher will ich Euch etwas Besonderes für Eure Hilfe geben. Dies ist eine Miniaturversion jenes Roboters, den Ihr jetzt kennt und liebt, den OOX!\n\nIch würde normalerweise niemandem solch ein potenziell tödliches Gerät anvertrauen, aber Ihr wart eine wirklich große Hilfe. Außerdem wurden die Kampfmechanismen und die Leitlogik dieses Exemplars deaktiviert.\n\nAber abgesehen davon ist das ein echter OOX!", sourceObjectiveStatus = "unverified-source-field" }
quests[3741] = { id = 3741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilarys Halskette", description = "Meine Freundin Hilary hat ihre Halskette verloren und wir können sie einfach nicht finden. Den ganzen Tag lang fischen wir schon hier und haben auch schon rundum überall gesucht. Ich kann mir nur vorstellen, dass sie in den See gefallen ist. Unsere Eltern möchten nicht, dass wir im See schwimmen... meine Mama sagt, dass es unter Wasser ein paar garstige Dinge gibt, aber Ihr seht aus, als ob Ihr keine Angst vor garstigen Dingen hättet.\n\nKönnt Ihr die Kette bitte für uns suchen?", sourceObjective = "Sucht Hilarys Halskette und bringt sie Hilary in Seenhain zurück.", progress = "Hallo! Ich vermisse meine Halskette. Mein Papa hat sie mir geschenkt. Papa sagt, dass es Monster im See gibt. Habt Ihr irgendwelche Monster verhauen?", completion = "Vielen Dank, dass Ihr meine Halskette gefunden habt, lieber {class}... Ihr seid sehr gütig! Auch mein Kätzchen dankt Euch... nicht wahr, Effsee?", sourceObjectiveStatus = "unverified-source-field" }
quests[3761] = { id = 3761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Un'Goro-Erde", description = "Die Erde des Un'Goro Kraters ist angeblich reich an starken magischen Eigenschaften. Der Zirkel des Cenarius möchte diese Erde in großen Mengen untersuchen; zieht daher in die Wildnis von Un'Goro und sammelt genug davon für unsere ständig laufenden Forschungen.\n\nDie angereicherte Erde ist manchmal zu Haufen aufgeworfen und einige der Wildtiere könnten vielleicht nützliche Proben bei sich haben. Bringt sie raus zu Ghede; sucht einfach nach den Erdhaufen und dem Tauren, der Befehle brüllt. Er ist kein schlechter Kerl, aber verärgert ihn lieber nicht!", sourceObjective = "Bringt 20 Un'Goro-Erdproben zu Ghede in Thunder Bluff.", progress = "Rühren, Gefreiter. Wenn Ihr hier seid, um Erde aus Un'Goro abzuladen - hervorragend! Anderenfalls verschwindet.", completion = "Oh, macht's Euch ruhig bequem, Gefreiter {name}. Bemüht Euch bloß nicht, mir zu helfen, diese Erde auf die Haufen da zu schaufeln! Wenn die großen Geister gewollt hätten, dass sie da hinkommt, hätten sie die dort bestimmt hinaufgezaubert, nicht wahr?!\n\nErzdruide Runetotem möchte erneut mit Euch sprechen, aber Ihr werdet feststellen, dass für seine nächste Aufgabe das Wissen eines Gesellen der Kräuterkunde hilfreich wäre. Falls Ihr nicht über dieses Wissen verfügt, wird er trotzdem Verwendung für Euch finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[3762] = { id = 3762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide Runetotem helfen", description = "Entschuldigung, {class}, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Thunder Bluff ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runetotem an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Thunder Bluff.", sourceObjective = "Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem.", completion = "Seid gegrüßt, {class}; ich freue mich, dass Ihr daran interessiert seid, an unseren Forschungen teilzunehmen. Es gibt viel zu tun und ich würde Euch einen schlechten Dienst erweisen, wenn ich Euch sagen würde, dass die Arbeit, die dies mit sich bringt, ungefährlich sei. Hoffentlich erschreckt Euch das nicht ... aber so, wie Ihr ausseht, würde ich sagen, dass Ihr schon früher der Gefahr ins Auge geblickt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3763] = { id = 3763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide Staghelm helfen", description = "Entschuldigung, {class}, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Staghelm an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", sourceObjective = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.", completion = "Nun gut, {class}... da Ihr informiert wurdet, dass ich dieses Forschungsprojekt selbst leite, seid Ihr offensichtlich so schnell Ihr konntet gekommen.\n\nNachdem Ihr nun hier seid, folgt meinen Ausführungen, wenn ich die Einzelheiten erläutere, bitte mit voller Konzentration; ich möchte mich nicht wiederholen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3764] = { id = 3764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Un'Goro-Erde", description = "Die Erde des Un'Goro Kraters ist angeblich reich an starken magischen Eigenschaften. Ich möchte Wahrheit von Unwahrheit unterscheiden; begebt Euch daher in die Wildnis von Un'Goro und sammelt ausreichend hochwertige Erdproben für unsere ständig laufenden Studien.\n\nIhr glaubt möglicherweise, dass die Aufgabe, etwas zu sammeln, unter Eurer Würde sei; doch mit solch einer Einstellung macht Ihr Euch weder bei mir noch beim Zirkel des Cenarius beliebt. Bringt die Proben zu Jenal, der zweifellos draußen hinter diesem Baum müßig herumlungert; sucht einfach nach den Erdhaufen. Er wird sich um die Logistik kümmern, nicht ich.", sourceObjective = "Bringt 20 Un'Goro-Erdproben zu Jenal in Darnassus.", progress = "Ach ja, die Erde. Der Erzdruide möchte zwanzig Ladungen pro Abenteurer, und zwanzig Ladungen wird er bekommen. Lasst die, die gegen uns konspirieren, auf der Strecke bleiben!", completion = "Ladet Eure wertvolle Fracht hier ab, edler {class}. Es muss eine rechte Bürde gewesen sein... ähnlich der Bürde, die ich als Visionär mit mir herumtrage. Hier ist eine Entlohnung für Eure Arbeit, wie es der Erzdruide höchstpersönlich angewiesen hat.\n\nErzdruide Staghelm möchte erneut mit Euch sprechen, {name}, aber für seine nächste Aufgabe wäre Euch geholfen, wenn Ihr über das Wissen eines Gesellen der Kräuterkunde verfügt. Falls Ihr nicht über dieses Wissen verfügt, werdet Ihr dennoch hilfreich für den Zirkel sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[3765] = { id = 3765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis in der Fremde", description = "Stormwind - geschäftiger Dreh- und Angelpunkt der Aktivität.\n\nIch bin weit gereist, um Hilfe zu suchen. Man hört häufig, dass mutige Abenteurer durch die Straßen dieser Stadt ziehen.\n\nMein Bruder Gershala benötigt Hilfe in Dunkelküste. Er lebt in der Küstenstadt Auberdine.\n\nDie Reise ist lang und abenteuerlich. Daher suche ich nach Hilfe. Es sollte ein erfahrener {class} sein, so wie Ihr.", sourceObjective = "Reist zu Gershala Nightwhisper in Auberdine.", completion = "Ah, mein Bruder Argos hat Euch also zu mir geschickt? Ich nehme an, Ihr seid müde von Eurer Reise. Aber wir müssen über vieles sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3781] = { id = 3781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkornforschung", description = "Mit dem, was wir einen Immergrünbeutel nennen, haben wir Tharlendrissamenkörner in der Erde vom Un'Goro Krater kultiviert. Diese Samenkörner sind zu einer Ansammlung wirksamer Kräuter erblüht. Ein Ergebnis ist das Morgenkorn, ein rätselhaftes Kraut, von dem wir wenig wissen; ich habe vor, dieses Geheimnis zu enthüllen.\n\nBringt das nach unten zu Mathrengyl, und er wird Euch einige Samenkörner geben, mit denen Ihr beginnen könnt. Wenn Ihr diese verbraucht habt, müsst Ihr weitere von ihm kaufen.", sourceObjective = "Bringt den Samenkorngutschein des Erzdruiden zu Mathrengyl Bearwalker in der Enklave des Cenarius von Darnassus.", progress = "Friede und Klarheit seien mit Euch, Freund. Ihr seid im Auftrag des Erzdruiden höchstpersönlich hier, nicht wahr?", completion = "Ja, dieser Gutschein ist gültig für zwanzig Pakete mit Samenkörnern. Wenn Ihr die verbraucht habt, kein Problem, bei uns gibt es noch mehr. Leider ist es aber recht kostspielig, Tharlendrissamenkörner in großer Zahl zu produzieren. Daher bittet der Zirkel des Cenarius diejenigen, die uns helfen, einen Teil der Kosten auszugleichen.\n\nDiejenigen, die mit Morgenkorn zurückkehren, werden feststellen, dass die Belohnung, die der Erzdruide bietet, die Kosten mehr als wettmacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[3782] = { id = 3782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkornforschung", description = "Mit dem, was wir einen Immergrünbeutel nennen, haben wir Tharlendrissamenkörner in der Erde vom Un'Goro Krater kultiviert. Diese Samenkörner sind zu einer Ansammlung wirksamer Kräuter erblüht. Ein Ergebnis ist das Morgenkorn, ein rätselhaftes Kraut, von dem wir wenig wissen; ich hoffe, dieses Geheimnis für den Zirkel zu enthüllen.\n\nBringt diesen Gutschein zu meiner Tochter Bashana, und sie wird Euch einige Samenkörner geben, damit Ihr uns helfen könnt. Wenn Ihr diese verbraucht habt, müsst Ihr weitere von ihr kaufen.", sourceObjective = "Bringt den Samenkorngutschein zu Bashana Runetotem in Thunder Bluff.", progress = "Friede mit dir, Freund. Ihr seid im Auftrag des Erzdruiden höchstpersönlich hier, nicht wahr?", completion = "Ja, dieser Gutschein ist gültig für zwanzig Pakete mit Samenkörnern. Wenn Ihr die Samenkörner verbraucht habt, habe ich noch mehr, die ich Euch verkaufen kann.\n\nLeider ist es aber recht kostspielig, {name}, Tharlendrissamenkörner in großer Zahl zu produzieren. Daher bittet der Zirkel des Cenarius diejenigen, die uns helfen, einen Teil der Kosten auszugleichen. Diejenigen, die mit Morgenkorn zurückkehren, werden feststellen, dass die Belohnung, die der Erzdruide bietet, die Kosten mehr als wettmacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[3783] = { id = 3783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sind wir endlich da, Yeti?", description = "Meine Freunde hatten immerzu tolle Ideen. Ich hatte nie das Gefühl mit ihnen mithalten zu können... bis heute! Gerade habe ich die Pläne für etwas Großes angefertigt! Wenn Ihr versprecht, es nicht zu erzählen, weihe ich Euch in das Geheimnis ein... \n\nIch werde einen mechanischen Yeti herstellen! Meine Freunde werden ganz bestimmt durchdrehen, wenn sie ihn sehen, aber wenn sie darüber hinweg sind, bin ich mir sicher, dass sie beeindruckt sein werden!\n\nFür den Anfang benötige ich dickes Yetifell von Eisdistelyetis. Werdet Ihr helfen? Ihr könnt sie im Südosten finden.", sourceObjective = "Sammelt 10 dicke Yetifelle für Umi Rumplesnicker in Everlook.", progress = "Ich habe hier viel zu tun. Bitte, besorgt mir diese Felle, so schnell Ihr könnt!", completion = "Diese Felle sind perfekt, {name}. Damit haben wir einen guten Anfang!", sourceObjectiveStatus = "unverified-source-field" }
quests[3784] = { id = 3784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide Runetotem helfen", description = "Entschuldigung, {class}, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Thunder Bluff ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runetotem an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Thunder Bluff.", sourceObjective = "Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem.", completion = "Seid gegrüßt, {class}; ich freue mich, dass Ihr daran interessiert seid, an unseren Forschungen teilzunehmen. Es gibt viel zu tun und ich würde Euch einen schlechten Dienst erweisen, wenn ich Euch sagen würde, dass die Arbeit, die dies mit sich bringt, ungefährlich sei. Hoffentlich erschreckt Euch das nicht... aber so, wie Ihr ausseht, würde ich sagen, dass Ihr schon früher der Gefahr ins Auge geblickt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3785] = { id = 3785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkornforschung", description = "Hier ist Euer Immergrünbeutel, den Ihr für die Nutzung der Tharlendrissamenkörner benötigen werdet. Ihr benötigt außerdem noch Un'Goro-Erdproben als Dünger für die Samenkörner. Verwendet einfach den Beutel, wenn Ihr alles habt; der Beutel wird den Rest erledigen.\n\nWenn Ihr genug Einheiten Morgenkorn habt, bringt sie mir hierher in die Enklave. Und belästigt bitte nicht den Erzdruiden; er ist ein sehr beschäftigter Mann und muss nicht jedes Mal gestört werden, wenn jemand mit einer Ladung Morgenkorn zurückkehrt!", sourceObjective = "Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Un'Goro-Erdproben, um Morgenkorn zu kultivieren.\n\nBringt 10 Einheiten Morgenkorn zu Mathrengyl Bearwalker in Darnassus.", progress = "Also, {name}, habt Ihr Morgenkorn für die wichtigen Forschungen des Erzdruiden gezüchtet? Die Arbeit, die er für den Zirkel des Cenarius leistet, ist sehr wichtig und Eure Hilfe wird nicht unbemerkt bleiben!", completion = "Gut gemacht, {name}, ich werde sie dem Erzdruiden geben, wenn er sie benötigt. Nehmt dies in der Zwischenzeit als Zeichen der Wertschätzung des Zirkels des Cenarius.\n\nWir benötigen fortlaufend Morgenkorn; wenn Ihr uns auch weiterhin helfen wollt, dann kehrt bitte zu mir zurück, sobald Ihr weiteres Morgenkorn kultiviert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3786] = { id = 3786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkornforschung", description = "Hier ist Euer Immergrünbeutel, den Ihr für die Nutzung der Tharlendrissamenkörner benötigen werdet. Ihr benötigt außerdem noch Un'Goro-Erdproben als Dünger für die Samenkörner. Verwendet einfach den Beutel, wenn Ihr alles habt; der Beutel wird den Rest erledigen.\n\nWenn Ihr genug Einheiten Morgenkorn habt, bringt sie zu mir hierher auf die Anhöhe der Ältesten. Belästigt bitte nicht den Erzdruiden; er wird sehr mit den Forschungsarbeiten beschäftigt sein sowie mit den tausend anderen Sorgen, die er hat!", sourceObjective = "Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Un'Goro-Erdproben, um Morgenkorn zu kultivieren.\n\nBringt 10 Einheiten Morgenkorn zu Bashana Runetotem in Thunder Bluff.", progress = "Also, {name}, habt Ihr Morgenkorn für die wichtigen Forschungen des Erzdruiden gezüchtet? Die rätselhaften Eigenschaften des Un'Goro Kraters werden dank Eurer Hilfe mit jedem Tag klarer.", completion = "Gut gemacht, {name}, ich werde sie dem Erzdruiden geben, wenn er sie benötigt. Nehmt dies in der Zwischenzeit als Zeichen der Wertschätzung des Zirkels des Cenarius.\n\nWir benötigen im Moment fortlaufend Morgenkorn; wenn Ihr uns auch weiterhin helfen wollt, dann kehrt bitte zu mir zurück, sobald Ihr weiteres kultiviert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3787] = { id = 3787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jonespyres Bitte", description = "Entschuldigung...\n\nEin Kollege von mir würde gern mit Euch über die Forschungsarbeiten sprechen, die Ihr zusammen mit dem Zirkel des Cenarius durchführt. Er ist ein Druide namens Quintis Jonespyre und lebt in der Festung Feathermoon in Feralas. Er würde gern mit Euch über Morgenkorn reden... und er würde es vorziehen, wenn unser Gespräch dem Erzdruiden nicht zu Ohren kommt.\n\nFalls Ihr interessiert seid, dann sprecht mit ihm; zweifellos wird alles klargelegt, wenn Ihr es tut.", sourceObjective = "Sprecht mit Quintis Jonespyre in der Festung Feathermoon.", completion = "Ich danke Euch für Euer Kommen, müder Reisender! Erlaubt mir, mich vorzustellen - ich bin Quintis Jonespyre, Druide und bescheidener Diener von Malfurion und dem Zirkel des Cenarius. Meine Kollegen (General Shandris Feathermoon und das Protektorat - vielleicht habt Ihr schon von uns gehört) und ich möchten mit Euch über die Arbeit sprechen, die Ihr für Fandral Staghelm in Darnassus erledigt.\n\nBevor wir weitermachen, möchte ich Euch jedoch bitten, unser Gespräch für Euch zu behalten. Wenn Ihr damit kein Problem habt, dann können wir fortfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[3788] = { id = 3788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jonespyres Bitte", description = "Entschuldigung...\n\nEin Kollege von mir würde gern mit Euch über die Forschungsarbeiten sprechen, die Ihr zusammen mit dem Zirkel des Cenarius durchführt. Er ist ein Druide namens Quintis Jonespyre und lebt hier in der Festung Feathermoon. Er würde gern mit Euch über Morgenkorn reden... und er würde es vorziehen, wenn unser Gespräch dem Erzdruiden nicht zu Ohren kommt.\n\nFalls Ihr interessiert seid, dann sprecht mit ihm; zweifellos wird alles klargelegt, wenn Ihr es tut.", sourceObjective = "Sprecht mit Quintis Jonespyre in der Festung Feathermoon.", completion = "Ich danke Euch für Euer Kommen, müder Reisender! Erlaubt mir, mich vorzustellen - ich bin Quintis Jonespyre, Druide und bescheidener Diener von Malfurion und dem Zirkel des Cenarius. Meine Kollegen (General Shandris Feathermoon und das Protektorat - vielleicht habt Ihr schon von uns gehört) und ich möchten mit Euch über die Arbeit sprechen, die Ihr für Fandral Staghelm in Darnassus erledigt.\n\nBevor wir weitermachen, möchte ich Euch jedoch bitten, unser Gespräch für Euch zu behalten. Wenn Ihr damit kein Problem habt, dann können wir fortfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[3789] = { id = 3789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide Staghelm helfen", description = "Entschuldigung, {class}, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Staghelm an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", sourceObjective = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.", completion = "Nun gut, {class}... da Ihr informiert wurdet, dass ich dieses Forschungsprojekt selbst leite, seid Ihr offensichtlich so schnell Ihr konntet gekommen.\n\nNachdem Ihr nun hier seid, folgt meinen Ausführungen, wenn ich die Einzelheiten erläutere, bitte mit voller Konzentration; ich möchte mich nicht wiederholen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3790] = { id = 3790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide Staghelm helfen", description = "Entschuldigung, {class}, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Staghelm an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", sourceObjective = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.", completion = "Nun gut, {class}... da Ihr informiert wurdet, dass ich dieses Forschungsprojekt selbst leite, seid Ihr offensichtlich so schnell Ihr konntet gekommen.\n\nNachdem Ihr nun hier seid, folgt meinen Ausführungen, wenn ich die Einzelheiten erläutere, bitte mit voller Konzentration; ich möchte mich nicht wiederholen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3791] = { id = 3791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des Morgenkorns", description = "Lasst mich offen mit Euch sein, {name}. Ich bin interessiert zu wissen - nein, ich muss es unbedingt wissen, warum der Erzdruide in Darnassus den Namen des Zirkels des Cenarius sowie dessen Mittel benutzt, um große Mengen Morgenkorn zu beschaffen. Ich bin ein Forscher - Flüche sind meine Spezialität. Ich habe gehört, dass Morgenkorn unter den richtigen Bedingungen Fähigkeiten verströmt wie andere Kräuter, die in primitiven Flüchen eingesetzt werden.\n\nIch möchte mehr darüber wissen und bitte Euch um Eure Hilfe. Bringt mir 10 Einheiten Morgenkorn und ich werde mich um Euch kümmern.", sourceObjective = "Bringt 10 Einheiten Morgenkorn zu Quintis Jonespyre in der Festung Feathermoon.", progress = "Ich benötige zehn Einheiten Morgenkorn - das sollte genügen, um meine Forschungen zumindest in Gang zu bringen. Zweifellos werde ich etliche davon beim Verfolgen falscher Spuren verbrauchen, aber das liegt in der Natur der Forschung.", completion = "Gah, durch dieses Morgenkorn fühle ich mich... merkwürdig. Was in Elunes Namen will Staghelm mit diesen Dingern?\n\nEgal, nochmals danke für Eure Hilfe. Hier habt Ihr eine Kleinigkeit... Ihr wisst schon, für Eure Mühe. Meine Forschungen zum Thema Morgenkorn werden einige Zeit dauern, und ich werde zweifellos mehr davon benötigen. Wo ich gerade dabei bin: Ich denke, ich könnte die Zeit vielleicht nutzen um herauszufinden, ob Morgenkorn eine brauchbare alchimistische Verwendung hat. Trotzdem fühle ich mich in seiner Umgebung äußerst unwohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[3792] = { id = 3792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkorn für die Festung Feathermoon", progress = "Abermals hallo, {name}. Meine Forschung macht gute Fortschritte, aber wenn Ihr fünf weitere Einheiten Morgenkorn habt, würde ich Euch die sehr gern abnehmen. Na ja... 'gern' ist nicht wirklich der richtige Ausdruck dafür; je länger ich mich in seiner Umgebung befinde, desto unwohler fühle ich mich. Aber für meine Forschungen ist es nun mal nötig, dass ich mich zusammenreiße und weiterarbeite.", completion = "Vielen Dank, {name}; ich werde das erst einmal zu meinem Vorrat legen. Und wenn ich auch nicht über die Mittel wie Staghelm verfüge, so bin ich doch in der Lage, Euch etwas für Eure Bemühungen zu geben. Denn schließlich, wer kann schon wissen, was geschehen wird, wenn Staghelm Morgenkorn um Morgenkorn bekommt. Hier geht etwas Merkwürdiges vor sich, denkt an meine Worte.\n\nVergesst nicht, dass ich immer nach weiterem Morgenkorn suche. Ich nehme Euch immer jeweils fünf Einheiten ab." }
quests[3801] = { id = 3801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkeleisenerbe", description = "Seid gegrüßt, {name}. Ich bin Franclorn Forgewright. Ja, der Franclorn Forgewright, der für die Stonewrought-Methode der Architektur verantwortlich ist. Ihr habt zweifellos während Eurer Abenteuer in unserer vom Krieg zerrissenen Welt eines meiner Werke durchquert oder habt auf einem gestanden.\n\nIhr fragt Euch wahrscheinlich, warum ich hier bin und was ich von Euch möchte - beides berechtigte Fragen.\n\nIch brauche natürlich Eure Hilfe. Im Austausch für Eure Hilfe gewähre ich Euch den Schlüssel zu den Tiefen meiner verfluchten Stadt.", sourceObjective = "Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten.", completion = "Ganz gleich, ob es Gier oder ein Akt selbstloser Hingabe ist, der Euch hierher geführt hat, was immer Ihr unternehmt, wird zu unserem Wohle sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[3802] = { id = 3802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkeleisenerbe", description = "Ihr findet Fineous Darkvire jenseits des Rings des Gesetzes in der Halle des Handwerks. Tötet den elenden Wicht und nehmt Ironfel an Euch.\n\nBringt Ironfel zum Schrein von Thaurissan und legt den Hammer an seinen rechtmäßigen Ort: in die Hände der Statue, die mir zu Ehren aufgestellt wurde.\n\nSobald dieses getan ist, öffnet sich das Fach, in dem ich den Hauptschlüssel verborgen habe. Wichtiger jedoch ist: Ironfel wird für alle Zeiten in meinen Händen bleiben. Sollte jemand versuchen, den Hammer zu entfernen, werden Statue und Hammer bersten und für immer verloren sein.", sourceObjective = "Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright.", progress = "Die Statue ragt bedrohlich über Euch auf.", completion = "Der Hammer gleitet sicher an seinen Platz, in greifbarer Nähe des massiven Monuments der Dunkeleisenzwerge. Am Fundament der Statue öffnet sich ein winziges Fach. Darin findet Ihr...", sourceObjectiveStatus = "unverified-source-field" }
quests[3803] = { id = 3803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkorn nach Darnassus", progress = "Der Erzdruide sucht ständig nach mehr Morgenkorn für die weiteren Forschungsarbeiten des Zirkels des Cenarius. Wir nehmen jeweils zehn Einheiten ab und belohnen Euch mit umfangreichen Dingen, die Ihr nützlich finden werdet. Wenn Ihr zehn Einheiten habt, lasst es mich wissen, und ich werde Euch entsprechend belohnen.", completion = "Hervorragend - dieses Morgenkorn wird den Erzdruiden zweifellos erfreuen. Ich muss aber zugeben... allein seine Nähe bereitet mir ein unangenehmes Gefühl. Ich kann mir gar nicht vorstellen, wie schwierig es für den Erzdruiden ist, es in so großer Menge zu ertragen!\n\nDas ist für Euch, {name}. Der Zirkel des Cenarius dankt Euch für Eure unermüdliche Unterstützung." }
quests[3804] = { id = 3804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkorn nach Thunder Bluff", progress = "Der Erzdruide sucht ständig nach mehr Morgenkorn für das Forschungsprojekt des Zirkels des Cenarius über den Un'Goro Krater. Wir nehmen jeweils zehn Einheiten ab und belohnen Euch mit umfangreichen Dingen, die Ihr nützlich finden werdet. Wenn Ihr zehn Einheiten habt, lasst es mich wissen, und ich werde Euch entsprechend belohnen.", completion = "Hervorragend - dieses Morgenkorn wird zweifellos hilfreich sein, wenn die Zeit kommt. Wir wissen, dass die Nachtelfen ähnliche Forschungen über dieses Kraut durchführen, obwohl es nicht klar ist, wie sie sie nutzen werden, wenn sie etwas herausfinden. Der Erzdruide meint, dass wir so lange Morgenkorn benötigen werden, bis wir das Geheimnis hinter diesem Kraut gelüftet haben.\n\nDas ist für Euch, {name}. Der Zirkel des Cenarius dankt Euch für Eure unermüdliche Unterstützung." }
quests[3821] = { id = 3821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckensfels", description = "Sha'ni wurde ausgeschickt, um Berichte über merkwürdige rituelle Aktivitäten zu untersuchen, die vor mehr als drei Wochen von den Feuermagenogern der brennenden Steppe kamen.\n\nGoretooth sagt mir, dass er noch nichts wieder von dieser Gruppe gehört hätte und dass es am besten sei, wenn ich einfach weitermache und mich auf meine Aufgabe konzentriere. Könnt Ihr Euch das vorstellen? Das ist doch meine Frau!\n\nIch kann meinen Posten nicht verlassen, {name}, aber ich muss wissen, was aus Sha'ni geworden ist. Reist in die brennende Steppe und sucht nach ihr.", sourceObjective = "Begebt Euch in die brennende Steppe und findet heraus, was aus Sha'ni Proudtusk geworden ist.", completion = "Mein armer Thal'trak.\n\nWir hatten vor, zu meinen Eltern ins Hinterland zu ziehen, sobald unsere Dienstzeit abgeleistet war. Jetzt sind unsere Pläne ruiniert!", sourceObjectiveStatus = "unverified-source-field" }
quests[3822] = { id = 3822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krom'Grul", description = "Meine ganze Gruppe wurde gefangen genommen, {name}. Alle wurden getötet - alle, außer mir.\n\nIhr Anführer Krom'Grul wollte mich für irgendein Ritual aufsparen.\n\nIch wurde von dem Biest an diesen Altar gekettet und brutal misshandelt. Mein körperliches Sein gab nach einer Stunde dieser Folter auf. Die Bestie riss mir dann meinen Ehenasenring aus dem Gesicht und steckte ihn an seinen Finger. Noch niemals habe ich solch eine Rohheit gesehen!\n\nFindet Krom'Grul und erledigt ihn! Bringt meinen Ring zurück zu Thal'trak.\n\nUnd, {name}, sagt ihm, dass wir uns wiedersehen werden ... in einem anderen Leben.", sourceObjective = "Holt Sha'nis Nasenring von Krom'Grul zurück und bringt ihn zu Thal'trak in Kargath. Durchsucht die verschiedenen Höhlen und Minen im Schreckensfels.", progress = "Habt Ihr Sha'ni gefunden? Geht es ihr gut?", completion = "<Thal'trak bricht zusammen.>\n\nWir wollten ins Hinterland ziehen. Hat sie Euch das schon erzählt? Das sollte ihre letzte Mission sein.\n\n<Thal'trak schluchzt.>\n\nIch will ihn nicht, {name}. Behaltet ihn, werft ihn weg, es ist mir egal! Der Ring hat keine Bedeutung mehr für mich. Nicht ohne sie ...", sourceObjectiveStatus = "unverified-source-field" }
quests[3823] = { id = 3823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Feuermagenoger auslöschen", description = "Wir müssen unsere Feinde schlagen, bevor sie uns schlagen!\n\nIch werde es kurz machen, Soldat.\n\nDie Feuermagenoger der brennenden Steppe sind Verbündete der Orcs des Blackrockklans. Sie arbeiten eng mit diesen üblen Orcs zusammen, bewachen den mineralreichen Schreckensfels und halten die Nachschublinien ständig offen.\n\nHinterlasst Euer Zeichen, {name}. Legt ihre Streitkräfte lahm und kehrt zu mir zurück, wenn der Auftrag erledigt ist.\n\n<Oralius greift in die Luft und macht eine erwürgende Bewegung.>\n\nICH BRING DICH UM, WINKY!", sourceObjective = "Tötet 15 Ogermagier der Feuermägen, 7 Oger der Feuermägen sowie 7 Schläger der Feuermägen und kehrt zu Oralius zurück, wenn Ihr fertig seid.", progress = "Es ist nicht annähernd genug Blut auf Eurer Uniform, Soldat!", completion = "Hervorragend, Soldat! Die Orcs und Oger werden von diesem Schlag minutenlang, vielleicht sogar stundenlang gelähmt sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[3824] = { id = 3824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gor'tesh der Schläger-Lord", description = "Sie sind gelähmt, ich sag's Euch! Unser nächster Schlag muss entscheidend sein.\n\nDer Lord dieser Bestien, Gor'tesh, muss eliminiert werden. Wichtiger noch, sein Kopf muss zu mir zurückgebracht werden, damit ich die dritte Phase unseres Angriffs auf die Feuermagenoger vorbereiten kann.\n\nSeid gewarnt, Soldat, Gor'tesh regiert nicht vom Schreckensfelsen aus. Stattdessen befindet er sich in einem Gebäude der Blackrockorcs westlich vom Schreckensfelsen.\n\nEure Befehle sind daher einfach. Sucht Gor'tesh und hackt ihm seinen fetten Kopf ab. Kommt zurück, wenn Eure Aufgabe erledigt ist.\n\nKLAPPE HALTEN, WINKY!", sourceObjective = "Sucht Gor'tesh irgendwo im Westen des Schreckensfelsens. Tötet Gor'tesh und bringt dann seinen abgehackten Kopf zu Oralius in der brennenden Steppe zurück.", progress = "Welch wunderbarer Tag! Seid Ihr mit dem Kopf zurückgekehrt?", completion = "Seht Euch das an, Soldat. Widerlich! Wenn die verbleibenden Feuermagenoger diese fette Visage auf einem Pfahl aufgespießt sehen, der auf der Spitze ihres Berges steht, wird es zu einer Massenhysterie kommen!\n\n<Oralius kichert wild.>", sourceObjectiveStatus = "unverified-source-field" }
quests[3825] = { id = 3825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerkopf auf einem Pfahl = Party", description = "Jetzt müsst Ihr nur noch eine Sache erledigen, Soldat.\n\nIch habe mir die Freiheit genommen, Gor'teshs Kopf auf einen Pfahl zu stecken. Ihr sollt jetzt einfach diesen Kopf zur Spitze des Schreckensfelsens bringen und ihn in den Boden rammen. Wenn Ihr das getan habt, seht zu, wie diese feigen Oger um ihr Leben rennen! Nachdem Ihr Euren Spaß hattet, kommt zu mir zurück und ich werde Euch für all Eure harte Arbeit belohnen.\n\n<Oralius scheint seinen Bezug zur Realität zu verlieren.>", sourceObjective = "Nehmt Gor'teshs abgehackten Kopf und platziert ihn auf dem Gipfel des Schreckensfelsens. Sucht nach einem weichen Erdhügel, um den Pfahl aufzustellen.", progress = "Und? Habt Ihr von dem Ereignis Bilder gemalt?", completion = "Hervorragende Arbeit, Soldat! Einfach unglaublich! Oh, ich werde dafür die Tapferkeitsmedaille bekommen, äh, ich meine, Ihr werdet fürstlich dafür belohnt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[3841] = { id = 3841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waise sucht Zuhause", description = "Ach, hallo, {name}. Ich freue mich sehr, Euch wiederzusehen. Wie war Eure Reise nach Darnassus?\n\nNa, Ihr seid bestimmt froh darüber, dass wir während Eurer Abwesenheit ziemliche Fortschritte gemacht haben. Wir haben sogar ein ganzes Nest voller Eier gerettet. Leider ist die Mutter gestorben, ehe wir sie gefunden haben.\n\nSagt mal, wollt Ihr nicht vielleicht so ein Tierchen haben? Es sieht aus, als würden sie bald schlüpfen, und dann brauchen sie <einen guten Vater/eine gute Mutter>. Was meint Ihr?\n\nWenn Ihr wirklich Interesse habt, dann bringt eines der Eier zu Quentin. Ihr findet ihn an der Rennbahn in der schimmernden Ebene. Er kann Euch mehr darüber sagen.", sourceObjective = "Sprecht mit Quentin in Tausend Nadeln.", progress = "Ja, hallo, {class}.\n\nLasst Euch nicht von meinem Aufenthaltsort täuschen, ich bin nicht wegen der Rennen hier... so unterhaltsam sie auch sein mögen.\n\nEigentlich bin ich hier in Tausend Nadeln, um so gut es geht zu untersuchen, was von dem Land hier noch zu retten ist. Es ist gewissermaßen eine heilige Mission geworden, die Gegend mit neuem, fruchtbaren Boden wiederzubeleben. Vielleicht finde ich ja hier in der Nähe eine Wasserquelle.\n\nIst Euch eigentlich aufgefallen, wie eigenartig der Übergang zwischen Feralas und Tausend Nadeln ist? Ganz seltsame Magie muss im Spiel gewesen sein, als das passiert ist.", completion = "Ah, ein Grimmlingflitzerei, und noch dazu eines, dessen Ausreifung bald vollendet sein wird, wenn ich mich nicht irre. Erstaunlich, dass Ihr eines gefunden habt, und noch dazu eines, das sich in einem so guten Zustand befindet. So etwas sieht man in Feralas nur noch selten heutzutage. Wie mir zu Ohren kam, sind etliche Wilderer hier in der Gegend gewesen, um diese Wesen aus den unterschiedlichsten Gründen zu fangen und zu töten. Ich verstehe das nicht... es sind so wunderschöne Geschöpfe, wenn sie ausgewachsen sind.\n\nWie seid Ihr nur an einen solchen Fund geraten?", sourceObjectiveStatus = "unverified-source-field" }
quests[3842] = { id = 3842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurz vor dem Schlüpfen", description = "Die Moonweavers, wie? Überaus interessant. Schade, dass die Grimmlingflitzer nicht schätzen können, was es bedeutet, wenn diese beiden sich um sie kümmern. Beide sind überaus fähig und gut.\n\nSoso, sie haben Euch das Ei also geschenkt. Tja, dann solltet Ihr auch so lange dafür verantwortlich sein, wie Ihr dies wünscht. Das Junge scheint wohl schon bald zu schlüpfen, aber wir sollten trotzdem sichergehen, dass es gesund ist und keinen Schaden genommen hat.\n\nIch brauche lediglich zwei Elixiere der Seelenstärke für einen kleinen Zauber, der das Ei beschützen wird. Die übrigen Komponenten habe ich bereits hier.", sourceObjective = "Bringt 2 Elixiere der Seelenstärke zu Quentin in Tausend Nadeln.", progress = "Je länger ich hier bin, desto mehr überkommt mich die Lust, an diesen Rennen teilzunehmen, {name}. Einfach überwältigend...\n\nHabt Ihr die Elixiere schon gefunden? Sobald ich sagen kann, ob das Ei gesund ist oder nicht, gebe ich es Euch zurück, damit Ihr es aufbewahrt, bis es schlüpft.\n\nSagt mir einfach Bescheid.", completion = "Großartig. Die sind perfekt. Gebt mir einen Augenblick, damit ich die Komponenten miteinander vermischen kann, und dann werden wir ja sehen, wie sich dieses Ei einmal machen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[3843] = { id = 3843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das neueste Mitglied der Familie", description = "Ein prachtvolles Exemplar, {name}. Wenn dieses Geschöpf das Heranreifen übersteht, dann wird es ein wahrhaft gesundes Tier sein!\n\nAber eines würde ich Euch noch vorschlagen, wenn Ihr es damit wirklich ernst meint - geht zum Aerie Peak im Hinterland. Sprecht dort mit einem Zwerg namens Agnar Beastamer. Er ist ein Tierführermeister und kann Euch bestimmt bei den letzten Stadien der Brutzeit behilflich sein.\n\nAber eilt Euch, {name}, das Ei ist empfindlich und wird sich ohne die richtige Pflege nicht lange halten.", sourceObjective = "Bringt Euer empfindliches Grimmlingflitzerei ins Hinterland und sprecht mit Agnar Beastamer, aber beeilt Euch. Ihr habt nur eine Stunde Zeit, ihn zu finden. Dann stirbt das Jungtier in dem Ei.", progress = "Seid gegrüßt, {name}. Kann ich Euch mit irgendwas helfen?", completion = "Ja, was haben wir denn hier? So etwas hab ich ja schon seit Ewigkeiten nicht mehr gesehen! Feendrache, wenn ich mich nicht irre... und zwar ein Grimmlingflitzer, wie's aussieht. Ausgezeichnet, ganz ausgezeichnet.\n\nNa, wenn der kleine Kerl hier schlüpfen und mal ein starker und gesunder Flitzer werden soll, dann sollten wir ihm was zu essen beschaffen. Gut, dass Ihr's mir grad noch rechtzeitig gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3844] = { id = 3844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist für jeden ein Geheimnis", description = "In Ufernähe liegt ein zerstörtes Floß. Das hier ist nur ein kleiner Tümpel, deswegen ist Euch nicht so ganz klar, wie das Floß hier landen konnte. Aber ein Blick auf die Bäume verrät Euch, dass der Wasserstand im Teich nicht unbedingt immer derselbe sein muss.\n\nVielleicht findet Ihr ja mehr heraus, wenn Ihr Euch ein bisschen in der Gegend umschaut ...", sourceObjective = "Sucht in dem Tümpel nach einem Hinweis darauf, wem dieses havarierte Floß gehören könnte.", completion = "Am Grund des Tümpels liegt ein durchnässtes Bündel.", sourceObjectiveStatus = "unverified-source-field" }
quests[3845] = { id = 3845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist für jeden ein Geheimnis", description = "Ihr greift nach dem Bündel und zieht es an Land. Vielleicht findet Ihr heraus, wem es gehört, wenn Ihr die Gegenstände darin untersucht.\n\nIn Marshals Zuflucht halten sich ein paar vereinzelte Reisende auf. Vielleicht lässt sich dort ja mehr herausfinden.", sourceObjective = "Untersucht die Gegenstände in dem Bündel und bringt sie zu ihrem Besitzer.", progress = "Hallo, Ihr da! Euch hab ich doch schon mal gesehen... Oder nicht?", completion = "Oh... Ja, die Sachen kommen mir bekannt vor... irgendwie schon...", sourceObjectiveStatus = "unverified-source-field" }
quests[3861] = { id = 3861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GLUCK!", description = "Gack... gack... gack... GAGGACK!\n\nGack... gack... gack.\n\nDas Huhn sieht zu Euch hinauf und beginnt dann, mit seinen Krallen am Boden zu scharren. Ihr glaubt, dass es ein Wort schreibt, aber Ihr seid Euch nicht sicher, was es ist. Könnte es das sein... S-A-L-D-E-A-N? Bevor Ihr fragen könnt, dreht sich das Huhn weg und kümmert sich um seine Angelegenheiten.", sourceObjective = "Beschafft Euch etwas Spezial-Hühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /cheer, ehe Ihr dem Huhn das Spezial-Hühnerfutter gebt.", progress = "Das Huhn starrt Euch mit dunklen, kalten Augen an. Hungrig wartet es auf Euch.\n\n\"GAGGAAACK!\n\nGack... gack... gack.\"", completion = "GAGGACK!!!\n\nDas Huhn beginnt gierig, das Futter aufzupicken, das Ihr ihm hingestreut habt.\n\nNach einer kurzen Weile sieht es sich überrascht um. Dann trippelt es unruhig vor und zurück. Ob dieses Huhn vielleicht gleich ein Ei legt? Vielleicht solltet Ihr besser einmal darunter nachsehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3881] = { id = 3881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungsexpedition", description = "Ich weiß zwar nicht, wie Ihr es bis hierher geschafft habt, aber Ihr seid Balsam für meine Augen! Ich heiße Williden Marshal und bin der Leiter eines neutralen Expeditionstrupps. Unsere jüngste und größte Unternehmung wurde von zahllosen Katastrophen begleitet. Die schlimmste davon war, dass wir die Wildheit des Un'Goro Kraters unterschätzt hatten.\n\nAls wir aus unseren Stützpunkten im südwestlichen und nordöstlichen Teil des Kraters flohen, ließen wir lebenswichtige Vorräte zurück. Ihr seht aus, als wärt Ihr recht stark und geschickt ... Könnt Ihr uns vielleicht dabei helfen, sie zurückzubekommen?", sourceObjective = "Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marshal im Un'Goro Krater.", progress = "Wenn wir auch nur die geringste Chance haben wollen, hier lebendig rauszukommen, dann brauchen wir unsere große Kiste mit Nahrungsmitteln. Und zumindest einen Teil unserer Forscherausrüstung zurückzubekommen, das wäre ein Segen in diesem Meer des Elends.", completion = "Ihr habt ja sogar beides wiederbeschafft: unsere Nahrungsmittel UND unsere Forscherausrüstung! Ihr habt nicht nur die Expedition gerettet, sondern auch unser aller Leben. Mein Team und ich können Euch gar nicht genug danken; Euretwegen können wir jetzt wenigstens eine Zeit lang weitermachen.\n\nWir haben zwar nicht viel, aber ich werde Euch bestimmt nicht auf dem Trockenen sitzen lassen als Dank für die unschätzbare Hilfe, die Ihr uns erwiesen habt! Danke, {name}, Ihr habt jetzt einen Freund bei Marshals Expeditionen!", sourceObjectiveStatus = "unverified-source-field" }
quests[3882] = { id = 3882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenklappern", description = "Man sollte meinen, dass ich gern grabe, nur weil ich der Oberbuddler von Marshals Expeditionen bin. Es könnte schlimmere Dinge in der Welt geben... auch wenn mir gerade keines einfällt.\n\nJedenfalls sollten wir eigentlich in der Terrorflucht - PHANTASTISCHER Name übrigens - nach toten Stegodons und Dimetrodons graben. Na ja, es treiben sich von der Sorte auch noch eine Menge lebende Viecher dort herum! Wil und Hol beschäftigen sich immer mit dieser Todesfalle, daher benötigen wir diese Dinosaurierknochen. Obwohl, unter uns gesagt, wenn Ihr mir welche von einem lebenden Exemplar bringt, dann ist das genauso gut.", sourceObjective = "Bringt 8 Dinosaurierknochen zu Spark Nilminer im Un'Goro Krater.", progress = "Ihr könnt von mir denken, was Ihr wollt, aber denen ist es doch völlig egal, ob die Knochen, die sie zum Erforschen bekommen, von uralten Stegodons und Dimetrodons stammen oder von den Viechern, die uns beinahe zum Frühstück verspeist hätten, als wir gerade unser Lager aufschlugen. Ich wäre schon glücklich, wenn wir hier lebend rauskämen...", completion = "Wunderbar, das sollte funktionieren. Und jetzt, wenn Ihr erlaubt...\n\nDANKE, DASS IHR ALL DIESE KNOCHEN FÜR UNS AUSGEGRABEN HABT, OHNE DEN HIER LEBENDEN TIEREN SCHADEN ZUZUFÜGEN!\n\nOb das wirklich so war oder nicht, das will ich gar nicht wissen. Belassen wir es dabei, in Ordnung? Hier - vielleicht hilft Euch das, über die ganze Angelegenheit Euren Mund zu halten. Jedes Mittel ist recht, wenn wir nur lebendig hier rauskommen, sage ich!", sourceObjectiveStatus = "unverified-source-field" }
quests[3883] = { id = 3883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine fremdartige Ökologie", description = "Nur weil wir einen Rückschlag erlitten haben, heißt das noch lange nicht, dass unsere Forschungen ein Ende finden müssen! Bevor wir hier gelandet sind, untersuchten wir die Schwarmbauten der Gorishiinsekten im südlichen Teil des Kraters. Sie sind fremdartig und passen nicht zur ursprünglichen Ökologie des Un'Goro und wir wollen herausfinden, warum das so ist.\n\nIn ihrem Schwarmbauverbund muss es Larvenbrutstätten geben. Ihr könnt diesen Ort an der hängenden Raupenbrut erkennen. Hier, nehmt mit dieser Phiole eine Probe von der Schwarmbauwand in der Nähe der Brutstätten. Bringt sie dann zu mir zurück, damit ich sie untersuchen kann, aber seid vorsichtig!", sourceObjective = "Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Un'Goro Krater zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut.\n\nBringt die Schwarmbauwandprobe zu Hol'anyee Marshal im Un'Goro Krater.", progress = "Habt Ihr die Probe des Gorishischwarmbaus, damit ich sie untersuchen kann, {name}?", completion = "Ja, die ist prima. Ihr wart mir eine große Hilfe... Ich wünschte, ich könnte Euch mehr geben als das hier, aber wenn man mitten in einer primitiven Gegend festsitzt, dann schränkt einen das in seinen Möglichkeiten schon ein bisschen ein. Eines ist jedoch sicher: Die Forschungsarbeit, die hier geleistet wird, wäre ohne Eure Hilfe nicht möglich!", sourceObjectiveStatus = "unverified-source-field" }
